MAX_CALLGRAPH_DEPTH = 4

MAX_CALLGRAPH_NODES = 60

def _cg_site_rel(from_rel):
    """返回从某源码页目录到「站点根」的相对路径前缀（用于拼接节点 href）。

    关键：源码页一律位于站点根下的 src/ 子目录（src/<rel>.html），因此到站点根
    需要的层数 = rel 的路径段数（含 src/ 这一层）。例如：
      from_rel='a/b.m' → 页面在 src/a/b.m.html（目录 src/a/），到站点根需上 2 级
                         → '../../'；
      from_rel='main.m' → 页面在 src/main.m.html（目录 src/），到站点根需上 1 级
                         → '../'。
    此前实现少算 src/ 这一层（用 len(parts)-1），导致跨文件跳转 href 变成
    src/src/... 而找不到文件，本次修正为 len(parts)。"""
    parts = from_rel.split("/") if from_rel else []
    depth = len(parts)
    return "../" * depth

def _rel_to_src_asset(from_rel, asset):
    """源码页内指向 src/ 目录下共享资源（如 _cgdata.js）的相对链接。"""
    parts = from_rel.split("/") if from_rel else []
    depth = max(0, len(parts) - 1)
    return ("../" * depth) + asset





# P270 R4：可访问性 / 键盘导航层（全站注入）。
#   提供：① ? 帮助浮层（列出全部快捷键）；② Esc 关闭任意浮层；
#   ③ 全局快捷键：t 主题 / g 跳概览 / h 跳首页 / d 跳重复代码 / / 命令面板；
#   ④ 浮层打开时焦点锁定 + 关闭后焦点归还；⑤ 跳转到主内容（skip link 由模板提供）。
# 与 GLOBAL_SEARCH_JS 的 Ctrl+K 互不冲突（搜索浮层优先消费按键）。

# P271 R3：源码行深链（代码可分享视图）。
# ① 解析 URL 的 #Lx 或 #Lx-y，高亮对应源码行并滚动入视；② 点击行号单元格即可复制
# 「当前文件 URL#Lx」分享链接（navigator.clipboard 不可用时回退到临时 textarea）。
# P271 R3（步骤3）：通用视图状态深链 —— 把页面控件状态同步到 URL hash。
# 与 DEEPLINK_JS（全局状态页专用）不同，这里是**声明式、可复用**的：
# 页面只需在 window.__VIEWSTATE_SPEC__ 里声明「控件 id → hash 键 → 默认值 → 变更回调」，
# 本脚本统一负责「URL → 控件」还原与「控件 → URL」同步，任何页面都能低成本接入。
# 例：index.html#cgmin=2&cglbl=1 分享出去，对方打开即为「只看高扇入 + 显示全部标签」的视图。

def _render_callgraph_host(f, direction, gid_of):
    """生成单个函数的「按需下钻」调用图容器（占位 div）；真实 SVG 由前端
    initLocalCG 依据 window.__CG__ 全局邻接表渲染，支持点击节点上的 +/- 徽标
    展开 / 折叠其被调（callee）或被调用（caller）子树，彻底消除旧实现的深度截断。"""
    gid = gid_of.get(id(f))
    if gid is None:
        return ""
    return ('<div class="cg-host" data-dir="%s" data-root="%d"></div>'
            % (direction, gid))


_CG_CACHE = {}



# === R9 修复：从 renderers/hotspot.py 移回的分析层辅助（被 analysis 代码调用） ===

def _build_global_cg(files, fn_to_file, calls_of, callers_of, model=None,
                     max_nodes=None):
    """构建前端「按需下钻」调用图所需的全局邻接表（一次分析仅构建一次，跨页缓存复用）。

    P201 深度变革：在原有「函数级调用图」(meta/down/up) 基础上扩展为**统一图谱 v2**——
    新增 folder / file / variable 三类一等节点，以及 contain / flow 两类新边：
      cg_json：JSON 文本 {meta, down, up, contain, flow}
        meta[gid] = {n, r, k, l, p, ...}  k ∈ main|local|method|constructor|script
                    |folder|file|variable
        down[gid] / up[gid]：函数级调用/被调用（不变）
        contain[gid]：归属/包含边（folder→file、file→fn、folder→folder）
        flow[gid]   ：变量数据流边（var→fn 读/写、fn→var 定义/污点、var→var 污点传递）
    返回 (cg_json, gid_of)：gid_of 兼容旧调用（id(fn)->gid），并额外含 id(folder/file/var)->gid。

    meta 不依赖页面位置（源码页路径 p 已是站点根相对，href 由前端按各页 SITE_REL
    拼接），故可安全跨页缓存。前端 initLocalCG 依据此全局邻接表，默认仅展开根 + 直接子
    一层，点击节点 +/- 徽标即可增量下钻。

    P203 --max-nodes：节点数硬上限。超出时按「folder>file>function>variable」优先级
    保留高价值节点，截断低价值的变量节点（最高占大头），保证 300+ 文件仓库仍可渲染。
    """
    # 跨页缓存：单次分析内 calls_of 为同一对象，多次调用命中；不同分析的
    # calls_of 虽可能复用同一 id，但对象不同（is 校验失败）不命中，避免脏缓存。
    # P205-2：缓存键含 max_nodes，使得「同一代码库 + 任意 max_nodes」的截断视图
    # 均被缓存（首次构建完整图后，不同 max_nodes 切换直接命中，免重复构建/排序）。
    # 完整图构建是主要开销，本设计已满足 300+ 文件仓库的重复渲染性能目标。
    _cache_key = (id(calls_of), max_nodes)
    _cached = _CG_CACHE.get(_cache_key)
    if _cached is not None and _cached[0] is calls_of:
        return _cached[1]
    import json as _json
    gid_of = {}
    meta = []
    dup_map = _dup_candidates(files)   # P52：同名函数候选（就近解析可视化）

    # P147：风险标志位阈值（与热点分析 P23 保持同量级口径）
    _HOT_COMPLEXITY = 15
    _HOT_INDEG = 6
    # 污点流函数集合（rel, func）——用于 meta.fl.t（无数据则为空）
    taint_set = set()
    # P201：变量级污点集合（rel, varname）——用于变量节点 fl.t 高亮
    _taint_vars = set()
    try:
        for _fl in (getattr(files, "taint", None) or {}).get("flows", []) or []:
            taint_set.add((str(_fl.get("rel", "")), str(_fl.get("func", ""))))
            for _v in (_fl.get("vars") or _fl.get("var_sources") or []):
                if _v:
                    _taint_vars.add((str(_fl.get("rel", "")), str(_v)))
    except Exception:
        taint_set = set()
        _taint_vars = set()

    def reg(fn):
        key = id(fn)
        g = gid_of.get(key)
        if g is None:
            g = len(meta)
            gid_of[key] = g
            tmf = fn_to_file.get(key)
            rel = tmf.rel if tmf is not None else ""
            # P52：同名候选列表（含当前函数自身），供预览弹窗「同名函数候选」区块展示
            # P80：候选补 p（站点根相对源码页路径），使候选可点击跳转/切换解析目标
            dups = None
            cands = dup_map.get(fn.name.lower())
            if cands:
                dups = [{"r": cmf.rel, "l": cf.line, "k": cf.kind, "self": cf is fn,
                         "p": ("src/" + _page_rel(cmf.rel)) if cmf.rel else ""}
                        for (cf, cmf) in cands]
            meta.append({
                "n": fn.name,
                "r": rel,
                "k": fn.kind,
                "l": fn.line,
                "p": ("src/" + _page_rel(rel)) if rel else "",
                "d": (fn.header.get("description", "") if isinstance(getattr(fn, "header", None), dict) else "")
                      or "",   # 函数简要说明（P18：悬停 / caption 展示）
                "cx": getattr(fn, "complexity", 0) or 0,   # P29：圈复杂度（节点悬浮详情卡片展示）
                "sig": (fn.signature() if hasattr(fn, "signature") else fn.name),   # P36：函数签名（点击预览展示）
                "snip": _fn_src_snip(fn),   # P37：函数源码片段（预览面板展示）
                "body": getattr(fn, "body_start", fn.line + 1) or (fn.line + 1),   # P37：函数体首行（快速定位）
                "dups": dups,   # P52：同名候选（>1 时非 None）
                # P147：风险标志位（供函数搜索结果/节点着色快速判读）
                #   t: 含污点流(0/1)  w: 含未初始化告警(0/1)  hd: 高复杂度(0/1)
                #   hi: 高扇入(被依赖度高,0/1)  TODO 由前端据 cx 阈值动态补
                "fl": {
                    "t": 1 if (taint_set and (rel, fn.name) in taint_set) else 0,
                    "hd": 1 if (fn.complexity or 0) >= _HOT_COMPLEXITY else 0,
                    "hi": 1 if len(callers_of.get(id(fn), [])) >= _HOT_INDEG else 0,
                },
            })
        return g

    down = {}
    up = {}
    contain = {}
    flow = {}
    # 文件/文件夹节点注册表（key 用稳定字符串，避免与函数 id 冲突）
    _folder_gid = {}
    _file_gid = {}
    _var_gid = {}

    def reg_file(rel):
        key = "file:" + str(rel)
        g = _file_gid.get(key)
        if g is None:
            g = len(meta)
            _file_gid[key] = g
            d = os.path.dirname(str(rel).replace(os.sep, "/"))
            meta.append({
                "n": os.path.basename(str(rel)), "r": str(rel), "k": "file",
                "l": 0, "p": ("src/" + _page_rel(str(rel))) if rel else "",
                "d": "", "cx": 0, "sig": "", "snip": "", "body": 0, "dups": None,
                "fl": {"t": 0, "hd": 0, "hi": 0},
            })
            # 文件归属文件夹（folder→file contain 边）
            fg = reg_folder(d) if d else None
            if fg is not None:
                contain.setdefault(fg, [])
                if g not in contain[fg]:
                    contain[fg].append(g)
        return g

    def reg_folder(d):
        if not d:
            return None
        key = "folder:" + d
        g = _folder_gid.get(key)
        if g is None:
            g = len(meta)
            _folder_gid[key] = g
            meta.append({
                "n": d.split("/")[-1] or d, "r": d, "k": "folder",
                "l": 0, "p": ("dir.html?d=" + d) if d != "(root)" else "dir.html",
                "d": "", "cx": 0, "sig": "", "snip": "", "body": 0, "dups": None,
                "fl": {"t": 0, "hd": 0, "hi": 0},
            })
            # 父文件夹→本文件夹（folder→folder contain 边）
            parent = os.path.dirname(d)
            if parent and parent != d:
                pg = reg_folder(parent)
                if pg is not None:
                    contain.setdefault(pg, [])
                    if g not in contain[pg]:
                        contain[pg].append(g)
        return g

    def reg_var(vkey, name, rel, owner_gid, kind, line, tainted, reads, writes):
        g = _var_gid.get(vkey)
        if g is None:
            _vt = tainted or ((str(rel), str(name)) in _taint_vars)
            g = len(meta)
            _var_gid[vkey] = g
            meta.append({
                "n": name, "r": rel, "k": "variable", "l": line,
                "p": ("src/" + _page_rel(rel) + "#L" + str(line)) if rel else "",
                "d": "", "cx": 0, "sig": "", "snip": "", "body": line, "dups": None,
                "fl": {"t": 1 if _vt else 0, "hd": 0, "hi": 0, "uninit": 1 if tainted else 0},
            })
            # contain：owner 函数 → 变量（文件→函数边在下方面向 fn 节点建立）
            if owner_gid is not None:
                contain.setdefault(owner_gid, [])
                if g not in contain[owner_gid]:
                    contain[owner_gid].append(g)
            # flow：变量 ↔ 拥有函数（读/写）
            if owner_gid is not None:
                flow.setdefault(g, [])
                flow[g].append(owner_gid)
                flow.setdefault(owner_gid, [])
                if g not in flow[owner_gid]:
                    flow[owner_gid].append(g)
        return g

    for mf in files:
        fg = reg_file(mf.rel)
        for f in mf.functions:
            g = reg(f)
            # file → fn contain 边
            contain.setdefault(fg, [])
            if g not in contain[fg]:
                contain[fg].append(g)
            callees = calls_of.get(id(f), [])
            down[g] = [reg(cf) for (cf, _tm) in callees]
            callers = callers_of.get(id(f), [])
            up[g] = [reg(cf) for cf in callers]
    # P201：变量节点（来自 model.variables，与 P200 缓存同源）
    _vars = getattr(model, "variables", None) if model is not None else None
    if _vars:
        for _rel, _vlist in _vars.items():
            for _v in _vlist:
                _og = gid_of.get(_v.get("owner_id")) \
                    if _v.get("owner_id") is not None else None
                reg_var("var:" + str(_rel) + ":" + str(_v.get("name")) + ":"
                        + str(_v.get("owner_id")),
                        _v.get("name"), _rel, _og, _v.get("kind"),
                        _v.get("line", 0), _v.get("tainted", False),
                        _v.get("reads", 0), _v.get("writes", 0))
    # P201：未初始化变量（来自 model.uninit）→ 变量节点 fl.uninit 高亮，并补 flow 到 owner
    _uninit = getattr(model, "uninit", None) if model is not None else None
    if _uninit:
        for _u in _uninit:
            _rel = _u.get("rel") or _u.get("file") or ""
            _og = gid_of.get(_u.get("owner_id")) \
                if _u.get("owner_id") is not None else None
            reg_var("var:" + str(_rel) + ":" + str(_u.get("name")) + ":uninit:"
                    + str(_u.get("owner_id")),
                    _u.get("name"), _rel, _og, "local",
                    _u.get("line", 0), True, 0, 0)
    # P201：将 down/up/contain/flow 由「gid→list」字典归一为「按 gid 索引的列表」，
    # 保证 JSON 中为数组（前端 Object.keys 遍历 / Python 按 gid 索引一致），
    # 同时兼容既有 GLOBAL_SEARCH_JS（down/up 取真值直接用，列表/字典均可）。
    _n = len(meta)

    # P203 --max-nodes：节点数硬上限。超出时按优先级 folder>file>function>variable
    # 保留高价值节点，优先截断占大头的变量节点（其在调用图遍历中价值最低）。
    # P204 智能截断：含污点的变量（fl.t/uninit=1）与函数同优先级——它们是安全
    # 审计的核心节点，截断时优先保留，避免「截断后看不出风险点」。
    _truncated = False
    if max_nodes is not None and _n > int(max_nodes):
        _keep = set()
        _order = {"folder": 0, "file": 1, "local": 2, "main": 2,
                  "method": 2, "constructor": 2, "script": 2, "variable": 3}

        def _pri(g):
            m = meta[g] or {}
            k = m.get("k")
            base = _order.get(k, 9)
            # 含污点(t)或未初始化(uninit)的变量提升为「函数级」优先级（P204），
            # 这类变量是安全审计核心节点，截断时优先保留，避免看不出风险点。
            _fl = m.get("fl") or {}
            if k == "variable" and (_fl.get("t") or _fl.get("uninit")):
                base = 2
            return (base, g)
        _by_pri = sorted(range(_n), key=_pri)
        _dropped_vars = []   # P207-5：被截断丢弃的变量名（高价值优先），供 banner 可点击下钻
        for g in _by_pri:
            if len(_keep) >= int(max_nodes):
                _truncated = True
                # 记录剩余未保留的变量节点（按优先级降序=高价值在前）
                for dg in _by_pri[len(_keep):]:
                    dm = meta[dg] or {}
                    if dm.get("k") == "variable":
                        _dropped_vars.append({"n": dm.get("n", ""), "r": dm.get("r", ""),
                                              "l": dm.get("l", 0)})
                break
            _keep.add(g)
        # P207-5：截断变量名单过多时仅保留前若干（高价值已在排序前部），其余折叠为计数
        _dropped_vars = _dropped_vars[:20]
        # 被保留节点需要其 contain/flow/down/up 指向的节点也尽量保留，避免悬空边；
        # 但为严格限容，仅保留「两端都在 _keep 内」的边（前端遇到缺失 gid 按空处理）。
        meta = [meta[g] for g in range(_n) if g in _keep]

        def _remap(d):
            # d: 原 gid -> list[原 gid]；返回仅含保留 gid 的子图（gid 重排）
            _old_to_new = {g: i for i, g in enumerate(sorted(_keep))}
            _new = [[] for _ in range(len(_keep))]
            for g in _keep:
                ni = _old_to_new[g]
                for t in (d.get(g, d.get(str(g), [])) or []):
                    if t in _keep:
                        _new[ni].append(_old_to_new[t])
            return _new

        down = _remap(down)
        up = _remap(up)
        contain = _remap(contain)
        flow = _remap(flow)
        # gid_of 失效（gid 已重排）——调用方仅用于「渲染后跳转」之外的高层聚合，
        # 高层聚合走 cg 本身，故把 gid_of 置为旧映射的最接近近似（保留文件级可查）。
        _new_n = len(meta)
        _already_list = True
    else:
        _new_n = _n
        _already_list = False

    def _dict_to_list(d):
        return [d.get(i, d.get(str(i), [])) for i in range(_new_n)]

    cg = {"meta": meta,
          "down": down if _already_list else _dict_to_list(down),
          "up": up if _already_list else _dict_to_list(up),
          "contain": contain if _already_list else _dict_to_list(contain),
          "flow": flow if _already_list else _dict_to_list(flow),
          "truncated": _truncated,
          "truncated_vars": _dropped_vars if _truncated else []}   # P207-5：被截断变量（可点击）
    cg_json = _json.dumps(cg, ensure_ascii=False, separators=(",", ":"))
    result = (cg_json, gid_of)
    _CG_CACHE[_cache_key] = (calls_of, result)
    return result

def _render_call_tree(root_fn, direction, calls_of, callers_of, fn_to_file,
                     linker, depth=0, seen=None, counter=None):
    """生成 doxygen 风格调用树（嵌套 <ul>）。

    direction='callee' 正向（调用图：root 调用了谁）；
    direction='caller' 反向（被调用图：谁调用了 root）。
    linker(target_fn, tmf) -> href：所有层级链接都统一相对「所在页面」解析，
    避免嵌套节点按中间文件目录计算导致跨目录断链。
    返回 HTML 字符串；循环调用、超过最大深度 / 最大节点数均做截断。
    """
    if seen is None:
        seen = set()
    if counter is None:
        counter = [0]
    if counter[0] >= MAX_CALLGRAPH_NODES or depth > MAX_CALLGRAPH_DEPTH:
        return ""
    if direction == "callee":
        links = calls_of.get(id(root_fn), [])
    else:
        links = [(cf, fn_to_file.get(id(cf))) for cf in callers_of.get(id(root_fn), [])]
    if not links:
        return ""
    items = []
    for target_fn, tmf in links:
        if tmf is None or counter[0] >= MAX_CALLGRAPH_NODES:
            continue
        counter[0] += 1
        href = linker(target_fn, tmf)
        label = html_mod.escape(target_fn.name)
        if id(target_fn) in seen:
            items.append(f'<li><a href="{href}">{label}</a> '
                         f'<span class="muted">(循环调用)</span></li>')
            continue
        sub = ""
        if depth < MAX_CALLGRAPH_DEPTH:
            sub = _render_call_tree(target_fn, direction, calls_of, callers_of,
                                    fn_to_file, linker, depth + 1, seen | {id(root_fn)}, counter)
        items.append(f'<li><a href="{href}">{label}</a>{sub}</li>')
    return "<ul class=\"calltree\">" + "".join(items) + "</ul>" if items else ""

def _dup_candidates(files):
    """P52：收集项目内的同名函数候选，返回 {lower_name: [(fn, mf), ...]}，
    仅含同名候选数 > 1 的短名（用于「就近解析」可视化：列出实际解析到的候选
    及其余同名候选的文件:行，让歧义走向透明化）。
    """
    m = defaultdict(list)
    for mf in files:
        for f in mf.functions:
            if f.kind == "script":
                continue
            m[f.name.lower()].append((f, mf))
    return {k: v for k, v in m.items() if len(v) > 1}

MAX_CALLGRAPH_DEPTH = 4

MAX_CALLGRAPH_NODES = 60

