class MatlabFrontend(BaseFrontend):
    """P90：MATLAB 前端插件（解析复走主流程，测试生成独立实现）。"""
    lang = "matlab"
    exts = (".m",)
    display = "MATLAB"

    def collect_files(self, root, recursive=True, exclude=None):
        return collect_files(root, recursive=recursive, exclude=exclude)

    def parse_file(self, text, rel, path):
        # 主流程使用 MFile 类解析（含语义分析）；此处保留原始文本供扩展。
        return {"rel": rel, "path": path, "text": text}

    def build_edges(self, model):
        """MATLAB 的结构边由**主流程**产出（MFile / 语义分析），不走 IR 的
        func_index 判定 —— 显式覆盖成空，避免读者以为这里也在算边。
        MATLAB 的 unresolved 产出点是 `frontends/matlab.py::unresolved_tuples`。"""
        return [], []

    def gen_tests(self, model, out_dir, root):
        return _gen_matlab_tests(model, out_dir, root)


register_frontend("matlab", MatlabFrontend)


def _match_c_bridge(files, c_model):
    """P87：MATLAB ↔ C 混合桥接——MATLAB 外部调用命中 C 函数名。

    返回 [{matlab, mfile, c_file, c_func, count}]（按 matlab 名排序）。"""
    bridge = []
    idx = c_model.get("func_index", {}) or {}
    if not idx:
        return bridge
    for mf in files:
        for f in mf.functions:
            for cname, cnt in (f.external_calls or {}).items():
                hits = idx.get(cname.lower())
                if not hits:
                    continue
                for h in hits:
                    bridge.append({
                        "matlab": f.name, "mfile": mf.rel,
                        "c_file": h["file"]["rel"], "c_func": h["func"]["name"],
                        "count": cnt,
                    })
    bridge.sort(key=lambda b: (b["mfile"], b["matlab"], b["c_func"]))
    return bridge


def _persist_and_diff_sarif(checks_for_sarif, args, root, display):
    """P94：C/PY/JS 模式 SARIF 基线持久化 + --sarif-diff 增量差异报告。

    与 MATLAB 主流程对齐：
      - --sarif 输出后自动把当前指纹写入 .codebuddy/analyzer/sarif_base.json；
      - --sarif-diff 未给 --sarif-base 时自动读该自动基线，生成 Markdown 差异报告
        （新增/已修复告警表），实现 PR 间无需手工传参的增量扫描。
    返回 True 表示成功（失败已打印告警，不抛异常）。"""
    auto_base = _default_sarif_base(root)
    try:
        sarif_text = render_sarif(checks_for_sarif, root)
        cur_fps = _collect_sarif_fps_from_text(sarif_text)
    except Exception as exc:
        print("[WARN] SARIF 渲染/指纹提取失败：%s" % exc)
        return True
    if args.sarif and not args.sarif_diff:
        try:
            if _save_sarif_fingerprints(cur_fps, auto_base):
                print("[INFO] SARIF 基线已持久化：%s（%d 条指纹）"
                      % (auto_base, len(cur_fps)))
        except Exception as exc:
            print("[WARN] 基线持久化失败：%s" % exc)
    if args.sarif_diff:
        base_fps = None
        if args.sarif_base:
            # 首次运行基线尚未生成属正常：降级为 INFO，本次即作为新基线；
            # 仅当文件存在却解析失败才返回错误。
            if not os.path.exists(args.sarif_base):
                print("[INFO] 未找到基线 SARIF %s，本次扫描将作为新基线（首次运行属正常）"
                      % args.sarif_base)
            else:
                try:
                    base_fps = _load_sarif_fingerprints(args.sarif_base)
                except Exception as exc:
                    print("[ERROR] 读取基线 SARIF 失败：%s" % exc)
                    return False
        elif os.path.exists(auto_base):
            try:
                # 自动基线是 _save_sarif_fingerprints 写入的裸指纹行数组
                base_fps = _load_fp_list_file(auto_base)
                print("[INFO] 复用自动基线：%s（%d 条指纹）"
                      % (auto_base, len(base_fps)))
            except Exception as exc:
                print("[WARN] 读取自动基线失败：%s" % exc)
        if base_fps is None:
            if args.sarif_base:
                # 显式基线不存在（首次运行）：用本次结果落盘建基（下次即可增量），
                # 并跳过当次差异报告而非报错。
                if _write_output(args.sarif_base, sarif_text,
                                 "SARIF 基线（首次建基）"):
                    print("[INFO] 基线已建立：%s（来自本次扫描，"
                          "下次运行即可输出增量差异）" % args.sarif_base)
                else:
                    print("[INFO] 跳过 SARIF 差异报告：基线 %s 尚不存在。"
                          % args.sarif_base)
                return True
            print("[ERROR] --sarif-diff 需要基线：请先运行一次 --sarif（自动建基）"
                  "或显式指定 --sarif-base")
            return False
        _, sarif_stats = render_sarif(checks_for_sarif, root,
                                      base_fps=base_fps, return_stats=True)
        _diff_md = render_sarif_diff_md(sarif_stats,
                                        args.sarif_base or auto_base, root)
        # R62-R12：算子影响增量并入 SARIF 差异报告（需 --operator-impact-baseline）。
        _base = getattr(args, "operator_impact_baseline", None)
        if _base and os.path.exists(_base):
            try:
                with io.open(_base, "r", encoding="utf-8") as _fh:
                    _prev = json.load(_fh)
                _cur = _compute_operator_impact(checks_for_sarif)
                _diff_md = _diff_md.rstrip() + "\n\n" + \
                    _operator_impact_delta_md(_prev, _cur)
            except (IOError, OSError, ValueError) as _e:
                print("[WARN] 算子增量并入差异报告失败：%s" % _e)
        if _write_output(args.sarif_diff, _diff_md, "SARIF 差异报告"):
            print("[OK] SARIF 差异报告已写入：%s" % args.sarif_diff)
            return True
        return False
    return True


def _apply_unified_gates(model, heuristics, args, root, lang):
    """P94/P96：跨语言统一门禁矩阵（C/PY/JS 模式与 MATLAB 主流程对齐）。

    依次应用：
      1) --max-warnings-by-rule 与 --gate-file rule_gates 合并 → 按规则独立阈值；
      2) --max-warnings 告警总量阈值；
      3) --gate-file test_coverage.min_percent → measure_branch_coverage 分支覆盖门禁。
    返回 (ok, messages)。"""
    ok = True
    msgs = []
    gate_cfg = None
    if args.gate_file:
        gate_cfg = _parse_gate_file(args.gate_file)
        if gate_cfg is None:
            msgs.append("[ERROR] 门禁文件解析失败：%s" % args.gate_file)
            return False, msgs
    rule_max = {}
    if args.max_warnings_by_rule:
        _rm = _parse_rule_max(args.max_warnings_by_rule)
        if _rm is None:
            msgs.append("[ERROR] --max-warnings-by-rule 格式非法：%s"
                        % args.max_warnings_by_rule)
            ok = False
        else:
            rule_max.update(_rm)
    if gate_cfg and gate_cfg.get("rule_gates"):
        rule_max.update(gate_cfg["rule_gates"])
    checks = {"%s_heuristics" % lang: heuristics or []}
    if rule_max:
        _rgv = _rule_gate_violations(checks, rule_max)
        if _rgv:
            for _r, _c, _m in _rgv:
                msgs.append("[WARN] 规则门禁违例：%s 共 %d 条，超过阈值 %d"
                            % (_r, _c, _m))
            ok = False
        else:
            msgs.append("[OK] --max-warnings-by-rule 规则门禁通过")
    if args.max_warnings > 0:
        n_warn = sum(len(h) for h in (heuristics or []))
        if n_warn > args.max_warnings:
            msgs.append("[WARN] 告警数 %d 超过阈值 %d，质量门禁未通过"
                        % (n_warn, args.max_warnings))
            ok = False
        else:
            msgs.append("[OK] 告警总数 %d ≤ 阈值 %d，质量门禁通过"
                        % (n_warn, args.max_warnings))
    if gate_cfg is not None and gate_cfg.get("test_coverage") is not None:
        _cov = measure_branch_coverage(model, root, lang=lang)
        if _cov is not None:
            pct = _cov["coverage_percent"]
            mp = gate_cfg["test_coverage"].get("min_percent", 0) or 0
            msgs.append("[INFO] 分支覆盖：%d/%d（%.1f%%），阈值 %.1f%%"
                        % (_cov["covered_branches"], _cov["total_branches"],
                           pct, mp))
            if pct < mp:
                msgs.append("[WARN] 测试覆盖率未达门禁（%.1f%% < %.1f%%）"
                            % (pct, mp))
                ok = False
        else:
            msgs.append("[WARN] 分支覆盖度量不可用（模型为空）")
    return ok, msgs


def _run_c_only(c_model, root, args):
    """P87/P90：纯 C 分析入口（--lang c）。

    不进入 MATLAB 解析流程，输出 C 语言前端分析报告（HTML/JSON/SARIF），
    支持 --checks C 静态启发式检查、--gen-tests C 测试骨架生成，
    以及 P94/P96 跨语言统一门禁矩阵（--gate-file/--max-warnings-by-rule/覆盖门禁）。"""
    ok = True
    # P90：C 静态启发式检查（--checks all/具体规则名/none）
    c_heuristics = []
    if args.checks != "none":
        c_heuristics = _c_heuristic_checks(
            c_model, _parse_checks_arg(args.checks))
    # P90：--gen-tests 生成 C 测试骨架（走前端插件接口，验证注册表可用性）
    if args.gen_tests:
        n_gt, rels = gen_tests_for_lang("c", c_model, args.gen_tests, root)
        print("[OK] C 测试骨架已生成：%d 个文件 → %s/gen_c_tests/"
              % (n_gt, args.gen_tests))
        for r in rels[:20]:
            print("      - %s" % r)
        if len(rels) > 20:
            print("      ... 其余 %d 个省略" % (len(rels) - 20))
    c_html = render_c_report(c_model, [], root)
    if args.browse:
        bdir = os.path.abspath(args.browse)
        if not os.path.isdir(bdir):
            try:
                os.makedirs(bdir)
            except Exception as exc:
                print("[ERROR] 创建 C 报告目录失败：%s" % exc, file=sys.stderr)
                return 1
        try:
            with io.open(os.path.join(bdir, "c_report.html"), "w",
                         encoding="utf-8") as fh:
                fh.write(c_html)
            with io.open(os.path.join(bdir, "index.html"), "w",
                         encoding="utf-8") as fh:
                fh.write(render_c_index_html(c_model, root))
            print("[OK] C 语言前端分析站点已生成：%s/index.html" % bdir)
        except Exception as exc:
            print("[ERROR] 写入 C 报告失败：%s" % exc, file=sys.stderr)
            ok = False
    if args.json:
        # R33/C'3：--binary-attach 的三态归因（只依据显式给出的二进制）
        _c_names = [u[0] for u in (c_model.get("unresolved", []) or [])]
        _binattr, _binattr_ok = _emit_binary_attach_names(
            args, _c_names, label="C 未解析调用", root=root)
        _c_payload = {
            "lang": c_model.get("lang", "c"),
            "version": VERSION,
            "files": [{
                "rel": pf["rel"], "includes": pf["includes"],
                "macros": pf["macros"],
                "functions": pf["functions"],
            } for pf in c_model.get("files", [])],
            "edges": [{"caller": e[0], "callee": e[1], "line": e[2],
                       "file": e[3]} for e in c_model.get("edges", [])],
            # P90：#include 跨文件依赖边（解析到项目内文件 / 未解析为 null）
            "include_edges": [{"from": e[0], "include": e[1], "to": e[2]}
                              for e in c_model.get("include_edges", [])],
            "unresolved": [{"callee": u[0], "line": u[1], "file": u[2]}
                           for u in c_model.get("unresolved", [])],
            "heuristics": c_heuristics,
        }
        if _binattr is not None:
            _c_payload["unresolved_attribution"] = _binattr
        if not _binattr_ok:
            ok = False
        c_json = json.dumps(_c_payload, ensure_ascii=False, indent=2)
        if _write_output(args.json, c_json, "JSON"):
            print("[OK] JSON 已写入：%s" % args.json)
        else:
            ok = False
    else:
        # 即使不写 JSON，也把归因结果打到终端（否则这个开关在非 JSON 模式下静默无输出）
        _binattr, _binattr_ok = _emit_binary_attach_names(
            args, [u[0] for u in (c_model.get("unresolved", []) or [])],
            label="C 未解析调用", root=root)
        if not _binattr_ok:
            ok = False
    # P90：C 模式 SARIF 输出（--lang c --sarif），C 启发式检查接入统一 SARIF 规范
    _cf = {"c_heuristics": c_heuristics}
    # R62：检测算子工程影响分析——无条件落地（不依赖 --sarif 开关）。
    _apply_operator_impact(args, _cf)
    if args.sarif:
        sarif_text = render_sarif(_cf, root)
        if _write_output(args.sarif, sarif_text, "SARIF"):
            print("[OK] C 模式 SARIF 已写入：%s" % args.sarif)
        else:
            ok = False
    # P94：SARIF 基线自动持久化 + --sarif-diff 增量差异报告（PR 级增量扫描）
    if args.sarif or args.sarif_diff:
        if not _persist_and_diff_sarif(_cf, args, root, "C 模式"):
            ok = False
    # P94/P96：跨语言统一门禁矩阵
    _g_ok, _g_msgs = _apply_unified_gates(c_model, c_heuristics, args, root, "c")
    for _gm in _g_msgs:
        print(_gm)
    if not _g_ok:
        ok = False
    n_files = len(c_model.get("files", []) or [])
    n_funcs = sum(len(pf["functions"]) for pf in c_model.get("files", []))
    n_edges = len(c_model.get("edges", []) or [])
    n_inc = len(c_model.get("include_edges", []) or [])
    print("\n===== C 语言前端分析摘要 =====")
    print("C 文件 %d | C 函数 %d | 调用边 %d | 未解析 %d | include 依赖边 %d"
          % (n_files, n_funcs, n_edges,
             len(c_model.get("unresolved", []) or []), n_inc))
    if c_heuristics:
        from collections import Counter as _Cnt
        by_kind = _Cnt(h["kind"] for h in c_heuristics)
        print("C 启发式检查 %d 条：%s"
              % (len(c_heuristics),
                 " | ".join("%s=%d" % (k, by_kind[k]) for k in sorted(by_kind))))
    return 0 if ok else 1


def _run_ext_only(model, root, args, lang):
    """P93：Python/JS 前端入口（--lang py / --lang js）。

    复用 C 模式输出链路：静态启发式检查（--checks）、测试骨架（--gen-tests）、
    JSON（含 heuristics）/SARIF 输出与摘要；不生成 HTML 站点。"""
    ok = True
    fe = get_frontend(lang)
    heuristics = []
    if args.checks != "none":
        heuristics = fe.collect_checks(model, _parse_checks_arg(args.checks)) or []
    if args.gen_tests:
        n_gt, rels = gen_tests_for_lang(lang, model, args.gen_tests, root)
        print("[OK] %s 测试骨架已生成：%d 个文件 → %s/gen_%s_tests/"
              % (fe.display, n_gt, args.gen_tests, lang))
        for r in rels[:20]:
            print("      - %s" % r)
        if len(rels) > 20:
            print("      ... 其余 %d 个省略" % (len(rels) - 20))
    if args.json:
        payload = {
            "lang": model.get("lang", lang),
            "version": VERSION,
            "files": [{"rel": pf["rel"], "imports": pf.get("imports", []),
                       "functions": pf["functions"]}
                      for pf in model.get("files", [])],
            "edges": [{"caller": e[0], "callee": e[1], "line": e[2], "file": e[3]}
                      for e in model.get("edges", [])],
            "include_edges": [],
            "unresolved": [{"callee": u[0], "line": u[1], "file": u[2]}
                           for u in model.get("unresolved", [])],
            "heuristics": heuristics,
        }
        if _write_output(args.json,
                         json.dumps(payload, ensure_ascii=False, indent=2),
                         "JSON"):
            print("[OK] JSON 已写入：%s" % args.json)
        else:
            ok = False
    _cf = {"%s_heuristics" % lang: heuristics}
    # R62：检测算子工程影响分析——无条件落地（控制台/JSON/独立文件），
    # 不依赖 --sarif 开关（与 MATLAB 主流程一致）。
    _apply_operator_impact(args, _cf)
    if args.sarif:
        sarif_text = render_sarif(_cf, root)
        if _write_output(args.sarif, sarif_text, "SARIF"):
            print("[OK] %s 模式 SARIF 已写入：%s" % (fe.display, args.sarif))
        else:
            ok = False
    # P94：SARIF 基线自动持久化 + --sarif-diff 增量差异报告（PR 级增量扫描）
    if args.sarif or args.sarif_diff:
        if not _persist_and_diff_sarif(_cf, args, root, fe.display):
            ok = False
    # P94/P96：跨语言统一门禁矩阵
    _g_ok, _g_msgs = _apply_unified_gates(model, heuristics, args, root, lang)
    for _gm in _g_msgs:
        print(_gm)
    if not _g_ok:
        ok = False
    n_files = len(model.get("files", []) or [])
    n_funcs = sum(len(pf["functions"]) for pf in model.get("files", []))
    print("\n===== %s 语言前端分析摘要 =====" % fe.display)
    print("%s 文件 %d | %s 函数 %d | 调用边 %d | 未解析 %d | import 引用 %d"
          % (fe.display, n_files, fe.display, n_funcs,
             len(model.get("edges", []) or []),
             len(model.get("unresolved", []) or []),
             sum(len(pf.get("imports", [])) for pf in model.get("files", []))))
    if heuristics:
        from collections import Counter as _Cnt
        by_kind = _Cnt(h["kind"] for h in heuristics)
        print("%s 启发式检查 %d 条：%s"
              % (fe.display, len(heuristics),
                 " | ".join("%s=%d" % (k, by_kind[k]) for k in sorted(by_kind))))
    return 0 if ok else 1


