TAINT_SVG_JS = """
// P151：污点流路径图交互——点击表格行高亮对应 SVG 路径；hover 节点逐步高亮。
(function(){
  var rows = document.querySelectorAll('#taint-table tbody tr');
  var graphs = document.querySelectorAll('#taint-graphs svg[data-gi]');
  function clearHi(){
    graphs.forEach(function(g){
      g.querySelectorAll('.t-node,.t-edge').forEach(function(e){ e.classList.remove('hi'); });
    });
  }
  function hi(gi){
    var g = document.querySelector('#taint-graphs svg[data-gi="'+gi+'"]');
    if(!g) return;
    g.querySelectorAll('.t-node,.t-edge').forEach(function(e){ e.classList.add('hi'); });
  }
  rows.forEach(function(tr, i){
    tr.addEventListener('click', function(){
      clearHi();
      // 表格行与 flows 顺序一致（P151 注入时同序）
      hi(i);
      var g = document.querySelector('#taint-graphs svg[data-gi="'+i+'"]');
      if(g){ g.scrollIntoView({block:'nearest'}); }
    });
  });
  // hover 节点逐步高亮其上游链
  document.querySelectorAll('#taint-graphs .t-node').forEach(function(n){
    n.addEventListener('mouseenter', function(){
      var g = n.closest('svg');
      var idx = parseInt(n.getAttribute('data-idx')||'0',10);
      g.querySelectorAll('.t-node').forEach(function(x){
        var xi = parseInt(x.getAttribute('data-idx')||'0',10);
        x.classList.toggle('hi', xi <= idx);
      });
      g.querySelectorAll('.t-edge').forEach(function(x){
        var xi = parseInt(x.getAttribute('data-idx')||'0',10);
        x.classList.toggle('hi', xi < idx);
      });
    });
    n.addEventListener('mouseleave', function(){
      var g = n.closest('svg');
      g.querySelectorAll('.t-node,.t-edge').forEach(function(x){ x.classList.remove('hi'); });
    });
  });
})();
"""


def _taint_svg_path(gi, fl, chain, nodes):
    """P151：把一条污点流渲染为左(源)→右(汇)的 SVG 节点链。

    chain：传播路径函数列表；nodes：chain + 汇。源节点标绿、汇节点标红、
    中间节点标蓝；边为箭头。节点 data-idx 用于 hover 逐步高亮。"""
    width = 920
    pad = 30
    n = max(len(nodes), 1)
    gap = (width - 2 * pad) / float(n)
    row_y = 60
    parts = ['<svg data-gi="%d" viewBox="0 0 %d 110" width="100%%" '
             'style="max-width:%dpx">' % (gi, width, width)]
    # 标题
    parts.append('<text x="%d" y="20" font-size="12" fill="#57606a">%s · 级别 %d%s</text>'
                 % (pad, _dh_escape(fl.get("func", "?")), fl.get("level", 1),
                    " · 精确" if fl.get("exact") else ""))
    for i, name in enumerate(nodes):
        x = pad + gap * i + gap / 2.0
        is_src = (i == 0)
        is_snk = (i == len(nodes) - 1)
        fill = "#1a7f37" if is_src else ("#d1242f" if is_snk else "#0969da")
        cls = "t-node" + (" src" if is_src else (" snk" if is_snk else ""))
        # 节点圆 + 标签
        parts.append('<g class="%s" data-idx="%d" style="cursor:pointer">'
                     '<circle cx="%.1f" cy="%d" r="18" fill="%s"/>'
                     '<text x="%.1f" y="%d" font-size="10" fill="#fff" '
                     'text-anchor="middle">%s</text></g>'
                     % (cls, i, x, row_y, fill, x, row_y + 4,
                        _dh_escape(_short_node(name))))
        if i > 0:
            px = pad + gap * (i - 1) + gap / 2.0
            parts.append('<line class="t-edge" data-idx="%d" x1="%.1f" y1="%d" '
                         'x2="%.1f" y2="%d" stroke="#8b949e" stroke-width="2" '
                         'marker-end="url(#arrow)"/>'
                         % (i - 1, px + 18, row_y, x - 18, row_y))
    parts.append('<defs><marker id="arrow" markerWidth="8" markerHeight="8" '
                 'refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" '
                 'fill="#8b949e"/></marker></defs>')
    parts.append('</svg>')
    return "".join(parts)


def _short_node(name):
    """P151：节点标签截断（保留函数名，过长用尾缀）。"""
    nm = str(name).split("/")[-1]
    if len(nm) > 14:
        nm = nm[:12] + "…"
    return nm


VARFLOW_VIEW_JS = r"""
(function () {
  var rows = window.__VARFLOW__ || [];
  var app = document.getElementById('vf-app');
  var kw = document.getElementById('vf-kw');
  if (!app) return;
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function chainHTML(defs) {
    if (!defs || !defs.length) return '<span class="muted">—</span>';
    return defs.map(function (d) {
      var from = (d.from && d.from.length)
        ? d.from.map(function (f) { return '<span class="vf-src">' + esc(f) + '</span>'; }).join(' ')
        : '<span class="vf-const">常量/外部</span>';
      var kind = d.kind === 'param' ? '形参' : '赋值';
      return '<span class="vf-def"><span class="vf-at">L' + esc(d.line) + '</span>'
        + '<span class="vf-kind">' + kind + '</span> ← ' + from + '</span>';
    }).join('<span class="vf-arrow">|</span>');
  }
  function xfTag(v) {
    if (v && v.xf > 0) {
      return ' <span class="vf-xftag" title="跨文件流动边数量">↔' + v.xf + '</span>';
    }
    return '';
  }
  function render(q) {
    q = (q || '').toLowerCase();
    var html = '';
    for (var i = 0; i < rows.length; i++) {
      var row = rows[i];
      var hitVars = row.vars.filter(function (v) {
        if (!q) return true;
        var hay = (v.name + ' ' + v.dim + ' ' + (v.defs || []).map(function (d) {
          return (d.from || []).join(' ');
        }).join(' ')).toLowerCase();
        return hay.indexOf(q) >= 0;
      });
      var fnHay = (row.name + ' ' + row.rel).toLowerCase();
      if (q && !hitVars.length && fnHay.indexOf(q) < 0) continue;
      var show = (q && hitVars.length) ? hitVars : row.vars;
      html += '<section class="vf-func"><h3><a class="vf-fname" href="func_detail.html?g='
        + esc(row.gid) + '">' + esc(row.name) + '</a> <span class="muted">'
        + esc(row.rel) + '</span> <span class="vf-count">' + show.length + ' 变量</span></h3>';
      html += '<table class="vf-table"><thead><tr><th>变量</th><th class="vf-c-dim">维度</th>'
        + '<th>定义 ← 来源（流动链）</th></tr></thead><tbody>';
      for (var j = 0; j < show.length; j++) {
        var v = show[j];
        html += '<tr><td class="vf-vname">' + esc(v.name) + xfTag(v) + '</td>'
          + '<td class="vf-dim">' + esc(v.dim || '?') + '</td>'
          + '<td class="vf-chain">' + chainHTML(v.defs) + '</td></tr>';
      }
      html += '</tbody></table></section>';
    }
    if (!html) html = '<p class="muted">无匹配变量。</p>';
    app.innerHTML = html;
  }
  if (kw) kw.addEventListener('input', function () { render(kw.value); });
  render('');
})();
"""

VARFLOW_XFLOW_JS = r"""
(function () {
  var X = window.__VARFLOW_X__ || { nodes: {}, edges: [] };
  var q = document.getElementById('vf-xq');
  var go = document.getElementById('vf-xgo');
  var out = document.getElementById('vf-xout');
  var err = document.getElementById('vf-xerr');
  if (!out) return;
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function label(fid, v) {
    var nd = X.nodes[fid] || { name: '?', rel: '' };
    return '<b>' + esc(nd.name) + '.' + esc(v) + '</b>'
      + ' <span class="muted">' + esc(nd.rel) + '</span>';
  }
  var SEP = '|';
  var down = {}, up = {};
  X.edges.forEach(function (e) {
    var sk = e.f + SEP + e.fv, tk = e.t + SEP + e.tv;
    (down[sk] = down[sk] || []).push(e);
    (up[tk] = up[tk] || []).push(e);
  });
  function collect(seed, adj) {
    var seen = {}, res = [], queue = seed.slice();
    seed.forEach(function (s) { seen[s] = true; });
    while (queue.length) {
      var cur = queue.shift();
      (adj[cur] || []).forEach(function (e) {
        var nk = (adj === down) ? (e.t + SEP + e.tv) : (e.f + SEP + e.fv);
        res.push(e);
        if (!seen[nk]) { seen[nk] = true; queue.push(nk); }
      });
    }
    return res;
  }
  function dedupe(es) {
    var seen = {}, out = [];
    es.forEach(function (e) {
      var k = [e.f, e.fv, e.t, e.tv, e.k, e.line].join(SEP);
      if (!seen[k]) { seen[k] = true; out.push(e); }
    });
    return out;
  }
  function render() {
    if (err) err.textContent = '';
    var txt = (q && q.value || '').trim();
    if (!txt) {
      out.innerHTML = '<p class="muted">输入「函数.变量」或「变量」后点击「追踪」，'
        + '端到端还原该变量跨模块的流动链。</p>';
      return;
    }
    var parts = txt.split('.');
    var fName = parts.length > 1 ? parts[0].trim().toLowerCase() : null;
    var vName = (parts.length > 1 ? parts.slice(1).join('.') : parts[0]).trim().toLowerCase();
    var starts = [];
    Object.keys(X.nodes).forEach(function (idn) {
      var nd = X.nodes[idn];
      if (fName && (nd.name || '').toLowerCase() !== fName) return;
      if (!vName) return;
      starts.push(idn + SEP + vName);
    });
    if (!starts.length) {
      if (err) err.textContent = '未找到匹配的「函数.变量」起点。';
      out.innerHTML = '';
      return;
    }
    var ds = dedupe(collect(starts, down));
    var us = dedupe(collect(starts, up));
    function hop(e) {
      var kind = e.k === 'arg'
        ? '<span class="vf-xk arg">实参→形参</span>'
        : '<span class="vf-xk ret">返回值→变量</span>';
      return '<li>' + label(e.f, e.fv) + ' <span class="vf-arrow">→</span> '
        + label(e.t, e.tv) + ' ' + kind
        + ' <span class="muted">L' + esc(e.line) + ' · ' + esc(e.rel) + '</span></li>';
    }
    var h = '';
    h += '<div class="vf-xsec"><h3>下游（数据从这里流向）'
      + ' <span class="vf-count">' + ds.length + ' 跳</span></h3>';
    h += ds.length ? ('<ul class="vf-xlist">' + ds.map(hop).join('') + '</ul>')
      : '<p class="muted">无下游流动（可能是叶子或被调方不接该变量）。</p>';
    h += '</div>';
    h += '<div class="vf-xsec"><h3>上游（数据来源）</h3>';
    h += us.length ? ('<ul class="vf-xlist">' + us.map(hop).join('') + '</ul>')
      : '<p class="muted">无上游流动（可能是入口参数或常量/外部输入）。</p>';
    h += '</div>';
    out.innerHTML = h;
  }
  if (go) go.addEventListener('click', render);
  if (q) q.addEventListener('keydown', function (ev) {
    if (ev && ev.key === 'Enter') render();
  });
  render();
})();
"""


def _build_varflow_data(model, gid_of):
    """汇总每个函数的变量字段流动（def-use 链）为页面数据（P225-A）。

    与「污点分析(taint.html)」互补：污点只跟踪「敏感源→危险汇」；本视图展示
    **任意变量**的定义/使用位置与来源链，回答"这个变量从哪来、被谁改动、流向哪"。

    返回 rows：每个函数一行 {gid, name, rel, vars:[{name, dim, defs:[...]}]}，
    defs 内每项 {line, from, kind}；from 为来源变量列表。
    """
    import json as _json
    rows = []
    for mf in (getattr(model, 'files', []) or []):
        rel = getattr(mf, 'rel', '') or ''
        flow = _infer_file_varflow(mf)
        for f in (getattr(mf, 'functions', []) or []):
            fname = getattr(f, 'name', '?')
            rec = flow.get(fname)
            if not rec:
                continue
            defs = rec.get("defs", {})
            if not defs:
                continue
            env = _INFER_FUNC_ENV_CACHE.get((id(mf), id(f), getattr(mf, '_path', None)), {})
            vs = []
            for vname in sorted(defs.keys()):
                dlist = []
                for d in defs.get(vname, []):
                    dlist.append({
                        "line": d.get("line"),
                        "from": d.get("from") or [],
                        "kind": d.get("kind"),
                    })
                vs.append({
                    "name": vname,
                    "dim": _shp_str(env.get(vname)),
                    "defs": dlist,
                })
            rows.append({
                "gid": (gid_of.get(id(f)) if gid_of else getattr(f, "gid", None)),
                "name": fname,
                "rel": rel,
                "vars": vs,
            })
    return rows


def _call_lhs_vars(src, line):
    """返回某行赋值语句左侧的变量名列表（多返回值解构返回多个）。"""
    if not (1 <= line <= len(src)):
        return []
    raw = src[line - 1]
    eq = _find_assignment_pos(raw)
    if eq < 0:
        return []
    return _vars_in_expr(raw[:eq])


def _extract_args_from_pos(raw, name_end):
    """从被调名结束位置 name_end 起做括号配对，返回顶层实参字符串列表。"""
    n = len(raw)
    k = name_end
    while k < n and raw[k] in ' \t':
        k += 1
    if k >= n or raw[k] != '(':
        return []
    depth = 1
    k += 1
    start = k
    while k < n and depth > 0:
        c = raw[k]
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
        elif c == "'" or c == '"':
            q = c
            k += 1
            while k < n and raw[k] != q:
                if raw[k] == '\\':
                    k += 1
                k += 1
            if k < n:
                k += 1
            continue
        k += 1
    inner = raw[start:k - 1]
    return _split_top_level_args(inner)


def _build_varflow_xfile(model, gid_of):
    """跨文件变量流（端到端参数绑定图），P225-A 延展。

    遍历每个非脚本函数的调用点（func.call_sites / func.destructured_calls），
    建立「实参 → 被调方形参」与「被调方返回值 → 本函数 LHS 变量」的绑定，
    并规约为统一的数据流有向边，供前端 BFS 端到端溯源：
      - arg 边：调用方变量 sv 作为实参传入 被调方 形参 tv  → 数据流向 (s,sv)→(t,tv)
      - ret  边：被调方 返回值 tv 赋给 调用方 变量 sv    → 数据流向 (t,tv)→(s,sv)
    返回 {"nodes": {gid: {name, rel, gid}},
          "edges": [{f, t, fv, tv, k, line, rel}]}，边均为数据流方向（gid 取自 gid_of）。
    """
    files = getattr(model, 'files', []) or []
    nodes = {}
    edges = []

    def _node(f):
        gid = gid_of.get(id(f))
        if gid not in nodes:
            mf = getattr(f, 'mfile', None)
            nodes[gid] = {
                "name": getattr(f, 'name', '?'),
                "rel": getattr(mf, 'rel', '') or '',
                "gid": gid,
            }
        return gid

    for mf in files:
        src = getattr(mf, 'source_lines', None) or []
        for f in (getattr(mf, 'functions', []) or []):
            if getattr(f, 'kind', None) == 'script':
                continue
            fid = _node(f)
            # (行, 被调方, lhs变量列表) 收集调用点
            sites = []
            for (line, _ns, ne, callee) in (getattr(f, 'call_sites', []) or []):
                lhs = _call_lhs_vars(src, line)
                sites.append((line, callee, lhs, ne))
            for (line, lhs, cname, dinfo) in (getattr(f, 'destructured_calls', []) or []):
                sites.append((line, dinfo, list(lhs), None))
            for (line, callee, lhs_vars, ne) in sites:
                if callee is None:
                    continue
                tid = _node(callee)
                raw = src[line - 1] if (1 <= line <= len(src)) else ""
                cname = getattr(callee, 'name', '')
                if ne is not None:
                    args = _extract_args_from_pos(raw, ne)
                else:
                    args = _extract_call_args(raw, cname) if cname else []
                inputs = getattr(callee, 'inputs', []) or []
                outputs = getattr(callee, 'outputs', []) or []
                rel = nodes[fid]["rel"]
                # 实参 → 形参：数据流出 调用方 → 被调方
                for i, astr in enumerate(args):
                    for v in _vars_in_expr(astr):
                        pname = inputs[i] if i < len(inputs) else None
                        edges.append({"f": fid, "fv": v, "t": tid, "tv": pname,
                                      "k": "arg", "line": line, "rel": rel})
                # 返回值 → LHS 变量：数据流入 被调方 → 调用方
                for j, w in enumerate(lhs_vars):
                    if not w:
                        continue
                    oname = outputs[j] if j < len(outputs) else None
                    edges.append({"f": tid, "fv": oname, "t": fid, "tv": w,
                                  "k": "ret", "line": line, "rel": rel})
    return {"nodes": nodes, "edges": edges}


def render_varflow_page(model, gid_of):
    """P225-A：变量字段流动视图（varflow.html）。

    以函数为卡片，逐一列出函数内每个变量的「定义行 ← 来源变量」链与实测维度，
    让"变量从哪来、如何流动、流向哪里"一目了然；与污点分析互补（污点只管源→汇）。
    另含「跨文件变量溯源」面板（P225-A 延展）：基于调用图的实参→形参、返回值→LHS
    绑定，对任意「函数.变量」做端到端的数据流 BFS 追踪。
    """
    import json as _json
    rows = _build_varflow_data(model, gid_of)
    xf = _build_varflow_xfile(model, gid_of)
    # 每个 (gid, 变量) 的跨文件边计数，附到 var 行用于在卡片内标注
    xfcount = {}
    for e in xf["edges"]:
        xfcount[(e["f"], e["fv"])] = xfcount.get((e["f"], e["fv"]), 0) + 1
        xfcount[(e["t"], e["tv"])] = xfcount.get((e["t"], e["tv"]), 0) + 1
    n_xf_edge = len(xf["edges"])
    for r in rows:
        r_gid = r.get("gid")
        for v in r["vars"]:
            v["xf"] = xfcount.get((r_gid, v["name"]), 0)
    n_var = sum(len(r["vars"]) for r in rows)
    n_edge = sum(sum(len(v["defs"]) for v in r["vars"]) for r in rows)
    data_js = ("window.__VARFLOW__=" + _json.dumps(rows, ensure_ascii=False) + ";")
    xflow_js = ("window.__VARFLOW_X__=" + _json.dumps(xf, ensure_ascii=False) + ";")
    return (
        "<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
        "<title>变量字段流动 · MATLAB 分析器</title>"
        "<link rel=\"stylesheet\" href=\"src/styles.css\">"
        "<link rel=\"stylesheet\" href=\"varflow.css\"></head><body>"
        "<a class=\"skip-link\" href=\"#main-content\">跳到主内容</a>"
        "<header><span class=\"brand\">变量字段流动</span>"
        "<a href=\"index.html\">&larr; 返回索引</a></header>"
        "<main id=\"main-content\">"
        "<h1>变量字段流动（def-use）</h1>"
        "<p class=\"muted\">逐函数展示每个变量的「定义位置 ← 来源变量」链与实测维度。"
        "回答：这个变量从哪来、被哪些语句改写、它的维度是什么。"
        "与「污点分析」互补——污点只跟踪敏感源到危险汇的传播。</p>"
        "<div class=\"vf-stats\">"
        "<span class=\"vf-stat\"><b>%d</b> 函数</span>"
        "<span class=\"vf-stat\"><b>%d</b> 变量</span>"
        "<span class=\"vf-stat\"><b>%d</b> 定义边</span>"
        "<span class=\"vf-stat\"><b>%d</b> 跨文件流动边</span>"
        "</div>"
        "<section id=\"vf-xflow\"><h2>跨文件变量溯源</h2>"
        "<p class=\"muted\">输入「函数名.变量名」（或仅「变量名」匹配所有函数），"
        "沿调用图的实参→形参、返回值→接收变量绑定，端到端还原该变量的跨模块流动链。"
        "例：<code>f.x</code> 或 <code>z</code>。</p>"
        "<div class=\"vf-xbar\"><input id=\"vf-xq\" "
        "placeholder=\"函数.变量 或 变量\" aria-label=\"跨文件溯源\">"
        "<button id=\"vf-xgo\" type=\"button\">追踪</button>"
        "<span class=\"vf-xerr\" id=\"vf-xerr\"></span></div>"
        "<div id=\"vf-xout\"></div></section>"
        "<div class=\"vf-filters\"><input id=\"vf-kw\" "
        "placeholder=\"搜索函数/文件/变量/来源...\" aria-label=\"过滤\">"
        "<span class=\"vf-tip\">变量名后的 <b class=\"vf-xftag\">↔N</b> "
        "表示该变量有 N 条跨文件流动边</span></div>"
        "<div id=\"vf-app\"></div>"
        "</main><script>%s</script><script>%s</script><script>%s</script>"
        "</body></html>"
        % (len(rows), n_var, n_edge, n_xf_edge,
           data_js, xflow_js, VARFLOW_VIEW_JS + VARFLOW_XFLOW_JS)
    )


SCHEDULE_VIEW_JS = r"""
(function () {
  var D = window.__SCHEDULE__ || {};
  var app = document.getElementById('sc-app');
  if (!app) return;
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  var mode = 'callee';
  function tbl(head, rows) {
    var h = '<table class="sc-table"><thead><tr>';
    for (var i = 0; i < head.length; i++) h += '<th>' + esc(head[i]) + '</th>';
    h += '</tr></thead><tbody>';
    for (var r = 0; r < rows.length; r++) {
      h += '<tr>';
      for (var c = 0; c < rows[r].length; c++) h += '<td>' + rows[r][c] + '</td>';
      h += '</tr>';
    }
    return h + '</tbody></table>';
  }
  function link(name, gid) {
    if (gid == null) return esc(name);
    return '<a class="sc-fname" href="func_detail.html?g=' + esc(gid) + '">' + esc(name) + '</a>';
  }
  function render() {
    var html = '';
    html += '<section class="sc-block"><h2>调用最频繁（被调用热度 Top）</h2>'
      + '<p class="muted">按"被调用次数"降序——这些是被反复调度的核心函数。</p>';
    var hot = D.hot_callees || [];
    html += tbl(['函数', '所属文件', '被调用次数', '调用方个数'], hot.map(function (x) {
      return [link(x.name, x.gid), esc(x.rel), '<b>' + x.n + '</b>', x.n_callers];
    }));
    html += '</section>';
    html += '<section class="sc-block"><h2>入口函数（无人调用）</h2>'
      + '<p class="muted">入度为 0 的函数——脚本入口 / 对外接口 / 定时任务起点。</p>';
    var roots = D.roots || [];
    html += tbl(['函数', '所属文件', '调用出的函数数'], roots.map(function (x) {
      return [link(x.name, x.gid), esc(x.rel), x.n_calls];
    }));
    html += '</section>';
    html += '<section class="sc-block"><h2>模块调度（函数 → 函数 调用统计）</h2>'
      + '<div class="sc-tabs"><button data-m="callee" class="on">按被调方聚合</button>'
      + '<button data-m="caller">按调用方聚合</button></div>';
    var ei = D.edges_info || [];
    var agg = {};
    for (var i = 0; i < ei.length; i++) {
      var e = ei[i];
      var key = mode === 'callee' ? (e.t + '\u0001' + e.tr) : (e.s + '\u0001' + e.sr);
      if (!agg[key]) agg[key] = { s: e.s, sr: e.sr, t: e.t, tr: e.tr, n: 0, lines: [], sg: e.sg, tg: e.tg };
      var a = agg[key];
      a.n += 1;
      a.lines.push(e.line);
    }
    var list = Object.keys(agg).map(function (k) { return agg[k]; });
    list.sort(function (a, b) { return b.n - a.n; });
    html += tbl(['调用方', mode === 'callee' ? '被调方' : '（聚合）', '次数', '调用行'],
      list.map(function (a) {
        var lines = a.lines.slice(0, 12).join(', ') + (a.lines.length > 12 ? ' …' : '');
        return [link(a.s, a.sg), link(a.t, a.tg), '<b>' + a.n + '</b>', '<span class="sc-lines">' + esc(lines) + '</span>'];
      }));
    html += '</section>';
    app.innerHTML = html;
    var btns = app.querySelectorAll('.sc-tabs button');
    for (var b = 0; b < btns.length; b++) {
      btns[b].addEventListener('click', function (ev) {
        mode = ev.target.getAttribute('data-m');
        render();
      });
    }
  }
  render();
})();
"""


def _build_schedule_data(model):
    """模块级调度流程统计（P225-B）。

    纯从既有分析产物聚合（零重复解析）：`func.call_sites`（调用点行）+
    `model.callers_of`（被调用索引），产出：
      - hot_callees: 被调用次数最多的函数（核心调度点）
      - roots: 入度 0 的入口函数
      - edges_info: 每条调用边 {s,sr,sg, t,tr,tg, line}（供前端聚合 函数→函数 统计）
    """
    files = getattr(model, 'files', []) or []
    # 构建 (rel,name)->gid 映射供跳转（复用全局调用图，跨页缓存，开销可忽略）
    gid_of_relfn = {}
    try:
        _cg_json, gid_map = _build_global_cg(
            files,
            getattr(model, 'fn_to_file', None) or {},
            getattr(model, 'calls_of', None) or {},
            getattr(model, 'callers_of', None) or {},
            model)
        for _mf in files:
            for _f in getattr(_mf, 'functions', []) or []:
                _g = gid_map.get(id(_f))
                if _g is not None:
                    gid_of_relfn[((getattr(_mf, 'rel', '') or ''), _f.name)] = _g
    except Exception:
        pass
    rel_of = {}
    fobj = {}
    for mf in files:
        for f in getattr(mf, 'functions', []):
            rel_of[id(f)] = getattr(mf, 'rel', '') or ''
            fobj[id(f)] = f
    edges_info = []
    call_count = {}   # id(callee) -> 次数
    caller_set = {}   # id(callee) -> set(id(caller))
    out_deg = {}      # id(caller) -> 调用出的函数数
    for mf in files:
        for f in getattr(mf, 'functions', []) or []:
            seen_targets = set()
            for site in (getattr(f, 'call_sites', None) or []):
                try:
                    line0, _c0, _c1, info = site
                except Exception:
                    continue
                callee = info[0] if isinstance(info, (tuple, list)) else info
                if callee is None:
                    continue
                cid = id(callee)
                cname = getattr(callee, 'name', '?')
                crel = rel_of.get(cid, '')
                edges_info.append({
                    "s": f.name, "sr": rel_of.get(id(f), ''),
                    "t": cname, "tr": crel, "line": line0,
                })
                call_count[cid] = call_count.get(cid, 0) + 1
                caller_set.setdefault(cid, set()).add(id(f))
                seen_targets.add(cid)
            if seen_targets:
                out_deg[id(f)] = len(seen_targets)
    hot = []
    for cid, n in call_count.items():
        cf = fobj.get(cid)
        if cf is None:
            continue
        hot.append({
            "name": getattr(cf, 'name', '?'), "rel": rel_of.get(cid, ''),
            "gid": gid_of_relfn.get((rel_of.get(cid, ''), getattr(cf, 'name', '?'))),
            "n": n, "n_callers": len(caller_set.get(cid, ())),
        })
    hot.sort(key=lambda x: (-x["n"], x["name"]))
    roots = []
    for mf in files:
        for f in getattr(mf, 'functions', []) or []:
            if getattr(f, 'kind', '') == 'script':
                is_root = True
            else:
                is_root = not caller_set.get(id(f))
            if is_root:
                roots.append({
                    "name": getattr(f, 'name', '?'), "rel": rel_of.get(id(f), ''),
                    "gid": gid_of_relfn.get((rel_of.get(id(f), ''), getattr(f, 'name', '?'))),
                    "n_calls": out_deg.get(id(f), 0),
                })
    roots.sort(key=lambda x: (-x["n_calls"], x["name"]))
    return {
        "hot_callees": hot[:200],
        "roots": roots[:200],
        "edges_info": edges_info,
    }


