def _parse_builtin_doc_dims(d):
    """从 builtin_dim_line 字符串解析 (sig, inp, out)。"""
    _parts = (d or "").split("｜")
    _sig = (_parts[0] or "").strip()
    _inp = _out = ""
    for _p in _parts[1:]:
        _a = _p.find("参数（维度）：")
        if _a >= 0:
            _inp = _p[_a + 6:].strip()
        _b = _p.find("返回（维度）：")
        if _b >= 0:
            _out = _p[_b + 6:].strip()
    return _sig, _inp, _out


def _parse_dim_shape(s):
    """从文档维度字符串解析具体整型维度元组（如 '3×4'→(3,4)、'标量'→(0,)）。
    含符号维度(如 N,M)或无法解析返回 None；'未登记'返回 None。"""
    if not s or not isinstance(s, str):
        return None
    _t = s.strip()
    if not _t or "未登记" in _t:
        return None
    if "标量" in _t or "0-d" in _t.lower() or "0维" in _t:
        return (0,)
    if "向量" in _t or "1-d" in _t.lower() or "1维" in _t:
        return (1,)
    _clean = _t.replace("×", "x").replace("，", ",")
    _clean = re.sub(r"[\[\]\(\)]", "", _clean)
    _dims = []
    for _p in re.split(r"[x,×]", _clean):
        _p = _p.strip()
        if not _p:
            continue
        if not _p.isdigit():
            return None  # 含符号维度，无法判定
        _dims.append(int(_p))
    return tuple(_dims) if _dims else None


def _first_concrete_shape(real_out):
    """从 _infer_file_dims 的实测输出取首个具体整型维度元组；否则 None。"""
    if not isinstance(real_out, list) or not real_out:
        return None
    for _sh in real_out:
        if isinstance(_sh, list) and _sh and all(isinstance(_x, int) for _x in _sh):
            return tuple(_sh)
    return None


def compute_builtin_dim_checks(model, gid_of=None):
    """内置函数维度联动检测：对每个文件用真实维度引擎 _infer_file_dims 推导内置调用处
    的实际输入/输出维度，并与 MATLAB_BUILTIN_DETAILS 文档做交叉校验。

    返回 [{"rel","gid","name","calls":[{"n","line","doc_in","doc_out","real_in","real_out","status"}]}]。
    status: 'ok'(有实测输出) / 'nodoc'(文档未登记但可推导) / 'na'(未能推导)。
    """
    _rows = []
    for _mf in getattr(model, "files", []) or []:
        _src = getattr(_mf, "source_lines", None)
        if not _src or len(_src) > 8000:
            continue
        try:
            _dim_map = _infer_file_dims(
                _mf, _file_member_dims_merged(
                    _mf, _get_global_member_dims(model.files)))
        except Exception:
            _dim_map = {}
        if not _dim_map:
            continue
        for _f in getattr(_mf, "functions", []) or []:
            _gid = (gid_of.get(id(_f)) if gid_of
                    else getattr(_f, "gid", None))
            _calls = []
            _seen_call = set()
            for (_ln, _name, _k), _v in _dim_map.items():
                if (_ln, _name) in _seen_call:
                    continue
                _seen_call.add((_ln, _name))
                _d = builtin_dim_line(_name)
                _sig, _doc_in, _doc_out = _parse_builtin_doc_dims(_d)
                _real_out = _v.get("r")
                _real_in = _v.get("p")
                _status = "ok" if (_real_out and _real_out != "?") else "na"
                if _doc_out and "未登记" in _doc_out and _status == "ok":
                    _status = "nodoc"
                # 联动检测：文档标注具体维度但实测不符 → 矛盾（mismatch）
                if _status in ("ok", "nodoc"):
                    _doc_shape = _parse_dim_shape(_doc_out)
                    _real_shape = _first_concrete_shape(_real_out)
                    if _doc_shape and _real_shape and _doc_shape != _real_shape:
                        _status = "mismatch"
                _calls.append({"n": _name, "line": _ln,
                               "doc_in": _doc_in, "doc_out": _doc_out,
                               "real_in": _real_in, "real_out": _real_out,
                               "status": _status})
            if _calls:
                _rows.append({"rel": getattr(_mf, "rel", ""), "gid": _gid,
                              "name": _f.name, "calls": _calls})
    return _rows


def render_builtin_dims_check_page(model, gid_of=None):
    """生成「内置函数维度联动检测」浏览页（dims_check.html）。"""
    _rows = compute_builtin_dim_checks(model, gid_of)
    _bodies = []
    for _r in _rows:
        _ch = []
        for _c in _r["calls"]:
            _cls = {"ok": "bd-ok", "nodoc": "bd-warn", "na": "bd-na",
                     "mismatch": "bd-bad"}[_c["status"]]
            _real_out = _c["real_out"] or "未能推导"
            _real_in = (", ".join(_c["real_in"])
                        if isinstance(_c["real_in"], list) else str(_c["real_in"]))
            _ch.append(
                '<tr class="%s"><td>%s</td><td>%s</td><td>%s</td><td>%s</td>'
                '<td>%s</td><td>%s</td></tr>'
                % (_cls, _html_esc(_c["n"]), _html_esc(_c["line"]),
                   _html_esc(_real_in), _html_esc(_real_out),
                   _html_esc(_c["doc_in"] or "—"), _html_esc(_c["doc_out"] or "—")))
        _bodies.append(
            '<section class="bd-func"><h3><a href="func_detail.html?g=%s">%s</a> '
            '<span class="muted">%s</span></h3>'
            '<table class="bd-table"><thead><tr><th>内置</th><th>行</th>'
            '<th>实测输入维度</th><th>实测输出维度</th><th>文档输入</th><th>文档输出</th>'
            '</tr></thead><tbody>%s</tbody></table></section>'
            % (_html_esc(str(_r["gid"])), _html_esc(_r["name"]),
               _html_esc(_r["rel"] or ""), "".join(_ch)))
    _html = "".join(_bodies) if _bodies else '<p class="muted">无可用内置调用维度推导。</p>'
    return (
        "<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
        "<title>内置函数维度联动检测 · MATLAB 分析器</title>"
        "<link rel=\"stylesheet\" href=\"src/styles.css\"></head><body>"
        "<a class=\"skip-link\" href=\"#main\">跳到主内容</a>"
        "<header class=\"topbar\"><div class=\"brand\"><h1>内置函数维度联动检测</h1></div>"
        "<a class=\"btn\" href=\"index.html\">&larr; 返回索引</a></header>"
        "<main id=\"main\" class=\"container\">"
        "<p class=\"muted\">对每处内置函数调用，<strong>实测维度</strong>由真实维度引擎依据实参推导"
        "（联动检测输入→输出），并与文档标注交叉呈现；标注「未登记但可推导」表示文档缺失但实测可用。"
        "</p>" + _html + "</main></body></html>")


def render_builtin_dims_check_markdown(files, gid_of=None):
    """Markdown：内置函数维度联动检测摘要（用于 --output 报告）。"""
    # 用占位 model 适配器：compute_builtin_dim_checks 需要 model.files
    class _M(object):
        def __init__(self, fs):
            self.files = fs
    _rows = compute_builtin_dim_checks(_M(files), gid_of)
    if not _rows:
        return ""
    _A = ["## 内置函数维度联动检测（Builtin IO Dims）", ""]
    _n_calls = 0
    _n_nodoc = 0
    for _r in _rows:
        for _c in _r["calls"]:
            _n_calls += 1
            if _c["status"] == "nodoc":
                _n_nodoc += 1
            _real_out = _c["real_out"] or "未能推导"
            _A.append("- `%s`(%s L%d)：实测输出 **%s** ｜ 文档输出 %s"
                      % (_c["n"], _r["name"], _c["line"], _real_out,
                         _c["doc_out"] or "未登记"))
    _A.insert(1, "> 共 %d 处内置调用维度推导；其中 %d 处文档未登记但已实测推导。"
              % (_n_calls, _n_nodoc))
    return "\n".join(_A) + "\n"


STRUCT_JUMP_JS = r"""
(function(){
  // 点击结构体字段名（源码页 .fld：data-struct + data-field）→ 跳转 / 滚动到其首次定义行。
  // 跨文件、跨嵌套层级。与 data-struct/data-field 同源：点击末尾字段 token 时，按
  // 「base + 末尾字段」在前缀 / 后缀上匹配最长命中的字段路径（如 s.cfg.enable 的 enable）。
  var SF = window.__STRUCT_FIELDS__ || {};
  function pageRel(rel){ return rel + '.html'; }
  function dirOf(p){ var i = p.lastIndexOf('/'); return i < 0 ? '.' : (p.slice(0, i) || '.'); }
  function relpath(t, s){
    var ta = t.split('/'), sa = s.split('/'), i = 0;
    while(i < ta.length && i < sa.length && ta[i] === sa[i]) i++;
    var up = sa.length - i, parts = [];
    for(var k = 0; k < up; k++) parts.push('..');
    for(var k = i; k < ta.length; k++) parts.push(ta[k]);
    return parts.join('/') || '.';
  }
  function srcUrl(rel){
    var cur = window.__CURRENT_REL__ || '';
    return relpath('src/' + pageRel(rel), dirOf('src/' + pageRel(cur)));
  }
  function resolveField(base, field){
    // base 可能是根基名（如 s.pos 的 base=s），也可能是中间段（如 s.cfg.enable 的
    // enable 被标记为 base=cfg）。匹配：字段路径 fp 精确等于 base.field，或以 “.base.field”
    // 结尾（且前导字符为 '.'），避免误匹配 xs.pos 之类；取最长命中的字段路径。
    var best = null;
    var _suf = base + '.' + field;
    for(var k in SF){
      var pk = k.split('::'); if(pk.length < 2) continue;
      var fp = pk[1];
      var _li = fp.lastIndexOf(_suf);
      var _ok = (fp === _suf) || (_li >= 0 && _li === fp.length - _suf.length && (_li === 0 || fp.charAt(_li - 1) === '.'));
      if(!_ok) continue;
      if(!best || fp.length > best.fp.length) best = {fp: fp, rec: SF[k]};
    }
    return best ? best.rec : null;  // rec = [rel, line]
  }
  document.addEventListener('click', function(e){
    var t = e.target.closest ? e.target.closest('[data-field]') : null;
    if(!t) return;
    var base = t.getAttribute('data-struct'), field = t.getAttribute('data-field');
    if(!base || !field) return;
    var rec = resolveField(base, field);
    if(!rec) return;
    e.preventDefault();
    var cur = window.__CURRENT_REL__ || '';
    if(rec[0] === cur){
      var el = document.getElementById('L' + rec[1]);
      if(el){ el.scrollIntoView({block: 'center'}); el.classList.add('ln-jump');
        setTimeout(function(){ el.classList.remove('ln-jump'); }, 1500); }
    } else {
      window.location.href = srcUrl(rec[0]) + '#L' + rec[1];
    }
  }, true);
})();
"""

BUILTIN_BADGE_JS = r"""
(function(){
  // 在每处内置函数调用旁常驻显示「真实返回维度」（与 BUILTIN_DIM_JS 的徽标 / 行内 / 悬停模式无关），
  // 让「真实维度展示」无需任何交互即可见。无可靠实参维度（如 reshape 推导失败的 '?'）则不显示。
  var css = '.dim-tag{display:inline-block;margin-left:4px;padding:0 6px;border-radius:999px;'
    + 'background:#e6f4ea;color:#1a7f37;border:1px solid #a3d9b1;font-size:11px;'
    + 'font-weight:600;vertical-align:middle;white-space:nowrap;}';
  var st = document.createElement('style'); st.textContent = css; document.head.appendChild(st);
  var cells = document.querySelectorAll('.tk-builtin[data-dim]');
  for(var i = 0; i < cells.length; i++){
    var tk = cells[i];
    var d; try { d = JSON.parse(tk.getAttribute('data-dim')); } catch(e){ continue; }
    if(!d || !d.r || d.r === '?') continue;
    var b = document.createElement('span'); b.className = 'dim-tag'; b.textContent = d.r;
    b.title = '实际返回维度：' + d.r + (d.p && d.p.length ? '（实参：' + d.p.join(' , ') + '）' : '');
    if(tk.parentNode) tk.parentNode.insertBefore(b, tk.nextSibling);
  }
})();
"""

BUILTIN_DIM_JS = r"""
(function(){
  var INFO = window.__BUILTIN_INFO__ || {};
  if(!Object.keys(INFO).length) return;
  var LS = 'pony.srccdim.mode';
  var LS2 = 'pony.srccdim.filter';
  // file://（opaque origin）/ 隐私模式 / 禁用存储时 localStorage 会抛 SecurityError。
  // 必须兜底，否则此处异常会中断后续 _pageview.js（STRUCT_JUMP_JS / BUILTIN_BADGE_JS 等）执行。
  function lsGet(k){ try { return localStorage.getItem(k); } catch(e){ return null; } }
  function lsSet(k,v){ try { localStorage.setItem(k,v); } catch(e){} }
  var MODE = lsGet(LS) || 'off';
  var FILTER = lsGet(LS2) || 'all';


  function esc(s){ s = (s==null?'':String(s));
    return s.replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  function shorten(s){ s=String(s||''); return s.length>44? s.slice(0,42)+'…' : s; }
  function lineOf(tk){ var tr=tk.closest('tr'); if(!tr) return '';
    var ln=tr.querySelector('td.ln'); return ln?ln.textContent.trim():''; }
  function isNum(s){ return /^\d+$/.test(String(s||'').trim()); }
  function arityOf(tk){
    var cell=tk.closest('td')||tk.parentNode; if(!cell) return '';
    var full=cell.textContent, i=full.indexOf('('); if(i<0) return '';
    var depth=0, args=1;
    for(var j=i;j<full.length;j++){ var c=full[j];
      if(c==='(') depth++; else if(c===')'){ depth--; if(depth===0) break; }
      else if(c===','&&depth===1) args++; }
    var inner=full.slice(i+1,j).trim(); return inner===''?0:args;
  }
  function funcCtx(){ var el=document.querySelector('.func-name')||document.querySelector('.fn-name')||document.querySelector('h1');
    return el?el.textContent.trim():''; }

  var box = document.createElement('div'); box.className='src-dim-box'; document.body.appendChild(box);
  var boxName=document.createElement('div'); boxName.className='sdb-name';
  var boxBody=document.createElement('div');
  var boxFoot=document.createElement('div'); boxFoot.className='sdb-foot';
  var copyBtn=document.createElement('button'); copyBtn.className='sdb-copy'; copyBtn.textContent='复制';
  var xlink=document.createElement('span'); xlink.className='sdb-xlink'; xlink.textContent='维度视图 ↗'; xlink.title='在维度视图中查看该内置函数';
  boxFoot.appendChild(copyBtn); boxFoot.appendChild(xlink);
  box.appendChild(boxName); box.appendChild(boxBody); box.appendChild(boxFoot);
  box.setAttribute('role','dialog'); box.setAttribute('aria-label','内置函数维度详情');
  box._pinned=false; box._name=null;
  xlink.addEventListener('click', function(e){ e.stopPropagation();
    var n=box._name; if(n) window.open('dims.html#bd-'+encodeURIComponent(n), '_blank'); });

  function readDim(tk){ try{ return tk.dataset.dim ? JSON.parse(tk.dataset.dim) : null; }catch(e){ return null; } }
  function badgeHtml(name, d, dim){
    var h = esc(name);
    if(dim) h += ' <span style="background:#e6f4ea;color:#1a7f37;border:1px solid #a3d9b1;'
        + 'padding:0 6px;border-radius:999px;font-size:11px;font-weight:400;">实测</span>';
    else if(d.generic) h += ' <span style="background:#f3ecff;color:#8250df;border:1px solid #d8b9ff;'
        + 'padding:0 6px;border-radius:999px;font-size:11px;font-weight:400;">推断</span>';
    return h;
  }
  function rowsHtml(d, ctx, arity, line, dim){
    var h='';
    if(line) h+='<div class="sdb-line">源码位置：L'+esc(line)+'</div>';
    h+='<div class="sdb-row"><span class="sdb-k">签名</span><span>'+esc(d.sig||'—')+'</span></div>';
    if(arity!==''&&arity!=null) h+='<div class="sdb-row"><span class="sdb-k">实参</span><span>'+esc(arity)+' 个参数</span></div>';
    if(dim){
      var ps=(dim.p&&dim.p.length)? dim.p.join(' , ') : '—';
      h+='<div class="sdb-row"><span class="sdb-k">实际参数维度</span><span>'+esc(ps)+'</span></div>';
      h+='<div class="sdb-row"><span class="sdb-k">实际返回维度</span><span>'+esc(dim.r||'—')+'</span></div>';
      if(dim.note) h+='<div class="sdb-row"><span class="sdb-k">说明</span><span>'+esc(dim.note)+'</span></div>';
    } else {
      h+='<div class="sdb-row"><span class="sdb-k">参数维度</span><span>'+esc(d.params||'—')+'</span></div>';
      h+='<div class="sdb-row"><span class="sdb-k">返回维度</span><span>'+esc(d.returns||'—')+'</span></div>';
    }
    if(d.note) h+='<div class="sdb-row"><span class="sdb-k">备注</span><span>'+esc(d.note)+'</span></div>';
    if(ctx) h+='<div class="sdb-ctx">'+ctx+'</div>';
    return h;
  }
  function showBox(name, d, ctx, anchor, arity, line, dim){
    boxName.innerHTML = badgeHtml(name, d, dim);
    boxBody.innerHTML = rowsHtml(d, ctx, arity, line, dim);
    box.classList.add('open');
    var bw=box.offsetWidth, bh=box.offsetHeight, r=anchor.getBoundingClientRect();
    var left=Math.max(8, Math.min(r.left, window.innerWidth - bw - 8));
    var top=r.bottom + window.scrollY + 6;
    var maxTop=window.scrollY + window.innerHeight - bh - 8;
    if(top>maxTop) top=Math.max(window.scrollY+8, maxTop);
    box.style.left=left+'px'; box.style.top=top+'px';
    box.setAttribute('aria-expanded','true');
    box._name=name; box._pinned=true;
  }
  function hideBox(){ box.classList.remove('open'); box._pinned=false; box._name=null; }
  function toggleBox(name, d, ctx, anchor, arity, line, dim){
    if(box._pinned && box._name===name){ hideBox(); }
    else { showBox(name, d, ctx, anchor, arity, line, dim); }
  }
  function jumpTo(ln){
    if(!isNum(ln)) return;
    var el=document.getElementById('L'+ln); if(!el) return;
    el.scrollIntoView({block:'center'});
    el.classList.add('ln-jump');
    setTimeout(function(){ el.classList.remove('ln-jump'); }, 1500);
  }

  // 浮动工具栏：模式切换 / 过滤 / 复制全部 / 汇总列表
  var bar=document.createElement('div'); bar.className='src-dim-bar';
  bar.innerHTML='<span class="sdb-stat" id="sdb-stat"></span>'
    + '<button class="sdb-btn" data-m="off">关闭</button>'
    + '<button class="sdb-btn" data-m="badge">徽标</button>'
    + '<button class="sdb-btn" data-m="inline">行内</button>'
    + '<span class="sdb-sep"></span>'
    + '<button class="sdb-btn" data-f="all">全部</button>'
    + '<button class="sdb-btn" data-f="reg">仅登记</button>'
    + '<span class="sdb-sep"></span>'
    + '<button class="sdb-btn" id="sdb-copyall">复制全部</button>'
    + '<button class="sdb-btn" id="sdb-summary">列表</button>';
  document.body.appendChild(bar);
  function syncBar(){ Array.prototype.forEach.call(bar.querySelectorAll('.sdb-btn[data-m]'), function(b){
    b.classList.toggle('on', b.getAttribute('data-m')===MODE); });
    Array.prototype.forEach.call(bar.querySelectorAll('.sdb-btn[data-f]'), function(b){
    b.classList.toggle('on', b.getAttribute('data-f')===FILTER); }); }
  bar.addEventListener('click', function(e){
    var b=e.target.closest('.sdb-btn'); if(!b) return;
    if(b.hasAttribute('data-m')){ MODE=b.getAttribute('data-m'); lsSet(LS, MODE); }
    else if(b.hasAttribute('data-f')){ FILTER=b.getAttribute('data-f'); lsSet(LS2, FILTER); }
    else if(b.id==='sdb-copyall'){ copyAll(); return; }
    else if(b.id==='sdb-summary'){ toggleSummary(); return; }
    syncBar(); build();
  });
  syncBar();
  function copyAll(){
    var txt=[]; GROUPS.forEach(function(g){ var d=INFO[g.name];
      txt.push(g.name+(d.generic?'（推断）':'')+' | '+d.sig+' | 参数: '+d.params+' | 返回: '+d.returns); });
    if(navigator.clipboard&&navigator.clipboard.writeText) navigator.clipboard.writeText(txt.join('\n'));
    var b=document.getElementById('sdb-copyall'); if(b){ b.textContent='已复制'; setTimeout(function(){b.textContent='复制全部';},1200);} }
  function toggleSummary(){ var p=document.getElementById('sdb-summary-panel'); if(p) p.classList.toggle('open'); }
  document.addEventListener('keydown', function(e){
    if(e.key==='Escape'){ hideBox(); return; }
    var tag=(document.activeElement&&document.activeElement.tagName)||'';
    if(tag==='INPUT'||tag==='TEXTAREA') return;
    if(e.key==='d'||e.key==='D'){ MODE=(MODE==='off'?'badge':'off'); lsSet(LS,MODE); syncBar(); build(); }
    else if(e.key==='i'||e.key==='I'){ var seq=['badge','inline','off']; MODE=seq[(seq.indexOf(MODE)+1)%seq.length];
      lsSet(LS,MODE); syncBar(); build(); }
  });

  var GROUPS=[], OCC={}, io=null;
  if('IntersectionObserver' in window){
    io=new IntersectionObserver(function(ents){ ents.forEach(function(en){
      if(en.isIntersecting && en.target._pend){ var p=en.target._pend; en.target._pend=null;
        attach(p.tk,p.g,p.k,p.idx); io.unobserve(en.target); } }); }, {rootMargin:'240px 0px'});
  }
  function adjacent(a,b){ var la=lineOf(a), lb=lineOf(b);
    return isNum(la) && isNum(lb) && (parseInt(lb,10)-parseInt(la,10)===1); }

  function attach(tk, g, k, idx){
    var name=g.name, d=INFO[name];
    if(MODE==='off') return;
    if(FILTER==='reg' && d.generic) return;
    var ar=arityOf(tk), line=lineOf(tk);
    if(MODE==='inline'){
      var el=document.createElement('div'); el.className='src-dim-inline'+(d.generic?' generic':'');
      var dim=readDim(tk);
      el.innerHTML='<div class="sdb-name">'+badgeHtml(name,d,dim)+'</div>'+rowsHtml(d, g.ctx, ar, line, dim);
      el.addEventListener('click', function(e){ if(e.target.closest('.sdb-name')) el.classList.toggle('collapsed'); });
      tk.parentNode.insertBefore(el, tk.nextSibling);
      return;
    }
    var chip=document.createElement('span'); chip.className='src-dim'+(d.generic?' generic':''); chip.tabIndex=0;
    chip.setAttribute('role','button'); chip.setAttribute('aria-expanded','false');
    var dim=readDim(tk);
    var retTxt = dim ? dim.r : (d.returns||'');
    var label='ⓘ '+shorten(retTxt || '—')+(ar!==''&&ar!=null?(' ('+ar+' 参)'):'')+(dim?' · 实测':'');
    if(k>1 && idx===0) label+=' ×'+k;
    chip.textContent=label;
    chip.title='点击/悬停查看「'+name+'」维度与前后调用上下文（Enter 展开，Esc 关闭；快捷键 d 切换 / i 循环密度）';
    var hT=null;
    chip.addEventListener('click', function(e){ e.stopPropagation(); toggleBox(name, d, g.ctx, chip, ar, line, dim); });
    chip.addEventListener('mouseenter', function(){ if(box._pinned) return; clearTimeout(hT);
      hT=setTimeout(function(){ showBox(name, d, g.ctx, chip, ar, line, dim); chip.setAttribute('aria-expanded','true'); }, 180); });
    chip.addEventListener('mouseleave', function(){ clearTimeout(hT); if(!box._pinned){ hideBox(); chip.setAttribute('aria-expanded','false'); } });
    chip.addEventListener('keydown', function(e){
      if(e.key==='Enter'||e.key===' '){ e.preventDefault(); toggleBox(name, d, g.ctx, chip, ar, line); } });
    tk.parentNode.insertBefore(chip, tk.nextSibling);
  }

  function build(){
    var src=document.querySelector('.src');
    if(!src){ bar.style.display='none'; return; }
    bar.style.display='';
    Array.prototype.forEach.call(src.querySelectorAll('.src-dim,.src-dim-inline'),
      function(e){ if(e.parentNode) e.parentNode.removeChild(e); });
    if(io){ Array.prototype.forEach.call(src.querySelectorAll('tr'), function(tr){ tr._pend=null; }); }
    var toks=[]; var withDim=0;
    Array.prototype.forEach.call(src.querySelectorAll('.tk-builtin'), function(tk){
      if(INFO[tk.textContent]){ toks.push(tk); if(tk.dataset.dim) withDim++; } });
    GROUPS=[]; OCC={};
    toks.forEach(function(tk){ var n=tk.textContent; var last=GROUPS.length?GROUPS[GROUPS.length-1]:null;
      if(last && last.name===n && adjacent(last.last, tk)) last.items.push(tk);
      else { GROUPS.push({name:n, items:[tk], last:tk}); }
      if(!OCC[n]) OCC[n]={count:0, lines:[]}; OCC[n].count++; OCC[n].lines.push(lineOf(tk)); });
    var reg=0, fctx=funcCtx();
    GROUPS.forEach(function(g, gi){
      if(!INFO[g.name].generic) reg++;
      var prev = gi>0 ? GROUPS[gi-1].name : null;
      var next = gi<GROUPS.length-1 ? GROUPS[gi+1].name : null;
      var prevLn = gi>0 ? lineOf(GROUPS[gi-1].items[0]) : '';
      var nextLn = gi<GROUPS.length-1 ? lineOf(GROUPS[gi+1].items[0]) : '';
      var ctx='调用序列：第 '+(gi+1)+' / '+GROUPS.length+' 次调用';
      if(fctx) ctx='所在：'+esc(fctx)+' ｜ '+ctx;
      if(prev) ctx+=' ｜ 前一次：<span class="sdb-jump" data-ln="'+esc(prevLn)+'">'+esc(prev)+'</span>（L'+esc(prevLn)+'）';
      if(next) ctx+=' ｜ 后一次：<span class="sdb-jump" data-ln="'+esc(nextLn)+'">'+esc(next)+'</span>（L'+esc(nextLn)+'）';
      g.ctx=ctx;
      g.items.forEach(function(tk, idx){
        if(io){ var row=tk.closest('tr')||tk; row._pend={tk:tk,g:g,k:g.items.length,idx:idx}; io.observe(row); }
        else attach(tk, g, g.items.length, idx);
      });
    });
    var st=document.getElementById('sdb-stat');
    if(st) st.textContent='共 '+GROUPS.length+' 处调用 · '+Object.keys(OCC).length+' 个内置函数 · 已登记 '+reg
      + (withDim? ' · 实测维度 '+withDim : '');
    buildSummary(src);
  }
  function buildSummary(src){
    var old=document.getElementById('sdb-summary-panel'); if(old&&old.parentNode) old.parentNode.removeChild(old);
    if(!Object.keys(OCC).length) return;
    var p=document.createElement('div'); p.id='sdb-summary-panel'; p.className='src-dim-summary';
    var html='<b>本文件调用的内置函数（点击跳转首个出现处）：</b> ';
    Object.keys(OCC).sort().forEach(function(n){ var d=INFO[n];
      html+='<span class="sds-item'+(d.generic?' generic':'')+'" data-name="'+esc(n)+'" data-ln="'+esc(OCC[n].lines[0])+'">'
        +esc(n)+' ×'+OCC[n].count+'</span>'; });
    p.innerHTML=html;
    if(src.parentNode) src.parentNode.insertBefore(p, src);
  }

  copyBtn.addEventListener('click', function(e){
    e.stopPropagation();
    var t=(boxName.textContent||'')+' | '+(boxBody.innerText||boxBody.textContent||'');
    if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(t); }
    copyBtn.textContent='已复制'; setTimeout(function(){ copyBtn.textContent='复制'; }, 1200);
  });
  document.addEventListener('click', function(e){
    var j=e.target.closest && e.target.closest('.sdb-jump');
    if(j){ e.stopPropagation(); jumpTo(j.getAttribute('data-ln')); return; }
    var s=e.target.closest && e.target.closest('.sds-item');
    if(s){ e.stopPropagation(); jumpTo(s.getAttribute('data-ln')); return; }
    if(box.contains(e.target)) return;
    hideBox();
  });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') hideBox(); });
  window.addEventListener('resize', hideBox);
  // ===== 浮动导航：返回顶部 / 底部 / 进度条 / 行号高亮 / 快捷键 =====
  (function(){
    var nav = document.createElement('div');
    nav.id = 'src-float-nav';
    nav.innerHTML =
      '<div id="sfn-progress"><div id="sfn-progress-bar"></div></div>'
      + '<button id="sfn-top" title="返回顶部 (Home)" aria-label="返回顶部">&#x2302;</button>'
      + '<button id="sfn-bottom" title="跳转底部 (End)" aria-label="跳转底部">&#x2304;</button>'
      + '<span id="sfn-pos" title="当前行号/总行数"></span>';
    document.body.appendChild(nav);



    var topBtn = document.getElementById('sfn-top');
    var botBtn = document.getElementById('sfn-bottom');
    var posEl = document.getElementById('sfn-pos');
    var progBar = document.getElementById('sfn-progress-bar');
    var progWrap = document.getElementById('sfn-progress');

    topBtn.addEventListener('click', function(){ window.scrollTo({top:0,behavior:'smooth'}); });
    botBtn.addEventListener('click', function(){ window.scrollTo({top:document.documentElement.scrollHeight,behavior:'smooth'}); });
    progWrap.addEventListener('click', function(e){
      var r = progWrap.getBoundingClientRect();
      var pct = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width));
      window.scrollTo({top: pct * (document.documentElement.scrollHeight - window.innerHeight), behavior:'smooth'});
    });

    var _totalLines = 0;
    function countLines(){
      var t = document.querySelector('table.src');
      if(!t) return 0;
      return t.querySelectorAll('tr').length;
    }
    function currentLine(){
      var t = document.querySelector('table.src');
      if(!t) return 0;
      var rows = t.querySelectorAll('tr');
      var mid = window.innerHeight / 2;
      for(var i=0;i<rows.length;i++){
        var r = rows[i].getBoundingClientRect();
        if(r.top <= mid && r.bottom >= mid) return i+1;
      }
      return rows.length;
    }

    var _raf;
    function updateNav(){
      cancelAnimationFrame(_raf);
      _raf = requestAnimationFrame(function(){
        var st = window.pageYOffset || document.documentElement.scrollTop;
        var dh = document.documentElement.scrollHeight - window.innerHeight;
        var pct = dh > 0 ? st / dh : 0;
        progBar.style.width = (pct * 100) + '%';
        topBtn.style.display = (st > 200) ? '' : 'none';
        if(_totalLines > 0){
          var cl = currentLine();
          posEl.textContent = cl + '/' + _totalLines;
          posEl.style.display = '';
        } else {
          posEl.style.display = 'none';
        }
      });
    }

    // 初始化
    setTimeout(function(){
      _totalLines = countLines();
      updateNav();
    }, 300);
    window.addEventListener('scroll', updateNav, {passive:true});
    window.addEventListener('resize', function(){
      _totalLines = countLines(); updateNav();
    }, {passive:true});

    // 快捷键增强：Home/End 已有浏览器默认，这里加 t/b 快捷键
    document.addEventListener('keydown', function(e){
      var tag = (document.activeElement && document.activeElement.tagName) || '';
      if(tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      if(e.key === 't' && !e.ctrlKey && !e.metaKey && !e.altKey){
        e.preventDefault(); window.scrollTo({top:0,behavior:'smooth'}); }
      else if(e.key === 'b' && !e.ctrlKey && !e.metaKey && !e.altKey){
        e.preventDefault(); window.scrollTo({top:document.documentElement.scrollHeight,behavior:'smooth'}); }
    });

    // 当前行高亮
    var _hlRow = null;
    function highlightCurrentRow(){
      var t = document.querySelector('table.src');
      if(!t) return;
      var rows = t.querySelectorAll('tr');
      var mid = window.innerHeight / 2;
      for(var i=0;i<rows.length;i++){
        var r = rows[i].getBoundingClientRect();
        if(r.top <= mid && r.bottom >= mid){
          if(_hlRow !== rows[i]){
            if(_hlRow) _hlRow.classList.remove('sfn-hl');
            _hlRow = rows[i];
            _hlRow.classList.add('sfn-hl');
          }
          return;
        }
      }
      if(_hlRow){ _hlRow.classList.remove('sfn-hl'); _hlRow = null; }
    }
    var _hlRaf;
    window.addEventListener('scroll', function(){
      cancelAnimationFrame(_hlRaf);
      _hlRaf = requestAnimationFrame(highlightCurrentRow);
    }, {passive:true});


  })();

  // ===== 双击行号复制行内容 + Ctrl+F 搜索增强 =====
  (function(){
    // 双击 td.ln 复制该行源码文本
    document.addEventListener('dblclick', function(e){
      var td = e.target;
      if(!td || !td.classList.contains('ln')) return;
      var tr = td.parentElement;
      if(!tr) return;
      var codeTd = tr.querySelector('td.code');
      if(!codeTd) return;
      var text = codeTd.textContent || '';
      text = text.replace(/\s+$/,'');
      if(navigator.clipboard && navigator.clipboard.writeText){
        navigator.clipboard.writeText(text).then(function(){
          var o = td; o.style.backgroundColor='rgba(16,185,129,.25)';
          setTimeout(function(){ o.style.backgroundColor=''; }, 500);
        });
      }
    }, true);

    // Ctrl+F / F3 时自动聚焦到源码表格（避免搜索命中在侧栏）
    document.addEventListener('keydown', function(e){
      if((e.key === 'f' && (e.ctrlKey || e.metaKey)) || e.key === 'F3'){
        var t = document.querySelector('table.src');
        if(t) t.setAttribute('tabindex','-1');
      }
    });
  })();

  // ===== 快捷键提示条（首次访问显示，5秒后自动淡出） =====
  (function(){
    var _hget = function(k){ try { return localStorage.getItem(k); } catch(e){ return null; } };
    var _hset = function(k,v){ try { localStorage.setItem(k,v); } catch(e){} };
    if(_hget('pony.sfn.hint')) return;
    var hint = document.createElement('div');
    hint.id = 'sfn-hint-bar';
    hint.innerHTML = '<span>快捷键: <b>T</b> 顶部 &middot; <b>B</b> 底部 &middot; <b>F</b> 搜索 &middot; 双击行号复制</span>'
      + '<button id="sfn-hint-close" aria-label="关闭提示">&times;</button>';

    document.body.appendChild(hint);
    var closeBtn = document.getElementById('sfn-hint-close');
    closeBtn.addEventListener('click', function(){ hint.style.opacity='0'; setTimeout(function(){hint.remove();},300); _hset('pony.sfn.hint','1'); });
    setTimeout(function(){ if(hint.parentNode){ hint.style.opacity='0'; setTimeout(function(){if(hint.parentNode)hint.remove();},300); _hset('pony.sfn.hint','1'); } }, 5000);
  })();

  if(document.readyState!=='loading') build();
  else document.addEventListener('DOMContentLoaded', build);
})();
"""


# P224-Z：渲染隔离——单个页面生成失败只降级该页并上报，不中断整站生成。
# 历史教训：struct_members.html 曾因形状标记越界抛 IndexError，令整个
# render_browse_site 异常、整份 HTML 报告全废。改为单页 try/except + 占位页 + 可观测清单。
_RENDER_ERRORS = []


def _safe_page(outdir, name, render_fn):
    """安全写页面：render_fn() 抛异常时写占位页并记入 _RENDER_ERRORS，绝不中断整站。

    render_fn 可为可调用（惰性求值，便于捕获其内部异常）或直接 HTML 字符串。
    返回 True/False 表示是否成功写出。
    """
    global _RENDER_ERRORS
    try:
        _html = render_fn() if callable(render_fn) else render_fn
        (outdir / name).write_text(_html, encoding="utf-8")
        return True
    except Exception as _e:
        _RENDER_ERRORS.append((name, repr(_e)))
        print("[WARN] 页面 %s 渲染失败（降级为占位页）：%s" % (name, _e))
        try:
            (outdir / name).write_text(
                "<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
                "<title>%s（渲染异常）</title></head><body>"
                "<h1>%s 渲染异常</h1>"
                "<p>该页面生成时发生错误，已跳过以保证整站可用。错误：<code>%s</code></p>"
                "<p><a href=\"index.html\">返回索引</a></p></body></html>"
                % (name, name, _html_esc(str(_e))), encoding="utf-8")
        except Exception:
            pass
        return False


def render_browse_site(model, outdir, reproducible=False, enabled=None,
                       max_nodes=None, offline=False, ai_mode="off",
                       checks_for_sarif=None):
    """生成可交互跳转的 HTML 源码浏览站点。返回入口 index.html 路径。

    model：统一分析数据层（build_analysis_model 返回值），包含 files / index /
    fn_to_file / callers_of / calls_of / stats / root / rel 等全部派生数据，
    由 main 统一构建后传入，避免在多个渲染函数间重复计算。
    enabled：启用的静态检查名集合（None = 全部），用于告警阈值配置化。
    reproducible=True 时省略索引页生成时间戳（P51）。
    """
    files = model.files
    # P225-F：AI CLI 引入时机。off=不引入；prompts=仅离线提示词；
    # ask=运行结束交互询问是否调用；auto=自动调用（需已配置 provider/密钥）。
    ai = ai_mode != "off"
    index = model.index
    stats = model.stats
    root = model.root
    rel = model.rel
    fn_to_file = model.fn_to_file
    callers_of = model.callers_of
    calls_of = model.calls_of
    outdir = Path(outdir)
    src_dir = outdir / "src"
    # P224-Z：清空上轮渲染错误清单（每次生成独立计数）
    _RENDER_ERRORS.clear()
    # P48：生成前清理上一轮遗留的旧页面，避免「幽灵函数」残留
    _clean_browse_dir(outdir)
    src_dir.mkdir(parents=True, exist_ok=True)

    # 1) 每个源码文件生成一个页面（页面路径使用原始相对路径，避免 + 文件夹断链）
    # 全局调用图邻接表仅构建一次（跨页缓存），写入共享 src/_cgdata.js，供各源码页
    # 前端按需下钻渲染（彻底替代旧版「按 MAX_CALLGRAPH_DEPTH 截断」的服务端 SVG）。
    cg_json, _gid_of = _build_global_cg(files, fn_to_file, calls_of, callers_of, model,
                                        max_nodes=max_nodes)
    (src_dir / "_cgdata.js").write_text(
        "window.__CG__=%s;" % cg_json, encoding="utf-8")
    # P107：全站函数搜索浮层（复用 __CG__.meta，Ctrl+K 跳转函数详情，离线零依赖）
    # P270：前置拼接共享内核 CORE_JS（主题统一），使所有引用 _search.js 的页面
    #       自动获得一致的主题行为，无需各页重复实现。
    (src_dir / "_search.js").write_text(CORE_JS + "\n" + KBD_JS + "\n" + GLOBAL_SEARCH_JS,
                                        encoding="utf-8")
    # P-rev R35：按需加载搜索模块。写一个极小的「懒加载桩」_search-lazy.js：
    # 它只安装 Ctrl+K / '/' 监听与「首次滚动」触发，第一次真正需要时才动态注入
    # 完整 _search.js（38KB）。这样 38KB 从首屏关键路径上移除，功能完全不变。
    (src_dir / "_search-lazy.js").write_text(LAZY_SEARCH_JS, encoding="utf-8")
    # P-rev S2：跨页上下文联动总线——点击任意带 data-sym 的符号，广播到 localStorage，
    # 其它已打开的页面监听到后自动高亮同名符号并滚动定位（信息主动找人）。
    (src_dir / "_ctxlink.js").write_text(CONTEXT_LINK_JS, encoding="utf-8")
    # P-rev S4：个人工作台（标注/收藏/最近视图），纯本地持久。
    (src_dir / "_workbench.js").write_text(WORKBENCH_JS, encoding="utf-8")
    # P-rev R9：设计令牌 + 暗色主题切换。
    (src_dir / "_theme.js").write_text(THEME_JS, encoding="utf-8")
    # P-rev R22：统一符号消费层（运行时按 symbols.json 自动标注 data-sym）。
    (src_dir / "_symbols.js").write_text(SYMBOLS_JS, encoding="utf-8")
    # P-rev R27：调用图模块外链化（源码页共享，避免每页内联 63KB）。
    (src_dir / "_localcg.js").write_text(LOCALCG_INIT_JS, encoding="utf-8")
    # P-rev R80：变量流 + 源码行深链两模块外链化——此前每个源码页各内联
    # VARFLOW_JS 与 LINE_DEEPLINK_JS 一份，N 个源码文件即重复 N 份；两份脚本
    # 均只读 DOM、无页面私有数据，收编为站点级 _pageview.js 一次写入即可。
    # R-本轮：把「全部内置函数维度信息」一次性注入站点级 _pageview.js，
    # 源码页加载后即在每个 .tk-builtin 调用处渲染静态维度徽标 + 可展开的前后调用上下文框。
    _bi_used = set()
    for _mf in files:
        for _fn in getattr(_mf, "functions", []) or []:
            for _b in (getattr(_fn, "builtin_calls", {}) or {}):
                _bi_used.add(_b)
    _bi_info = {_b: builtin_detail_obj(_b) for _b in _bi_used}
    # 全局结构体字段索引：供前端点击字段名跳转到其定义处（跨文件 / 跨嵌套层级）。
    # P224-Z：隔离——该索引曾因形状标记越界整站崩溃；现单点 try/except 降级为空索引。
    try:
        _sf_idx = collect_struct_field_index(files)
    except Exception as _e:
        print("[WARN] 结构体字段索引生成失败（降级为空索引）：%s" % _e)
        _sf_idx = {}
    # D-R11：结构体字段索引同样固定键序，避免跨进程哈希随机化污染产物
    _sf_js = ("window.__STRUCT_FIELDS__="
              + json.dumps(_sf_idx, ensure_ascii=False, sort_keys=True) + ";\n")
    # D-R11：--reproducible 曾**未兑现**。真因在 `_bi_info`：
    #     _bi_info = {_b: builtin_detail_obj(_b) for _b in _bi_used}   # _bi_used 是 set
    #   str 的哈希随机化（PYTHONHASHSEED）使 set 的迭代顺序跨进程漂移，于是
    #   json.dumps 出来的键序跟着漂移 ⇒ `src/_pageview.js` 两次生成逐字节不同，
    #   并级联污染 manifest.json（它记录每页 sha256，是**下游受害文件**）。
    #   修法：固定键序。这是「同一份输入 → 同一份字节」的最小充分条件。
    _bi_js = ("window.__BUILTIN_INFO__="
              + json.dumps(_bi_info, ensure_ascii=False, sort_keys=True)
              + ";\n" + _sf_js)
    (src_dir / "_pageview.js").write_text(
        VARFLOW_JS + "\n" + LINE_DEEPLINK_JS + "\n" + _bi_js
        + BUILTIN_DIM_JS + "\n" + STRUCT_JUMP_JS + "\n" + BUILTIN_BADGE_JS,
        encoding="utf-8")
    # FE-6：共享样式表外链化（消除每页 ~950 行 BROWSE_CSS 内联重复，浏览器缓存一次）
    (src_dir / "styles.css").write_text(BROWSE_CSS, encoding="utf-8")
    # P-rev R17：统一符号数据层 symbols.json —— 把「符号标识 + 类型 + 定义位置 +
    # 直接被调用数 + 传递影响闭包」一次性落盘，前端所有联动/引导只消费该文件，
    # 不再逐模板拼 data-sym 键（避免遗漏与不一致）。
    _symbols = []
    _caller_ids = {id(_f): [id(c) for c in callers_of.get(id(_f), [])]
                   for _mf in files for _f in _mf.functions}
    # id(f) -> 符号 id，便于把闭包结果转成「受影响符号 id 列表」供前端高亮
    _sym_of = {}
    for _mf in files:
        for _f in _mf.functions:
            _sym_of[id(_f)] = "%s::%s" % (_mf.rel, _f.name)
    # P-rev R23：正向依赖闭包所需的「被调方 id」邻接表。
    # calls_of 的项为 (callee_fn, dmf)——第一项是**被调函数对象**而非名字，
    # 直接用 id() 建邻接即可，无需按名解析（按名解析会在同名函数上错配）。
    _known_ids = {id(_f) for _mf in files for _f in _mf.functions}
    _callee_ids = {}
    for _mf in files:
        for _f in _mf.functions:
            _cs = []
            for _entry in (calls_of.get(id(_f), []) or []):
                try:
                    _cfn = _entry[0]
                except (IndexError, TypeError):
                    continue
                if _cfn is None:
                    continue
                _cid = id(_cfn)
                if _cid in _known_ids and _cid not in _cs:
                    _cs.append(_cid)
            _callee_ids[id(_f)] = _cs
    for _mf in files:
        for _f in _mf.functions:
            _seen, _q = set(), list(_caller_ids.get(id(_f), []))
            for _c in _q:
                if _c not in _seen:
                    _seen.add(_c)
                    _q.extend(_caller_ids.get(_c, []))
            # P-rev R19：一并落盘「受影响符号 id 列表」，供调用图高亮波及子树
            # P-rev R51：_seen 是 set，跨 PYTHONHASHSEED 迭代顺序不定，会破坏可复现
            # 构建（P51 逐字节比对）。先映射成符号 id 再排序，保证输出确定性。
            _impacts = sorted(_sym_of[c] for c in _seen if c in _sym_of)
            # P-rev R23：反向闭包——「改 X 需要依赖谁」（X 传递调用到的全部函数）
            _dseen, _dq = set(), list(_callee_ids.get(id(_f), []))
            for _c in _dq:
                if _c not in _dseen:
                    _dseen.add(_c)
                    _dq.extend(_callee_ids.get(_c, []))
            _deps = sorted(_sym_of[c] for c in _dseen if c in _sym_of)
            _symbols.append({
                "id": "%s::%s" % (_mf.rel, _f.name),
                "rel": _mf.rel,
                "name": _f.name,
                "kind": "method" if getattr(_f, "cls", None) else "function",
                "cls": getattr(getattr(_f, "cls", None), "name", None),
                "line": _f.line,
                "end_line": getattr(_f, "end_line", None),
                "fan_in": len(callers_of.get(id(_f), [])),
                "impact": len(_seen),
                "impacts": _impacts,
                "dep_count": len(_deps),
                "deps": _deps,
                # P225-L：间接调用（cell 元素/索引后/动态字段方法），目标运行期确定，
                # 不计入精确调用边，提示性暴露以避免调用图「看不到调用」。
                "indirect_calls": dict(sorted(getattr(_f, "indirect_calls", {}).items())),
                # P225-M：索引样式调用（A(:)/A(end)/A(1) 等疑似数组索引，非函数调用），标注性。
                "index_like_calls": dict(sorted(getattr(_f, "index_like_calls", {}).items())),
            })
        for _cl in _mf.classes:
            # P-rev R28：类与同名构造函数会撞 id（MyCls.m::MyCls 既指类也指构造函数），
            # 二者共存时后写入的会覆盖前者，导致联动/高亮指向错误。给类加 class: 前缀。
            _symbols.append({
                "id": "%s::class:%s" % (_mf.rel, _cl.name),
                "rel": _mf.rel, "name": _cl.name, "kind": "class",
                "cls": _cl.name, "line": _cl.line, "end_line": None,
                "fan_in": 0, "impact": 0, "impacts": [],
                "dep_count": 0, "deps": [],
            })
    (src_dir / "symbols.json").write_text(
        json.dumps({"v": 1, "symbols": _symbols}, ensure_ascii=False), encoding="utf-8")
    # P-rev R36：符号层分片。大项目下 symbols.json 会随函数数线性膨胀（每个符号还带
    # impacts/deps 两个闭包数组），全量加载既慢又费内存。按「顶层目录」切分，
    # 前端只按需加载当前文件所在目录的分片。保留全量 symbols.json 仅作兼容，
    # manifest 记录分片清单，供前端与审计定位。
    _shards = {}
    for _s in _symbols:
        _rel = _s.get("rel", "")
        _dir = _rel.split("/")[0] if "/" in _rel else "."
        _shards.setdefault(_dir, []).append(_s)
    _manifest = {"v": 1, "shards": {}}
    for _dir, _items in sorted(_shards.items()):
        _fname = "symbols-%s.json" % (_dir.replace("/", "_").replace("\\", "_") or "root")
        (src_dir / _fname).write_text(
            json.dumps({"v": 1, "dir": _dir, "symbols": _items}, ensure_ascii=False),
            encoding="utf-8")
        _manifest["shards"][_dir] = {"file": _fname, "count": len(_items)}
    (src_dir / "symbols-manifest.json").write_text(
        json.dumps(_manifest, ensure_ascii=False), encoding="utf-8")
    # P100/P101：目录树模型与文件依赖图（挂载到 model，供 JSON 输出与页面消费）
    model.dirs = _build_dir_tree(files)
    model.files_graph = _build_file_dep_graph(files, calls_of)
    # P104：函数详情页（单模板页 + 预注入污点/行动单标志，前端按 ?g= 渲染）
    _cg_obj = json.loads(cg_json)
    _fd_flags = _fd_extra_flags(model, _cg_obj.get("meta") or [])
    _safe_page(outdir, "func_detail.html",
               lambda: render_func_detail_page(model, cg_json, _fd_flags, _gid_of))
    # P201/P202：统一画布页（folder/file/function/variable 四类节点 + contain/flow 边）
    _safe_page(outdir, "unified.html",
               lambda: render_unified_page(cg_json))
    # P203：跨层闭环页面（文件夹影响面 / 变量污点溯源）
    _p203_shell = (
        "<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"/>"
        "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"/>"
        "<script>(function(){try{var t=localStorage.getItem('gs-theme');"
        "if(!t){t=(window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light';}"
        "if(t==='dark'){document.documentElement.setAttribute('data-theme','dark');}}catch(e){}})();</script>"
        "<title>__TITLE__ · MATLAB 分析器</title><link rel=\"stylesheet\" href=\"src/styles.css\"><link rel=\"stylesheet\" href=\"focus.css\"></head><body>"
        # P271 R5：无障碍基线——跳转到主内容的 skip link + <main> 语义地标
        '<a class="skip-link" href="#main-content">跳到主内容</a>'
        "<header class=\"site-head\"><div class=\"head-in\">"
        "<h1 class=\"brand\">__BRAND__</h1>"
        "<span class=\"brand-sub\">MATLAB 静态分析器 v" + VERSION + "</span></div></header>"
        '<div id="p203-toolbar">'
        '<span class="muted">本页为聚焦视图；</span>'
        '<a class="ug-btn" href="unified.html">打开统一画布（含包含/数据流/调用 图层开关）</a>'
        '</div>'
        "<main id=\"main-content\" class=\"content\">__BODY__</main></body></html>")

    def _p203_page(title, brand, body):
        return (_p203_shell
                .replace("__TITLE__", title)
                .replace("__BRAND__", brand)
                .replace("__BODY__", body))

    (outdir / "folder_impact.html").write_text(
        _p203_page("文件夹影响面", "文件夹影响面（P203）",
                   _render_folder_impact_html(cg_json, files, calls_of, callers_of)),
        encoding="utf-8")
    (outdir / "var_taint.html").write_text(
        _p203_page("变量污点溯源", "变量污点溯源（P203）",
                   _render_var_taint_html(cg_json, model)),
        encoding="utf-8")
    file_pages = {}
    for mf in files:
        # P224-Z：单文件源码页渲染隔离——任一文件渲染失败只丢该页，不影响整站。
        try:
            page = render_source_page(mf, index, files, fn_to_file, callers_of, calls_of, root, rel, model,
                                      max_nodes=max_nodes, cg_json=cg_json, gid_of=_gid_of,
                                      offline=offline)
            p = src_dir / _page_rel(mf.rel)
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(page, encoding="utf-8")
            file_pages[mf.rel] = p
        except Exception as _e:
            _RENDER_ERRORS.append(("src/" + _page_rel(mf.rel), repr(_e)))
            print("[WARN] 源码页 %s 渲染失败（跳过该文件）：%s" % (mf.rel, _e))

    # P270：命令面板（Ctrl+K）全站跳转索引。
    # 刻意**独立成文件**而非追加进 _cgdata.js：_cgdata.js 被多处按
    # 「window.__CG__={json};」单赋值格式解析，追加内容会破坏既有解析。
    try:
        import json as _json
        _gsi = _build_gs_index(files, None)
        (src_dir / "_index.js").write_text(
            "window.__GS_INDEX__=%s;" % _json.dumps(_gsi, ensure_ascii=False),
            encoding="utf-8")
    except (ValueError, OSError, TypeError, AttributeError):
        pass        # 索引是增强能力，失败不影响站点生成

    # 2) 索引页
    # P75：把空目录 Path 列表转为相对路径列表，供目录树与目录页展示
    empty_rels = []
    for ed in (model.empty_dirs or []):
        try:
            ed_rel = os.path.relpath(str(ed), str(root)).replace(os.sep, "/")
        except ValueError:
            ed_rel = str(ed)
        empty_rels.append(ed_rel or "(root)")
    index_html = render_browse_index(files, index, callers_of, stats, root, rel,
                                     calls_of, fn_to_file, reproducible=reproducible,
                                     empty_dirs=empty_rels, ai=ai)
    (outdir / "index.html").write_text(index_html, encoding="utf-8")

    # P221-D：AI 分析（静态↔动态边界）入口页——离线即可用，随时可接入
    if ai and checks_for_sarif is not None:
        try:
            _ai_title, _ai_body = _build_ai_prompts(
                files, model, stats, checks_for_sarif, None)
            (outdir / "ai_prompts.html").write_text(
                render_ai_prompts_page(_ai_title, _ai_body), encoding="utf-8")
        except Exception as _e:
            print("[WARN] AI 分析页生成失败（不影响其余站点）：%s" % _e)

    # 3) MATLAB 内置库函数说明（独立页面，P18）
    used_builtins = collect_used_builtins(files)
    _safe_page(outdir, "matlab_lib.html",
               lambda: render_matlab_lib_page(used_builtins))

    # 3.5) 内置函数维度视图（R2）——集中展示每个函数实际调用的内置及其输入/输出维度
    _safe_page(outdir, "dims.html",
               lambda: render_dims_view_page(model, _gid_of))

    # 3.5b) 变量字段流动视图（P225-A）——逐函数展示每个变量的 def-use 链与维度
    _safe_page(outdir, "varflow.html",
               lambda: render_varflow_page(model, _gid_of))

    # 3.5c) 模块调度统计视图（P225-B）——被调用热度/入口/函数→函数调用统计
    _safe_page(outdir, "schedule.html",
               lambda: render_schedule_page(model))

    # 3.6) 结构体成员变量查看（新功能）——struct_obj.f 与 struct('a',...) 成员清单
    _safe_page(outdir, "struct_members.html",
               lambda: render_struct_members_page(model))

    # 3.7) 内置函数维度联动检测（新功能）——真实维度引擎推导实测输入/输出并与文档交叉校验
    _safe_page(outdir, "dims_check.html",
               lambda: render_builtin_dims_check_page(model, _gid_of))

    # 3.8) 算子工程影响分析（R62）——复用 _compute_operator_impact 在浏览站点呈现
    _op_checks = _collect_checks(files, None)
    _op_td = getattr(model, "taint", None)
    _op_sinks, _op_srcs = [], []
    if _op_td:
        for _flow in (_op_td.get("flows") or []):
            _sk = _flow.get("sink")
            if isinstance(_sk, dict):
                _op_sinks.append({"file": _sk.get("file", ""),
                                  "func": _sk.get("func", ""), "line": _sk.get("line", 0)})
            for _sc in (_flow.get("sources") or []):
                if isinstance(_sc, dict):
                    _op_srcs.append({"file": _sc.get("file", ""),
                                     "func": _sc.get("func", ""), "line": _sc.get("line", 0)})
    _op_checks["tainted_sink"] = _op_sinks
    _op_checks["tainted_src"] = _op_srcs
    _op_oi = _compute_operator_impact(_op_checks, enabled_checks=None)
    (outdir / "operator_impact.html").write_text(
        render_operator_impact_page(_op_oi), encoding="utf-8")

    # 3.9) 定标 / 数值缩放分析（P224）——扫描缩放/归一化/单位换算/dB/eps 等定标模式
    _calib = _collect_scaling_patterns(files)
    (outdir / "calibration.html").write_text(
        render_scaling_page(_calib), encoding="utf-8")

    # 3.9.5) 分析总览 / 健康度仪表盘（P224 收口）——把维度/定标/算子/结构体四类发现汇成单页
    _safe_page(outdir, "overview.html",
               lambda: render_overview_page(model, _op_oi, _calib))

    # 4) 关键函数风险度量（独立页面，P23）
    metrics = _compute_function_metrics(files, callers_of, calls_of)
    _safe_page(outdir, "metrics.html",
               lambda: render_metrics_page(metrics))

    # 5) 疑似漏检调用诊断（独立页面，P25 + P43 溯源完整性/动态调用）
    unresolved = _collect_unresolved_calls(files)
    orphaned = _collect_orphaned(files, callers_of)
    dynamic = _collect_dynamic_calls(files)
    indirect = _collect_indirect_calls(files)
    index_like = _collect_index_like_calls(files)
    (outdir / "unresolved.html").write_text(
        render_unresolved_page(unresolved, orphaned=orphaned, dynamic=dynamic,
                              indirect=indirect, index_like=index_like),
        encoding="utf-8")

    # 5.5) 类层次（Class Hierarchy，P81）——doxygen 风格类继承图（父上子下）+ 类明细表
    # （无类时页面显示「未发现 classdef」，保证导航链接始终有效）
    _safe_page(outdir, "class_hierarchy.html",
               lambda: render_class_hierarchy_page(files))

    # 5.6) 注释标签聚合（A1）——doxygen 风格 \todo/\bug/\deprecated 列表页
    # （无标签时页面显示「未发现注释标签」，保证导航链接始终有效）
    _safe_page(outdir, "annotations.html",
               lambda: render_annotations_page(_collect_annotations(files)))

    # 5.8) 静态检查汇总（C3）——未初始化/类型不一致/死代码告警聚合页
    # （无告警时页面显示「代码健康」，保证导航链接始终有效）
    (outdir / "checks.html").write_text(
        render_checks_page(_collect_checks(files, enabled)), encoding="utf-8")

    # 5.9) 复杂度热力总览（C3）——文件/目录复杂度热力图 + 耦合热点
    _safe_page(outdir, "complexity.html",
               lambda: render_complexity_heatmap(files))

    # 5.9b) 代码审查工作台（P271 R6-2）——依据官方审查标准的合规总览
    # （合规得分 + 按严重度分组的发现 + 按文件下钻）
    try:
        _rv_findings, _rv_per_file, _rv_summary = _review_project(
            files, calls_of, callers_of)
        # P-rev R8/R14：构建「函数 → 被调用数」与「函数 → 传递受影响数（传递闭包）」映射。
        # R14：沿 callers_of 做 BFS，得到「改了 X 会影响到的全部下游（传递依赖）」规模。
        _fan_in, _fan_trans = {}, {}
        for _mf in files:
            for _f in _mf.functions:
                _k = "%s::%s" % (_mf.rel, _f.name)
                _fan_in[_k] = len(callers_of.get(id(_f), []))
        # 构建 id(f) -> [caller ids]，BFS 求传递被依赖集合大小
        _caller_map = {id(_f): [id(c) for c in callers_of.get(id(_f), [])] for _mf in files for _f in _mf.functions}
        for _mf in files:
            for _f in _mf.functions:
                _seen, _q = set(), list(_caller_map.get(id(_f), []))
                for _c in _q:
                    if _c not in _seen:
                        _seen.add(_c); _q.extend(_caller_map.get(_c, []))
                _fan_trans["%s::%s" % (_mf.rel, _f.name)] = len(_seen)
        (outdir / "compliance.html").write_text(
            render_compliance_page(files, _rv_findings, _rv_per_file, _rv_summary, _fan_in, _fan_trans),
            encoding="utf-8")
    except Exception:
        # 审查引擎异常不得影响主流程（站点生成优先）
        pass

    # 5.10) 目录耦合度矩阵（P82）——目录 × 目录耦合强度热力图 + 循环依赖高亮
    _safe_page(outdir, "dir_matrix.html",
               lambda: render_dir_coupling_matrix(files, calls_of))

    # 5.11) 污点流分析（P85）——敏感输入 → 危险输出点的传播路径安全门禁
    taint_data = getattr(model, "taint", None)
    if taint_data is not None:
        (outdir / "taint.html").write_text(
            render_taint_page(taint_data, root), encoding="utf-8")

    # 5.12) 函数待办清单（P86）——注释完备度评估（复杂度 × 扇入 × 缺注释）
    todo_data = getattr(model, "doc_todos", None)
    if todo_data is not None:
        _safe_page(outdir, "todo.html",
                   lambda: render_todo_page(todo_data, root))

    # 5.13) C 语言前端分析报告（P87）——多语言后端扩展（--lang c / --mixed）
    c_model = getattr(model, "c_model", None)
    if c_model is None:
        c_model = {"lang": "c", "files": [], "func_index": {}, "edges": [],
                   "unresolved": []}
    _safe_page(outdir, "c_report.html",
               lambda: render_c_report(c_model, getattr(model, "c_bridge", None) or [], root))

    # 5.7) 全局成员索引（B1）——doxygen 风格 Member Index（属性/事件/枚举/方法）
    # （无类时页面显示「未发现 classdef」，保证导航链接始终有效）
    (outdir / "members.html").write_text(
        render_members_page(files), encoding="utf-8")

    # 6) 静态调用图导出（独立 SVG，P30）——可直接打开 / 嵌入文档评审
    static_svg = render_static_callgraph_svg(files, calls_of, callers_of)
    (outdir / "callgraph.svg").write_text(static_svg, encoding="utf-8")

    # 7) 目录-函数分层调用图（独立 SVG，P62）——doxygen 风格：目录为簇、函数为节点
    combined_svg = render_folder_function_graph_svg(files, calls_of)
    if combined_svg:
        _safe_page(outdir, "combined_graph.svg", lambda: combined_svg)

    # 8) 目录索引页（doxygen 风格，P65）——每个目录一个页面：文件/函数 + 依赖目录
    dirs_out = outdir / "dirs"
    dirs_out.mkdir(parents=True, exist_ok=True)
    all_dir_labels = {os.path.dirname(mf.rel) or "(root)" for mf in files}
    # 根目录始终生成目录页（即使无直接 .m 文件，只有子目录，P75）
    all_dir_labels.add("(root)")
    # P74：空目录（不含 .m 文件）也生成目录页，使全部文件夹纳入分析
    for ed in (model.empty_dirs or []):
        try:
            ed_rel = os.path.relpath(str(ed), str(root)).replace(os.sep, "/")
        except ValueError:
            ed_rel = str(ed)
        all_dir_labels.add(ed_rel or "(root)")
    for dl in sorted(all_dir_labels):
        (dirs_out / _dir_page_name(dl)).write_text(
            render_directory_page(dl, files, calls_of, empty_dirs=empty_rels),
            encoding="utf-8")

    # P-rev R79：站点可审计清单——每页 sha256 落盘 manifest.json，供 fe_audit S15
    # 做「产物-清单一致性」对账（抓手工改动 / 半次生成的旧页 / 陈旧残留）。
    # P-rev R85：先写确定性质量快照 site-quality.json（规模事实，无时间戳），
    # 再让 manifest 一并收录其 sha；fe_audit S16 据此做语义复核（防成对改写）。
    # 统一补全横切元信息（description/OG/viewport/表头 scope）——必须早于 manifest，
    # 否则 sha 与改动后的页面不符会让 S15 误报。
    _finalize_site_html(outdir)
    # FE-21：将各页专用样式表（page_css/*.css）复制到站点根目录及每个含 .html 的子目录，
    # 使外链化后的 <link href="dims.css"> 等可解析。此前该函数从未被调用，
    # 导致全部 page_css 链接悬空（FE-21 外链化形同虚设）。
    write_page_css_tree(outdir)
    write_report_css(str(outdir))
    # FE-21+：将 browse.css 复制到站点根目录及每个含 .html 的子目录（与 page_css 同机制）。
    # 此前从未被调用，导致各浏览页 <link href="browse.css"> 悬空。必须在 _write_site_quality
    # 之前调用，使质量快照的资产计数包含这些新增样式表。
    write_browse_css_tree(outdir)
    _write_site_quality(outdir)
    _write_site_manifest(outdir, reproducible=reproducible)
    # P-rev R88：站点刚写完即自检，结构/重复 id 问题第一时间在 stderr 亮相。
    _selfcheck_html_tree(str(outdir))
    # P224-Z：渲染降级汇总——单页异常已被隔离，这里集中可观测，避免「整站静默废掉」。
    if _RENDER_ERRORS:
        print("[WARN] 共 %d 个页面渲染降级（已写占位页，详见站点首页「渲染异常」清单）：%s"
              % (len(_RENDER_ERRORS),
                 ", ".join("%s:%s" % (_n, _e) for _n, _e in _RENDER_ERRORS[:10])))
    # P225-F：AI CLI 引入时机——ask/auto 在站点生成后触发（off/prompts 不调用）
    if ai_mode in ("ask", "auto"):
        maybe_run_ai_cli(outdir, files, model, stats, checks_for_sarif, ai_mode)
    return outdir / "index.html"


def _write_site_quality(outdir):
    """P-rev R85：写确定性站点质量快照 site-quality.json。

    - 只记录**可从产物本身重新推导**的规模事实（html/source 页数、资产数、总字节），
      不含时间戳，--reproducible 与非 reproducible 模式下均逐字节稳定；
    - 资产计数与 manifest 的 pages 一致口径（html 之外的可分发文件），
      供 fe_audit S16 逐字段复核，抓「快照与清单被成对改写」或陈旧快照。
    """
    html_pages = 0
    src_pages = 0
    assets = 0
    total_bytes = 0
    for _root, _dirs, fnames in os.walk(str(outdir)):
        for fn in fnames:
            if fn in ("manifest.json", "site-quality.json"):
                continue
            if fn.startswith("_fe_"):
                # P-rev R92：fe_audit 运行时产物（_fe_dom_check.json 等）不属交付物
                continue
            fp = os.path.join(_root, fn)
            try:
                total_bytes += os.path.getsize(fp)
            except OSError:
                continue
            if fn.endswith((".html", ".htm")):
                html_pages += 1
            if fn.endswith(".m.html"):
                src_pages += 1
            if fn.endswith((".js", ".json", ".css", ".svg")):
                assets += 1
    snap = {
        "schema": 1,
        "tool": "matlabc",
        "version": VERSION,
        "mode": "browse",
        "pages": {"html": html_pages, "source": src_pages},
        "assets": assets,
        "total_bytes": total_bytes,
    }
    with io.open(os.path.join(str(outdir), "site-quality.json"), "w",
                 encoding="utf-8") as fh:
        json.dump(snap, fh, ensure_ascii=False, sort_keys=True, indent=1)


def _write_site_manifest(outdir, reproducible=False):
    """P-rev R79：为已生成的 browse 站点写 manifest.json（页面清单 + sha256）。

    - 相对路径统一用 '/' 分隔，独立于平台；
    - summary.bytes 由内容推导，可复现模式下也稳定（不含生成时间）；
    - reproducible=True 时不记录 generated_at，保证两次生成逐字节一致。
    """
    outdir = str(outdir)
    files_map = {}
    total_bytes = 0
    for _root, _dirs, fnames in os.walk(outdir):
        for fn in fnames:
            if fn == "manifest.json":
                continue
            if fn.startswith("_fe_"):
                # P-rev R92：fe_audit 运行时产物不入清单，双向目录共用不再互相污染
                continue
            fp = os.path.join(_root, fn)
            try:
                with io.open(fp, "rb") as fh:
                    data = fh.read()
            except OSError:
                continue
            total_bytes += len(data)
            rel = os.path.relpath(fp, outdir).replace(os.sep, "/")
            files_map[rel] = hashlib.sha256(data).hexdigest()
    manifest = {
        "v": 1,
        "tool": "matlabc",
        "version": VERSION,
        "mode": "browse",
        "reproducible": bool(reproducible),
        "pages": files_map,
        "summary": {"count": len(files_map), "bytes": total_bytes},
    }
    if not reproducible:
        manifest["generated_at"] = time.strftime("%Y-%m-%dT%H:%M:%S")
    with io.open(os.path.join(outdir, "manifest.json"), "w",
                 encoding="utf-8") as fh:
        json.dump(manifest, fh, ensure_ascii=False, sort_keys=True, indent=1)


# ---------------------------------------------------------------------------
# 源码级变量 / 参数流向高亮（轻量作用域估计，无需完整类型推导）
# ---------------------------------------------------------------------------
_RE_FOR = re.compile(r"^\s*(?:par)?for\b\s+([A-Za-z_]\w*)")


def _find_assignment_pos(raw):
    """在单行中找到顶层（不在括号/字符串/注释内）的赋值运算符 '=' 位置。

    排除比较/不等/关系运算符（==、~=、<=、>=、=~）。返回位置，未找到返回 -1。
    """
    n = len(raw)
    depth = 0
    in_str = None
    i = 0
    while i < n:
        ch = raw[i]
        if in_str:
            if ch == in_str:
                if i + 1 < n and raw[i + 1] == in_str:
                    i += 2
                    continue
                in_str = None
            i += 1
            continue
        if ch == "'" or ch == '"':
            in_str = ch
            i += 1
            continue
        if ch == "%":
            break  # 行注释之后忽略
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth -= 1
        elif ch == "=" and depth == 0:
            prev = raw[i - 1] if i > 0 else ""
            nxt = raw[i + 1] if i + 1 < n else ""
            if prev in "=~<>" or nxt == "=":
                i += 1
                continue
            return i
        i += 1
    return -1


def _stmt_rhs(raw, eq_pos):
    """从赋值语句中截取「干净的 RHS 表达式」：去掉尾随注释、语句分隔符 ';'、
    以及语句分隔符之后的内容（顶层，非字符串/括号/注释内）。

    用于结构体成员维度推导：避免把 'zeros(3,4); % 注释' 或 struct 实参尾部
    多捕获的 ')' 喂给 _es_eval 导致解析失败（P223-B 修复根因）。
    """
    if eq_pos < 0 or eq_pos + 1 >= len(raw):
        return ""
    s = raw[eq_pos + 1:]
    depth = 0
    in_str = None
    i = 0
    L = len(s)
    cut = -1
    while i < L:
        ch = s[i]
        if in_str:
            if ch == in_str and (i + 1 >= L or s[i + 1] != in_str):
                in_str = None
            i += 1
            continue
        if ch == "'" or ch == '"':
            in_str = ch
            i += 1
            continue
        if ch == "%":
            cut = i
            break
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth -= 1
        elif ch == ";" and depth == 0:
            cut = i
            break
        i += 1
    if cut >= 0:
        s = s[:cut]
    return s.strip().rstrip(";").strip()


def _clean_rhs_for_eval(rhs):
    """清洗结构体成员 RHS 供 _es_eval 解析：去掉尾随注释、语句分隔符 ';'、
    以及因 struct('a',v) 实参解析多捕获的「不平衡尾随闭括号」(如 rand(5)) )。

    尾随闭括号仅在整体「) 多于 (」时才裁掉，避免误伤正常函数调用 ones(2,3)。
    """
    if not rhs:
        return ""
    # 去尾随注释
    in_str = None
    i = 0
    L = len(rhs)
    cut = -1
    while i < L:
        ch = rhs[i]
        if in_str:
            if ch == in_str and (i + 1 >= L or rhs[i + 1] != in_str):
                in_str = None
            i += 1
            continue
        if ch in "'\"":
            in_str = ch
            i += 1
            continue
        if ch == "%":
            cut = i
            break
        i += 1
    if cut >= 0:
        rhs = rhs[:cut]
    rhs = rhs.strip().rstrip(";").strip()
    # 去掉不平衡的尾随闭括号
    for _cl in (")", "]"):
        while rhs.endswith(_cl):
            if rhs.count("(" if _cl == ")" else "[") < rhs.count(_cl):
                rhs = rhs[:-1].rstrip()
            else:
                break
    return rhs


def _lhs_assigned_vars(lhs):
    """返回赋值语句 LHS 中每个顶层逗号元素首个标识符（被赋值变量名）。

    例如 'a' -> {a}；'[a, b]' -> {a,b}；'a(b)' -> {a}；'a.b' -> {a}；'a(b).c' -> {a}。
    """
    vars_ = []
    depth = 0
    cur = ""
    for ch in lhs:
        if ch in "([{":
            depth += 1
            cur += ch
        elif ch in ")]}":
            depth -= 1
            cur += ch
        elif ch == "," and depth == 0:
            vars_.append(cur)
            cur = ""
        else:
            cur += ch
    if cur.strip():
        vars_.append(cur)
    out = []
    for el in vars_:
        m = _RE_IDENT_HL.match(el.strip())
        if m:
            out.append(m.group(0))
    return set(out)


def _analyze_varflow(mf):
    """分析文件中每个函数的参数（input/output）在函数体内的读写使用。

    返回 (func_of_line, line_var_map, summary)：
      func_of_line: {line: MatlabFunction}            行 -> 所属函数
      line_var_map : {line: {(s,e): (param, kind)}}   行 -> 该行的参数出现标注
      summary      : {fn_anchor: {param: {d,r,w}}}     汇总各参数的声明/读/写次数
    kind ∈ {'d'(声明), 'r'(读取), 'w'(写入)}。
    """
    funcs = [f for f in mf.functions if f.kind != "script"]
    if not funcs:
        return {}, {}, {}
    func_of_line = {}
    for f in funcs:
        a = f.line
        b = (f.body_end or mf.lines)
        for ln in range(a, b + 1):
            func_of_line[ln] = f
    line_var_map = defaultdict(dict)
    summary = defaultdict(lambda: defaultdict(lambda: {"d": 0, "r": 0, "w": 0}))
    in_block = False
    for ln in range(1, mf.lines + 1):
        raw = mf.source_lines[ln - 1]
        runs, in_block = _tokenize_matlab(raw, in_block)
        if runs and all(k == "comment" for (_, _, k) in runs):
            continue  # 整行注释（含 %{ %} 块注释行）跳过
        idents = [(s, e, raw[s:e]) for (s, e, k) in runs if k == "ident"]
        if not idents:
            continue
        f = func_of_line.get(ln)
        if f is None:
            continue
        params = f.inputs + f.outputs
        if not params:
            continue
        param_set = set(params)
        in_sig = (ln == f.line)
        assign_pos = -1
        assigned = set()
        if not in_sig:
            assign_pos = _find_assignment_pos(raw)
            if assign_pos >= 0:
                assigned = _lhs_assigned_vars(raw[:assign_pos])
            m = _RE_FOR.match(raw)
            if m:
                assigned.add(m.group(1))  # for/parfor 循环变量视为写入
        for (s, e, name) in idents:
            if name not in param_set:
                continue
            if in_sig:
                kind = "d"
            elif assign_pos < 0:
                kind = "r"
            elif s < assign_pos:
                kind = "w" if name in assigned else "r"
            else:
                kind = "r"
            line_var_map[ln][(s, e)] = (name, kind)
            summary[_anchor_id(f)][name][kind] += 1
    return func_of_line, dict(line_var_map), {k: dict(v) for k, v in summary.items()}


def _collect_field_defs(mf):
    """收集文件中每个结构体字段的「定义位」——即 (结构体基名, 字段名) 首次写入处。

    P36 / P223-B：MATLAB 结构体字段没有独立声明语句，其「定义」等价于**首次赋值写入**
    （位于顶层赋值号左侧）。本函数按源码顺序扫描，返回 {line_no: {(base, field), ...}}。

    P223-B 扩展：容忍「索引式成员写入」——
      BASE(idx).field = ...    如 S(1).k = 9
      BASE.field(idx) = ...    如 S.h(2) = 7
      BASE.a.b = ...           多层嵌套（仅记叶成员，中间段由调用方去重）
    匹配要求字段表达式覆盖整个赋值左值（避免把 `foo = bar.baz` 误判为在 foo 上定义字段）。
    """
    in_block = False
    seen = set()
    by_line = defaultdict(set)
    # 左值字段写入：base(可选idx).field(可选idx)(可多层)，且须覆盖整个等号左值。
    _lhs_field_re = re.compile(
        r"([A-Za-z_]\w*)"                       # base
        r"(?:\([^()]*\))?"                       # 可选 (idx)
        + r"(?:\.([A-Za-z_]\w*)"                 # .field
        + r"(?:\([^()]*\))?)+"                   # 可选 (idx)，至少一段
    )
    for ln in range(1, mf.lines + 1):
        raw = mf.source_lines[ln - 1]
        runs, in_block = _tokenize_matlab(raw, in_block)
        if runs and all(k == "comment" for (_, _, k) in runs):
            continue
        assign_pos = _find_assignment_pos(raw)
        if assign_pos < 0:
            continue
        lhs = raw[:assign_pos]
        # 去除字符串字面量，避免误匹配
        lhs_clean = re.sub(r"'[^']*'|\"[^\"]*\"", " ", lhs)
        m = _lhs_field_re.search(lhs_clean)
        if not m:
            continue
        # 字段表达式须覆盖整个左值（去掉首尾空白后相等），否则非定义位
        if m.group(0).strip() != lhs_clean.strip():
            continue
        base = m.group(1)
        field = m.group(2)
        if not field:
            continue
        key = (base, field)
        if key not in seen:
            seen.add(key)
            by_line[ln].add(key)
    return dict(by_line)


def _detect_uninitialized(mf):
    """C3：检测函数内「疑似未初始化变量」（读前无写 + 条件分支赋值后使用）。

    对每个非脚本函数，按源码顺序追踪局部变量的首次出现：若某标识符在函数体内
    首次出现即被「读取」（RHS 或 LHS 索引内），且非参数 / 关键字 / 内置函数 /
    调用目标 / 结构体字段，则判定为疑似未初始化（可能来自外层作用域或漏写赋值）。

    数据流精确化：if 块（无 else/elseif）内的赋值视为「条件赋值」（不保证执行），
    块外首次使用该变量时报告「可能未初始化」；if/else 各写一遍则视为确定初始化。

    返回 [{name, line, func, reason}]，按 (func, line, name) 稳定排序。"""
    # C3：增量复用——结果已缓存在 mf 上（随 pickle 缓存复用），直接返回
    cached = getattr(mf, "_uninitialized", None)
    if cached is not None:
        return cached
    out = []
    reported = set()
    in_block = False
    # C3：告警抑制注释（% analyzer:ignore uninitialized [name] / ignore-next-line）
    _supp_all = _parse_suppressions(mf)
    supp = _supp_all.get("uninitialized", {"names": set(), "all": False})
    next_line = _supp_all.get("_next_line", {})
    block_lines = _supp_all.get("_block_lines", {})
    for f in mf.functions:
        if f.kind == "script":
            continue
        # D-R8-A：嵌套函数。
        #   MATLAB **不要求**嵌套函数缩进（父函数 `end` 之前的同缩进 function
        #   同样是嵌套函数，实测夹具 f.m 即为此形态），所以判据只能是
        #   「落在本函数 body 区间内的 `function` 行」—— 本函数自身的声明行
        #   在 body_start 之前，故不会被误判。
        fn_stack = []            # 嵌套函数声明的缩进栈（其 body 不属本函数变量流）
        params = set(f.inputs) | set(f.outputs)
        # C3：降误报——global/persistent 注入的变量视为「已初始化」（来自外部/跨调用持久化）
        injected = set(n for n, _ in f.globals) | set(n for n, _ in f.persistents)
        seen_written = set()      # 确定已赋值
        maybe_written = set()     # 条件块内赋值（可能未初始化）
        a = f.body_start
        b = f.body_end or mf.lines
        cond_stack = []           # C3：增量维护条件块栈 [(indent, has_else)]，避免 O(n²)
        for ln in range(a, b + 1):
            if ln > len(mf.source_lines):
                break
            raw = mf.source_lines[ln - 1]
            indent = len(raw) - len(raw.lstrip())
            stripped = raw.strip()
            runs, in_block = _tokenize_matlab(raw, in_block)
            if runs and all(k == "comment" for (_, _, k) in runs):
                continue
            # D-R8-A：嵌套函数 —— 其声明行与**整个 body** 都不属于当前函数的
            # 变量流。旧实现把落在父函数 body 范围内的 `function z = inner(v)`
            # 当普通语句处理，于是 inner 的输入 v / 输出 z 被判成父函数里
            # 「读前无写」的局部量（实测 nested.m:4 两条 high 误报；而 high
            # 会被确定性补丁引擎直接拿去自动改源码）。
            if re.match(r"^function\b", stripped, re.IGNORECASE):
                fn_stack.append(indent)
                continue
            if fn_stack:
                if (re.match(r"^end\b", stripped, re.IGNORECASE)
                        and indent <= fn_stack[-1]):
                    fn_stack.pop()
                continue                       # 嵌套函数体整体跳过
            # 块关键字行：不参与变量读写判断。
            #   刻意**不**把 while/switch 放进来：它们的头部是真实读取
            #   （`while x < n`），跳过会漏掉真阳性。`try` 行无标识符，纳入无变化。
            kwm = re.match(r"^(if|elseif|else|end|try|catch)\b", stripped,
                           re.IGNORECASE)
            if kwm:
                kw = kwm.group(1).lower()
                if kw == "end":
                    while cond_stack and cond_stack[-1][0] >= indent:
                        cond_stack.pop()
                elif kw == "if":
                    cond_stack.append((indent, False))
                elif kw in ("elseif", "else"):
                    if cond_stack:
                        cond_stack[-1] = (cond_stack[-1][0], True)
                elif kw == "catch":
                    # catch 绑定的异常变量由捕获**确定赋值**
                    cm = re.match(r"^catch\s+([A-Za-z_]\w*)", stripped,
                                  re.IGNORECASE)
                    if cm:
                        seen_written.add(cm.group(1))
                continue
            # 是否处于「无 else 的 if 块」内（条件赋值不保证执行）
            in_cond = bool(cond_stack) and not cond_stack[-1][1]
            # D-R8-B：for / parfor 循环头 —— 循环变量由循环**确定赋值**。
            # 旧实现落到通用赋值解析，而 `_lhs_assigned_vars("for k ")` 取到的
            # 首个标识符是关键字 `for` 本身 ⇒ k 不在 lhs_vars ⇒ 被当作读取
            # （实测 varargs.m:4 一条 high 误报 → 补丁把 `for k = 1:n` 整行覆盖）。
            _lm = re.match(r"^(?:for|parfor)\s+(.+?)\s*=(?!=)", stripped,
                           re.IGNORECASE)
            if _lm:
                _lhs = _lm.group(1).strip()
                if _lhs.startswith("[") and _lhs.endswith("]"):
                    _lhs = _lhs[1:-1]          # for [i, j] = ... 的多变量形式
                for _lv in _lhs_assigned_vars(_lhs):
                    (maybe_written if in_cond else seen_written).add(_lv)
                continue                       # 循环头不参与读写判断
            idents = [(idx, s, e, raw[s:e]) for idx, (s, e, k) in enumerate(runs)
                      if k == "ident"]
            if not idents:
                continue
            assign_pos = _find_assignment_pos(raw)
            lhs_vars = _lhs_assigned_vars(raw[:assign_pos]) if assign_pos >= 0 else set()
            for idx, s, e, name in idents:
                if name in params or name in injected or name in reported:
                    continue
                is_call = (idx + 1 < len(runs) and runs[idx + 1][2] == "op"
                           and raw[runs[idx + 1][0]:runs[idx + 1][1]] == "(")
                is_field = (idx >= 1 and runs[idx - 1][2] == "op"
                            and raw[runs[idx - 1][0]:runs[idx - 1][1]] == ".")
                is_handle = (idx >= 1 and runs[idx - 1][2] == "op"
                             and raw[runs[idx - 1][0]:runs[idx - 1][1]] == "@")
                if is_call or is_field or is_handle:
                    continue
                if assign_pos >= 0 and s < assign_pos and name in lhs_vars:
                    # 赋值：条件块内 → maybe；否则 → 确定
                    if in_cond:
                        maybe_written.add(name)
                    else:
                        seen_written.add(name)
                else:
                    # 读取：确定已写 → 跳过；仅条件块内写 → 可能未初始化；完全没写 → 未初始化
                    if name in seen_written:
                        continue
                    # C3：告警抑制（变量名/函数名 ignore + 行级 ignore-next-line）
                    if (supp["all"] or name in supp["names"] or f.name in supp["names"]
                            or (ln in next_line and "uninitialized" in next_line[ln])
                            or (ln in block_lines and "uninitialized" in block_lines[ln])):
                        reported.add(name)
                        continue
                    if name in maybe_written:
                        out.append({"name": name, "line": ln, "func": f.name,
                                    "reason": "可能未初始化（仅条件分支赋值）",
                                    "confidence": "medium"})   # P147：条件赋值误报概率较高
                        reported.add(name)
                    else:
                        out.append({"name": name, "line": ln, "func": f.name,
                                    "reason": "未初始化（读前无写）",
                                    "confidence": "high"})      # P147：无写直接读，真问题概率高
                        reported.add(name)
    out.sort(key=lambda r: (r["func"], r["line"], r["name"]))
    mf._uninitialized = out
    return out


def _render_param_flow_pills(f, var_summary):
    """渲染函数卡片中的「参数流向」可点击药丸（点击高亮源码读写位置）。"""
    params = list(f.inputs) + list(f.outputs)
    if not params:
        return ""
    anchor = _anchor_id(f)
    sm = var_summary.get(anchor, {})
    parts = []
    for p in params:
        c = sm.get(p, {"d": 0, "r": 0, "w": 0})
        if c["r"] and c["w"]:
            kind, label, cls = "both", "既读又写", "k-both"
        elif c["r"]:
            kind, label, cls = "read", "仅读", "k-read"
        elif c["w"]:
            kind, label, cls = "write", "写入", "k-write"
        elif c["d"]:
            kind, label, cls = "decl", "仅声明", "k-decl"
        else:
            kind, label, cls = "unused", "未使用", "k-unused"
        parts.append(
            '<span class="param-pill %s" data-fn="%s" data-param="%s" data-kind="%s" '
            'title="点击高亮本函数在源码中的读写位置">%s'
            '<span class="pill-k">%s</span></span>'
            % (cls, anchor, html_mod.escape(p), kind,
               html_mod.escape(p), label))
    return '<div class="param-flow"><b>参数流向：</b>' + "".join(parts) + "</div>"


def _fn_desc(fn):
    """返回函数结构化头部注释里的「函数说明」（description），供调用列表 / 图注释展示。"""
    hdr = getattr(fn, "header", None)
    if isinstance(hdr, dict):
        return hdr.get("description", "") or ""
    return ""


def friendly_func_summary(func, calls_of=None, callers_of=None):
    """为缺少头注释说明的函数合成友好、细致的中文摘要（签名 + 位置 + 调用关系 + 复杂度）。

    当函数没有 DESCRIPTION 头注释时，用静态分析结果给出一段人能读懂的说明，
    保证每个函数页都有可读解释（呼应「内部函数更友好 / 更细致」需求）。"""
    name = getattr(func, "name", "?")
    ins = ", ".join(getattr(func, "inputs", []) or []) or "无"
    outs = ", ".join(getattr(func, "outputs", []) or []) or "无"
    mf = getattr(func, "mfile", None)
    rel = getattr(mf, "rel", "?") if mf else "?"
    line = getattr(func, "line", 0)
    n_out = len((calls_of or {}).get(id(func), []))
    n_in = len((callers_of or {}).get(id(func), []))
    cx = getattr(func, "complexity", None)
    parts = [
        "函数 `%s(%s)` → [%s]" % (name, ins, outs),
        "定义于 %s 第 %d 行" % (rel, line),
    ]
    if n_out or n_in:
        parts.append("调用 %d 个函数、被 %d 处引用" % (n_out, n_in))
    if cx is not None:
        parts.append("圈复杂度 %d" % cx)
    return "；".join(parts)


# P40：预览源码片段的语法高亮 token 类型 → CSS class 映射（深色代码块用浅色）
_SNIP_HILITE_CLASS = {
    "comment": "cg-snip-comment",
    "string": "cg-snip-string",
    "keyword": "cg-snip-keyword",
    "builtin": "cg-snip-builtin",
    "number": "cg-snip-number",
    "op": "cg-snip-op",
}


def _fn_src_snip(fn, pre_lines=6, post_lines=6):
    """P39/P40：返回函数「头部注释（向上 N 行）+ 定义行 + 函数体（向下 M 行）」的带行号、
    **语法高亮**的 HTML 源码片段，供预览面板展示（与源码页同配色）。合成对象无 mfile 时返回空串。"""
    mf = getattr(fn, "mfile", None)
    if mf is None:
        return ""
    src = getattr(mf, "source_lines", None)
    if not src:
        return ""
    def_idx = max(0, fn.line - 1)
    # 向上收集紧邻的注释 / 空行（函数头部注释块），最多 pre_lines 个注释行
    start = def_idx
    collected = 0
    while start - 1 >= 0 and collected < pre_lines:
        prev = src[start - 1].rstrip()
        if prev.strip() == "" or prev.strip().startswith("%"):
            start -= 1
            if prev.strip().startswith("%"):
                collected += 1
        else:
            break
    end = min(def_idx + post_lines, len(src))
    out = []
    in_block = False
    for ln in range(start, end):
        line = src[ln].rstrip()
        runs, in_block = _tokenize_matlab(line, in_block)
        segs = []
        for s, e, kind in runs:
            esc = html_mod.escape(line[s:e])
            cls = _SNIP_HILITE_CLASS.get(kind, "")
            if cls:
                segs.append('<span class="%s">%s</span>' % (cls, esc))
            else:
                segs.append(esc)
        # P41：每行包裹为可点击的 .cg-snip-line（data-ln 记录真实行号），点击可定位源码
        out.append('<div class="cg-snip-line" data-ln="%d"><span class="cg-snip-ln">%4d</span> %s</div>'
                   % (ln + 1, ln + 1, "".join(segs)))
    return "\n".join(out)


def _transitive_closure(fn, neighbors):
    """BFS 求某函数的传递闭包，按「最短距离」分层。返回 {depth: [fn, ...]}（不含自身）。
    neighbors(fn) -> 可迭代的相邻函数对象；层内保持邻居出现顺序（稳定）。"""
    layers = {}
    seen = {id(fn)}
    frontier = [fn]
    depth = 0
    while frontier:
        depth += 1
        nxt = []
        for f in frontier:
            for nf in neighbors(f):
                if id(nf) in seen:
                    continue
                seen.add(id(nf))
                layers.setdefault(depth, []).append(nf)
                nxt.append(nf)
        frontier = nxt
    return layers


# P44：传递闭包缓存——大型项目下 _compute_function_metrics 会为每个函数重复 BFS，
# 这里按函数 id 缓存影响面/依赖面结果，避免同一函数被反复计算（O(N²)→O(V+E)）。
_IMPACT_CACHE = {}
_DEPENDENCY_CACHE = {}


def _clear_closure_cache():
    """P44：清空传递闭包缓存（每次分析开始前调用，避免 id 复用导致脏缓存）。

    P71：一并清空全局调用图缓存 _CG_CACHE（其以 id(calls_of) 为键，测试序列中
    id 复用会命中脏缓存，导致同名候选/邻接表污染）。
    """
    _IMPACT_CACHE.clear()
    _DEPENDENCY_CACHE.clear()
    _CG_CACHE.clear()


def _impact_layers(fn, callers_of):
    """影响面：谁（直接 + 间接）调用了 fn → 沿 callers_of（上游）传递闭包（带缓存）。"""
    key = id(fn)
    cached = _IMPACT_CACHE.get(key)
    if cached is None:
        cached = _transitive_closure(fn, lambda f: callers_of.get(id(f), []))
        _IMPACT_CACHE[key] = cached
    return cached


def _dependency_layers(fn, calls_of):
    """依赖面：fn（直接 + 间接）调用了谁 → 沿 calls_of（下游）传递闭包（带缓存）。"""
    key = id(fn)
    cached = _DEPENDENCY_CACHE.get(key)
    if cached is None:
        cached = _transitive_closure(
            fn, lambda f: [cf for (cf, _dmf) in calls_of.get(id(f), [])])
        _DEPENDENCY_CACHE[key] = cached
    return cached


def _trace_roots(fn, callers_of):
    """P32：溯源到根——返回「无人调用（入口）但可传递调用到 fn」的最终祖先入口函数列表
    [(root_fn, depth)]，按距离（层数）升序。depth 为该入口到 fn 的最短层数。"""
    imp = _impact_layers(fn, callers_of)
    roots = []
    for depth in sorted(imp):
        for cf in imp[depth]:
            if not callers_of.get(id(cf)):
                roots.append((cf, depth))
    return roots


def _trace_status(fn, callers_of):
    """P43：返回函数溯源状态：
      'entry'    —— 本身是入口（无调用方）；
      'rooted'   —— 有调用方，且可上溯到「无调用方入口」；
      'orphaned' —— 有调用方，但上溯无法到达入口（处于调用循环、缺外部入口）。"""
    if not callers_of.get(id(fn)):
        return "entry"
    return "rooted" if _trace_roots(fn, callers_of) else "orphaned"


def _collect_orphaned(files, callers_of):
    """P43：收集「无法溯源到根」的函数（有调用方但上溯无法到达入口，即处于调用循环）。"""
    orphaned = []
    for mf in files:
        for f in mf.functions:
            if f.kind == "script":
                continue
            if _trace_status(f, callers_of) == "orphaned":
                orphaned.append((mf, f))
    return orphaned


def _render_impact_dependency_html(fn, callers_of, calls_of, fn_to_file, from_mf):
    """生成某函数「影响面 / 依赖面（传递闭包）」折叠区块（供源码页函数卡片）。
    影响面 = 谁（传递）调用本函数；依赖面 = 本函数（传递）依赖谁；均按最短距离分层列出，
    每项可点击跳转到对应函数源码，并附函数说明注释。"""
    imp = _impact_layers(fn, callers_of)
    dep = _dependency_layers(fn, calls_of)
    n_imp = sum(len(v) for v in imp.values())
    n_dep = sum(len(v) for v in dep.values())
    out = ['<details class="impact-block">'
           '<summary>影响面 / 依赖面（传递闭包 · 追本溯源）</summary>',
           '<div class="impact-body">']
    # 影响面
    out.append('<div class="impact-col"><b>影响面（改动本函数会波及 %d 个函数）：</b></div>'
               % n_imp)
    if n_imp:
        out.append('<ol class="call-order-list">')
        for depth in sorted(imp):
            for cf in imp[depth]:
                tmf = fn_to_file.get(id(cf))
                _d = _fn_desc(cf)
                dspan = (" — %s" % html_mod.escape(_d)) if _d else ""
                out.append('<li><a href="%s#L%d">%s</a>'
                           '<span class="muted"> · %s · 距离 %d</span>%s</li>'
                           % (_rel_href(from_mf.rel, tmf), cf.line,
                              html_mod.escape(cf.name),
                              html_mod.escape(tmf.rel if tmf else ""), depth, dspan))
        out.append('</ol>')
    else:
        out.append('<div class="muted">无（本函数为入口函数，无任何项目内调用方）。</div>')
    # 溯源到根（P32）：最终祖先 = 影响面中「无调用方」的入口函数（始终显示，便于理解）
    roots = _trace_roots(fn, callers_of)
    out.append('<div class="impact-col"><b>溯源到根（最终祖先入口函数，共 %d 个）：</b></div>'
               % len(roots))
    if roots:
        out.append('<ul class="call-order-list">')
        for cf, depth in roots:
            tmf = fn_to_file.get(id(cf))
            _d = _fn_desc(cf)
            dspan = (" — %s" % html_mod.escape(_d)) if _d else ""
            out.append('<li><a href="%s#L%d">%s</a>'
                       '<span class="muted"> · %s · 距本函数 %d 层</span>%s</li>'
                       % (_rel_href(from_mf.rel, tmf), cf.line,
                          html_mod.escape(cf.name),
                          html_mod.escape(tmf.rel if tmf else ""), depth, dspan))
        out.append('</ul>')
    else:
        out.append('<div class="muted">无（本函数无外部入口：为入口函数或处于调用循环中）。</div>')
    # 依赖面
    out.append('<div class="impact-col"><b>依赖面（本函数依赖 %d 个函数）：</b></div>'
               % n_dep)
    if n_dep:
        out.append('<ol class="call-order-list">')
        for depth in sorted(dep):
            for cf in dep[depth]:
                tmf = fn_to_file.get(id(cf))
                _d = _fn_desc(cf)
                dspan = (" — %s" % html_mod.escape(_d)) if _d else ""
                out.append('<li><a href="%s#L%d">%s</a>'
                           '<span class="muted"> · %s · 距离 %d</span>%s</li>'
                           % (_rel_href(from_mf.rel, tmf), cf.line,
                              html_mod.escape(cf.name),
                              html_mod.escape(tmf.rel if tmf else ""), depth, dspan))
        out.append('</ol>')
    else:
        out.append('<div class="muted">无（本函数为叶子函数，不调用任何项目内函数）。</div>')
    out.append('</div></details>')
    return "".join(out)


def _compute_function_metrics(files, callers_of, calls_of):
    """计算每个项目内函数的耦合风险指标（P23）：扇入 / 扇出 + 传递影响面 / 依赖面 + 圈复杂度。

    返回按「风险分」降序排列的 dict 列表。各字段：
      fan_in = 直接被调用数；fan_out = 直接调用数；
      impact = 影响面大小（传递调用方数）；dependency = 依赖面大小（传递被调数）；
      cx = 圈复杂度；risk = 加权风险分（影响面权重最高，兼顾扇入/依赖面/扇出/复杂度）；
      tag = 分类标签：关键 / 上帝函数 / 孤立 / 普通。
    用于「关键函数风险度量」排名表（HTML 报告 + 浏览站点 metrics.html）。"""
    rows = []
    for mf in files:
        for f in mf.functions:
            if f.kind == "script":
                continue
            fan_in = len(callers_of.get(id(f), []))
            fan_out = len(calls_of.get(id(f), []))
            impact_size = sum(len(v) for v in _impact_layers(f, callers_of).values())
            dependency_size = sum(len(v) for v in _dependency_layers(f, calls_of).values())
            cx = getattr(f, "complexity", 0) or 0
            # 风险分：影响面（改动波及范围）权重最高，其次被依赖度、依赖面、扇出、复杂度。
            risk = impact_size * 3 + fan_in * 2 + dependency_size + fan_out + cx
            tag = "普通"
            if fan_in == 0 and fan_out == 0:
                tag = "孤立"
            elif fan_out >= 8 or (fan_out >= 5 and cx >= 10):
                tag = "上帝函数"
            elif impact_size >= 5 or fan_in >= 5:
                tag = "关键"
            rows.append({
                "name": f.name, "rel": mf.rel, "line": f.line, "kind": f.kind,
                "cx": cx, "fan_in": fan_in, "fan_out": fan_out,
                "impact": impact_size, "dependency": dependency_size,
                "risk": risk, "tag": tag,
            })
    rows.sort(key=lambda r: (-r["risk"], r["rel"].lower(), r["name"].lower(), r["line"]))
    return rows


def _collect_unresolved_calls(files):
    """P25：收集「疑似漏检调用」诊断数据。汇总每个函数中未解析到项目/内置的调用名
    （func.external_calls），并标记该名是否在项目内存在同名函数/脚本（存在 → 疑似漏检，
    可能为脚本调用、限定名或解析遗漏；不存在 → 纯外部/工具箱）。返回按调用次数降序的列表。"""
    # R44 / C'''1：名字流来自 frontends.matlab 的**唯一产出点**。
    # 此前这里直接 cnt.update(f.external_calls)，于是「诊断页用的名字」与
    # 「归因用的名字」是两条各自独立的读取 —— 没有任何装置守着它们同源。
    cnt = Counter()
    for name, _line, _rel in f_matlab.unresolved_tuples(files):
        cnt[name] += 1
    project = {}
    for mf in files:
        for f in mf.functions:
            project.setdefault(f.name.lower(), []).append((mf.rel, f.name, f.line, f.kind))
    rows = []
    for name, c in cnt.most_common():
        matches = project.get(name.lower(), [])
        rows.append({"name": name, "count": c, "in_project": bool(matches), "matches": matches})
    return rows


def _collect_dynamic_calls(files):
    """P43：汇总各函数的动态执行调用（eval/run/evalin/evalc 等，需人工确认调用关系）。
    返回 [{rel, name, line, counts}]，其中 counts 为 {调用名: 次数}。"""
    out = []
    for mf in files:
        for f in mf.functions:
            if getattr(f, "dynamic_calls", None):
                out.append({"rel": mf.rel, "name": f.name, "line": f.line,
                            "counts": dict(f.dynamic_calls)})
    return out


def _collect_indirect_calls(files):
    """P225-L：汇总各函数的间接调用（cell 元素 C{1}(x) / 索引后 A(i)(x) / 动态字段 .(v)(x)）。
    这类调用目标运行期才确定，无法静态解析为项目内函数，此前调用图会完全遗漏。
    返回 [{rel, name, line, counts}]，counts 为 {被修饰基标识符/动态字段: 次数}。"""
    out = []
    for mf in files:
        for f in mf.functions:
            ic = getattr(f, "indirect_calls", None)
            if ic:
                out.append({"rel": mf.rel, "name": f.name, "line": f.line,
                            "counts": dict(ic)})
    return out


def _collect_index_like_calls(files):
    """P225-M：汇总各函数的索引样式调用（A(:)/A(end)/A(1)/A(2,3) 等疑似数组索引，非函数调用）。
    这些被调名解析不到函数，几乎必然是变量索引，已从 external_calls 剥离以免污染「疑似漏检」诊断。
    返回 [{rel, name, line, counts}]，counts 为 {被调名: 次数}。"""
    out = []
    for mf in files:
        for f in mf.functions:
            ilc = getattr(f, "index_like_calls", None)
            if ilc:
                out.append({"rel": mf.rel, "name": f.name, "line": f.line,
                            "counts": dict(ilc)})
    return out


def _collect_class_hierarchy(files):
    """P81：收集项目内全部 classdef 的继承关系。

    返回 (classes, children)：
      classes  = {类名: {"file": rel, "line": N, "supers": [父类短名...]}}（按文件序去重，重名取首个）
      children = {父类短名: [子类名...]}（仅含项目内定义的父类，用于向下展开子类）
    MATLAB 支持多继承 `classdef C < A & B`，父类可带包限定名 pkg.Cls（取末段作短名匹配）。
    """
    classes = {}
    for mf in files:
        for cls in mf.classes:
            if cls.name in classes:
                continue
            supers = []
            for s in cls.superclasses:
                short = s.rsplit(".", 1)[-1]
                if short and short not in supers:
                    supers.append(short)
            classes[cls.name] = {"file": mf.rel, "line": cls.line, "supers": supers}
    children = defaultdict(list)
    for name, info in classes.items():
        for sup in info["supers"]:
            if sup in classes and name not in children[sup]:
                children[sup].append(name)
    return classes, children


def render_class_hierarchy_svg(files, link_prefix=""):
    """P81：生成 doxygen 风格的「类继承图（Inheritance Diagram）」SVG。

    父类在上、子类在下，子类以空心三角箭头指向父类（UML 泛化方向，自下而上）；
    支持 MATLAB 多继承（一个子类可指向多个父类）。纯文本零依赖，节点可点击跳转源码页。
    link_prefix：从所在页面到站点根的相对前缀（页面在站点根传 ""，在 src/ 子页传 "../"）。
    """
    classes, children = _collect_class_hierarchy(files)
    if not classes:
        return ""
    from collections import deque
    # 根类：无项目内父类的类（继承树顶端）
    roots = [n for n in classes if not classes[n]["supers"]]
    depth = {}
    q = deque()
    for r in sorted(roots):
        depth[r] = 0
        q.append(r)
    # 多继承 DAG：取最长继承深度；未被任何根可达的孤立类归到第 0 层
    while q:
        n = q.popleft()
        nd = depth[n] + 1
        for c in sorted(children.get(n, [])):
            if c not in depth or depth[c] < nd:
                depth[c] = nd
                q.append(c)
    for n in classes:
        if n not in depth:
            depth[n] = 0
    layers = defaultdict(list)
    max_depth = 0
    for n, d in depth.items():
        layers[d].append(n)
        max_depth = max(max_depth, d)

    NODE_H = 46          # 节点高度（两行：类名 + 文件:行）
    X_GAP = 28           # 同层节点水平间距
    Y_GAP = 64           # 相邻层间距（节点顶到节点顶）
    TOP = 24
    LEFT = 24

    node_geom = {}
    for n, info in classes.items():
        file_name = info["file"].rsplit("/", 1)[-1]
        second = "%s:%d" % (file_name, info["line"])
        w = max(len(n), len(second)) * 7.5 + 32
        node_geom[n] = {"w": max(w, 96), "file_name": file_name, "second": second}

    layer_width = {}
    for d in range(max_depth + 1):
        nodes = sorted(layers.get(d, []))
        layer_width[d] = (sum(node_geom[n]["w"] for n in nodes)
                          + X_GAP * max(0, len(nodes) - 1)) if nodes else 0
    W = max(max(layer_width.values(), default=0), 300) + LEFT * 2
    H = TOP * 2 + max_depth * Y_GAP + NODE_H

    # 每层水平居中排布
    for d in range(max_depth + 1):
        nodes = sorted(layers.get(d, []))
        x_cursor = LEFT + (W - LEFT * 2 - layer_width[d]) / 2
        for n in nodes:
            node_geom[n]["x"] = x_cursor
            node_geom[n]["y"] = TOP + d * Y_GAP
            x_cursor += node_geom[n]["w"] + X_GAP

    svg = ['<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" '
           'viewBox="0 0 %d %d" font-family="Consolas,Microsoft YaHei,sans-serif">'
           % (W, H, W, H)]
    svg.append('<rect width="100%" height="100%" fill="#ffffff"/>')
    svg.append('<defs><marker id="inh-arrow" viewBox="0 0 10 10" refX="10" refY="5" '
               'markerWidth="9" markerHeight="9" orient="auto-start-reverse">'
               '<path d="M 0 0 L 10 5 L 0 10 z" fill="#ffffff" stroke="#57606a" stroke-width="1.2"/>'
               '</marker></defs>')

    # 边：子类顶部中心 -> 父类底部中心（空心三角箭头指向父类，UML 泛化方向）
    for n, info in classes.items():
        for sup in info["supers"]:
            if sup not in node_geom:
                continue
            x1 = node_geom[n]["x"] + node_geom[n]["w"] / 2
            y1 = node_geom[n]["y"]
            x2 = node_geom[sup]["x"] + node_geom[sup]["w"] / 2
            y2 = node_geom[sup]["y"] + NODE_H
            svg.append('<line x1="%.1f" y1="%.1f" x2="%.1f" y2="%.1f" stroke="#57606a" '
                       'stroke-width="1.2" marker-end="url(#inh-arrow)"/>'
                       % (x1, y1, x2, y2))

    # 节点：圆角矩形 + 类名（粗体）+ 文件:行，可点击跳转源码页
    for n in sorted(classes.keys()):
        info = classes[n]
        g = node_geom[n]
        x, y, w = g["x"], g["y"], g["w"]
        href = link_prefix + _src_href_from_rel(info["file"]) + "#L%d" % info["line"]
        svg.append('<a href="%s">' % html_mod.escape(href, quote=True))
        svg.append('<rect x="%.1f" y="%.1f" width="%.1f" height="%d" rx="6" fill="#f6f8fa" '
                   'stroke="#0969da" stroke-width="1.2"/>' % (x, y, w, NODE_H))
        svg.append('<title>%s</title>' % html_mod.escape(info["file"] + ":" + str(info["line"])))
        svg.append('<text x="%.1f" y="%.1f" font-size="13" font-weight="bold" fill="#0969da" '
                   'text-anchor="middle">%s</text>' % (x + w / 2, y + 19, html_mod.escape(n)))
        svg.append('<text x="%.1f" y="%.1f" font-size="10" fill="#57606a" text-anchor="middle">%s</text>'
                   % (x + w / 2, y + 34, html_mod.escape(g["second"])))
        svg.append('</a>')

    svg.append('</svg>')
    return "\n".join(svg)


def _collect_class_collaborations(files):
    """A3：收集类间协作（uses）关系——某类的任一方法调用了另一类的任一方法/构造函数。

    返回 (collab, class_names)：
      collab      = {类名: {被引用类名: 次数}}
      class_names = {类名: rel}（项目内全部类，用于节点绘制与跳转）
    """
    class_names = {}
    for mf in files:
        for cls in mf.classes:
            if cls.name not in class_names:
                class_names[cls.name] = mf.rel
    collab = defaultdict(Counter)
    for mf in files:
        for cls in mf.classes:
            for meth in cls.methods:
                for callee in meth.calls:
                    cn = getattr(callee, "class_name", None)
                    if cn and cn in class_names and cn != cls.name:
                        collab[cls.name][cn] += 1
    return {k: dict(v) for k, v in collab.items()}, class_names


def render_class_collaboration_svg(files, link_prefix=""):
    """A3：生成 doxygen 风格的「类协作图（Collaboration Diagram）」SVG。

    节点为类（环形均匀分布），实心箭头由「引用方」指向「被引用方」（uses 关系），
    与继承图（空心三角、自下而上）视觉区分；边标签标注引用次数。节点可点击跳转源码页。
    """
    collab, class_names = _collect_class_collaborations(files)
    nodes = sorted(class_names.keys())
    if not nodes:
        return ""
    import math
    n = len(nodes)
    # 节点几何
    node_geom = {}
    max_w = 96
    for name in nodes:
        file_name = class_names[name].rsplit("/", 1)[-1]
        w = max(len(name), len(file_name)) * 7.5 + 32
        w = max(w, 96)
        max_w = max(max_w, w)
        node_geom[name] = {"w": w, "file_name": file_name}
    NODE_H = 46
    R = max(140.0, n * 42.0)
    cx = R + max_w / 2 + 40
    cy = R + NODE_H / 2 + 40
    W = H = 2 * (R + max_w / 2 + 40)
    # 环形排布（自顶部顺时针）
    for i, name in enumerate(nodes):
        ang = -math.pi / 2 + 2 * math.pi * i / n
        node_geom[name]["x"] = cx + R * math.cos(ang) - node_geom[name]["w"] / 2
        node_geom[name]["y"] = cy + R * math.sin(ang) - NODE_H / 2

    svg = ['<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" '
           'viewBox="0 0 %d %d" font-family="Consolas,Microsoft YaHei,sans-serif">'
           % (W, H, W, H)]
    svg.append('<rect width="100%" height="100%" fill="#ffffff"/>')
    svg.append('<defs><marker id="collab-arrow" viewBox="0 0 10 10" refX="10" refY="5" '
               'markerWidth="8" markerHeight="8" orient="auto-start-reverse">'
               '<path d="M 0 0 L 10 5 L 0 10 z" fill="#8250df"/>'
               '</marker></defs>')

    # 边：引用方 -> 被引用方（实心箭头），带次数标签
    for src in nodes:
        for dst, cnt in collab.get(src, {}).items():
            if dst not in node_geom:
                continue
            s = node_geom[src]
            d = node_geom[dst]
            x1 = s["x"] + s["w"] / 2
            y1 = s["y"] + NODE_H / 2
            x2 = d["x"] + d["w"] / 2
            y2 = d["y"] + NODE_H / 2
            svg.append('<line x1="%.1f" y1="%.1f" x2="%.1f" y2="%.1f" stroke="#8250df" '
                       'stroke-width="1.2" marker-end="url(#collab-arrow)"/>'
                       % (x1, y1, x2, y2))
            if cnt > 1:
                mx = (x1 + x2) / 2
                my = (y1 + y2) / 2
                svg.append('<text x="%.1f" y="%.1f" font-size="10" fill="#8250df" '
                           'text-anchor="middle">%d</text>' % (mx, my - 4, cnt))

    # 节点：圆角矩形 + 类名 + 文件，可点击跳转
    for name in nodes:
        g = node_geom[name]
        x, y, w = g["x"], g["y"], g["w"]
        href = link_prefix + _src_href_from_rel(class_names[name])
        svg.append('<a href="%s">' % html_mod.escape(href, quote=True))
        svg.append('<rect x="%.1f" y="%.1f" width="%.1f" height="%d" rx="6" fill="#f6f8fa" '
                   'stroke="#8250df" stroke-width="1.2"/>' % (x, y, w, NODE_H))
        svg.append('<title>%s</title>' % html_mod.escape(class_names[name]))
        svg.append('<text x="%.1f" y="%.1f" font-size="13" font-weight="bold" fill="#8250df" '
                   'text-anchor="middle">%s</text>' % (x + w / 2, y + 19, html_mod.escape(name)))
        svg.append('<text x="%.1f" y="%.1f" font-size="10" fill="#57606a" text-anchor="middle">%s</text>'
                   % (x + w / 2, y + 34, html_mod.escape(g["file_name"])))
        svg.append('</a>')

    svg.append('</svg>')
    return "\n".join(svg)


def render_class_hierarchy_page(files):
    """P81：生成独立的「类层次（Class Hierarchy）」页面（--browse 模式专用），
    doxygen 风格的类继承图（父上子下）+ 类定义明细表。"""
    classes, children = _collect_class_hierarchy(files)
    lines = []
    A = lines.append
    A("<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
      "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">")
    A("<script>(function(){try{var t=localStorage.getItem('gs-theme');"
      "if(!t){t=(window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light';}"
      "if(t==='dark'){document.documentElement.setAttribute('data-theme','dark');}}catch(e){}})();</script>")
    A("<title>类层次（Class Hierarchy）</title>")
    A('<link rel="stylesheet" href="src/styles.css">')
    A("</head><body>")
    A('<a class="skip-link" href="#main-content">跳到主内容</a>')
    A("<header><span class=\"brand\">类层次</span>"
      "<a href=\"index.html\">&larr; 返回索引</a></header>")
    A("<main id=\"main-content\">")
    A("<h1>类层次（Class Hierarchy）</h1>")
    if not classes:
        A("<div class=\"muted\">项目内未发现 classdef 类定义。</div>")
        A("</main></body></html>")
        return "\n".join(lines)
    A("<div class=\"muted\">父类在上、子类在下，箭头由子类指向父类（UML 泛化方向）。"
      "支持 MATLAB 多继承（<code>classdef C &lt; A &amp; B</code>）。"
      "点击节点跳转到该类源码定义行。</div>")
    A("<div class=\"class-hierarchy-wrap\">%s</div>" % render_class_hierarchy_svg(files))
    # A3：类协作图（Collaboration Diagram）——uses 关系（引用方 -> 被引用方）
    collab_svg = render_class_collaboration_svg(files)
    if collab_svg:
        A("<h2>类协作图（Collaboration Diagram）</h2>")
        A("<div class=\"muted\">实心箭头由「引用方」指向「被引用方」（uses 关系），"
          "表示某类的方法调用了另一类的方法/构造函数；边标签为引用次数。"
          "与上方继承图的空心三角（is-a）视觉区分。</div>")
        A("<div class=\"class-hierarchy-wrap\">%s</div>" % collab_svg)
    # 类定义明细表
    A("<h2>类定义明细</h2>")
    A("<table><tr><th>类名</th><th>文件</th><th>继承（父类）</th><th>属性</th><th>方法</th></tr>")
    cls_by_name = {}
    for mf in files:
        for cls in mf.classes:
            cls_by_name.setdefault(cls.name, (mf, cls))
    for name in sorted(cls_by_name.keys()):
        mf, cls = cls_by_name[name]
        supers_txt = html_mod.escape(" & ".join(cls.superclasses) or "-")
        A("<tr><td><a href=\"%s#L%d\"><code>%s</code></a></td>"
          "<td><a href=\"%s\">%s</a></td>"
          "<td>%s</td><td>%d</td><td>%d</td></tr>"
          % (_src_href(mf), cls.line, html_mod.escape(cls.name),
             _src_href(mf), html_mod.escape(mf.rel),
             supers_txt, len(cls.properties), len(cls.methods)))
    A("</table>")
    A("</main></body></html>")
    return "\n".join(lines)


# A1：注释标签（annotation tags）——doxygen 风格 \todo/\bug/\deprecated 聚合
_ANNOTATION_TAGS = {
    "TODO": ("待办", "#0969da"),
    "BUG": ("缺陷", "#cf222e"),
    "DEPRECATED": ("弃用", "#6e7781"),
    "FIXME": ("待修复", "#bc4c00"),
    "NOTE": ("注意", "#1a7f37"),
    "XXX": ("临时方案", "#8250df"),
    "HACK": ("临时方案", "#8250df"),
    "WARNING": ("警告", "#9a6700"),
}
_RE_ANNOTATION = re.compile(
    r"^\s*%{1,2}\s*(TODO|BUG|DEPRECATED|FIXME|NOTE|XXX|HACK|WARNING)\b\s*[:：]?\s*(.*)$",
    re.IGNORECASE)


def _collect_annotations(files):
    """A1：扫描全部源码注释，聚合 TODO/BUG/DEPRECATED/FIXME/NOTE 等标签。

    返回 [{tag, text, file, line, kind}]，按「标签分组 + 文件/行号」稳定排序。
    kind 为标签中文名（用于页面分组标题）。"""
    rows = []
    for mf in files:
        for i, raw in enumerate(mf.source_lines, start=1):
            m = _RE_ANNOTATION.match(raw)
            if not m:
                continue
            tag = m.group(1).upper()
            text = m.group(2).strip()
            rows.append({"tag": tag, "text": text, "file": mf.rel, "line": i})
    # 稳定排序：先按标签（按 _ANNOTATION_TAGS 定义序），再按文件、行号
    tag_order = {t: idx for idx, t in enumerate(_ANNOTATION_TAGS)}
    rows.sort(key=lambda r: (tag_order.get(r["tag"], 99), r["file"], r["line"]))
    return rows


def render_annotations_page(annotations):
    """A1：生成「注释标签聚合」页面（--browse 模式专用），doxygen 风格
    \\todo/\\bug/\\deprecated 列表页——把散落的代码标记聚合成可跳转的技术债清单。"""
    lines = []
    A = lines.append
    A("<h1>注释标签聚合（TODO / BUG / DEPRECATED）</h1>")
    if not annotations:
        A("<div class=\"muted\">项目内未发现 TODO/BUG/DEPRECATED 等注释标签。</div>")
        return _browse_page("注释标签（TODO / BUG / DEPRECATED）", "注释标签",
                            "\n".join(lines))
    A("<div class=\"muted\">扫描源码注释中的 TODO / BUG / DEPRECATED / FIXME / NOTE / XXX / "
      "HACK / WARNING 标签并聚合，点击可跳转到对应源码行。</div>")
    # 按标签分组渲染（保留 _collect_annotations 的排序）
    groups = defaultdict(list)
    for r in annotations:
        groups[r["tag"]].append(r)
    for tag, label, color in [(t, _ANNOTATION_TAGS[t][0], _ANNOTATION_TAGS[t][1])
                              for t in _ANNOTATION_TAGS]:
        if tag not in groups:
            continue
        A("<h2 style=\"border-left:4px solid %s;padding-left:10px;\">%s <span class=\"muted\">"
          "(%s · %d 条)</span></h2>" % (color, html_mod.escape(label), tag, len(groups[tag])))
        A("<table><tr><th>文件</th><th>行</th><th>内容</th></tr>")
        for r in groups[tag]:
            href = "%s#L%d" % (_src_href_from_rel(r["file"]), r["line"])
            A("<tr><td><a href=\"%s\">%s</a></td><td class=\"num\">%d</td>"
              "<td><code>%s</code></td></tr>"
              % (href, html_mod.escape(r["file"]), r["line"],
                 html_mod.escape(r["text"] or "-")))
        A("</table>")
    # P-rev R78：骨架统一模板 _browse_page（输出与旧样板逐字节一致）
    return _browse_page("注释标签（TODO / BUG / DEPRECATED）", "注释标签",
                        "\n".join(lines))


def _collect_checks(files, enabled=None, dup_opts=None):
    """C3：聚合静态检查结果（未初始化 / 死代码 / 类型不一致），补 file 字段。

    enabled 为启用的检查名集合（None = 全部启用），用于告警阈值配置化。
    返回 {"uninitialized": [{file,name,func,line,reason}],
          "dead_code": [{file,func,line,reason}],
          "type_mismatch": [{file,name,func,from_type,to_type,from_line,line}],
          "dup_code": [{file,func,line,dup_with,reason,similarity}]}。"""
    uninit = []
    if enabled is None or "uninitialized" in enabled:
        for mf in files:
            for r in _detect_uninitialized(mf):
                r = dict(r)
                r["file"] = mf.rel
                uninit.append(r)
    dead = []
    if enabled is None or "dead_code" in enabled:
        for mf in files:
            # R62-R19：为死代码命中补上所属文件，使算子影响分析的「波及半径」准确。
            for _r in _detect_dead_code(mf):
                _r = dict(_r)
                _r.setdefault("file", mf.rel)
                _r.setdefault("func", _r.get("function"))
                dead.append(_r)
    mismatch = []
    if enabled is None or "type_mismatch" in enabled:
        mismatch = _detect_type_mismatch(files)
    shape = []
    if enabled is None or "shape_mismatch" in enabled:
        for r in _detect_shape_mismatch(files):
            r = dict(r)
            shape.append(r)
    dup = []
    if enabled is None or "dup_code" in enabled:
        for r in _detect_dup_code(
                files,
                min_lines=(dup_opts or {}).get("min_lines", _DUP_MIN_LINES),
                sim_threshold=(dup_opts or {}).get("sim", _DUP_SIM_THRESHOLD),
                frag_threshold=(dup_opts or {}).get("frag_sim", _DUP_FRAG_THRESHOLD),
                semantic=(dup_opts or {}).get("semantic", True),
                # P217x：增量索引缓存（按文件内容签名复用 token 序列）
                token_cache_path=(dup_opts or {}).get("token_cache")):
            r = dict(r)
            dup.append(r)
    return {"uninitialized": uninit, "dead_code": dead, "type_mismatch": mismatch,
            "shape_mismatch": shape, "dup_code": dup,
            "suppressed": _count_suppressed(files)}


# ======================================================================
# R62：检测算子工程影响分析
# ----------------------------------------------------------------------
# 工具内置数十个静态检查算子（未初始化 / 类型不一致 / 死代码 / 重复代码 /
# 污点流 / 跨语言启发式等）。本模块把这些算子聚合成「工程影响」视图：每个
# 在检测中实际触发的算子，按其 命中数 × 严重度 × 波及系数 计算综合影响分，
# 并按影响分降序排名，帮助使用者一眼看清「哪些算子对整个工程影响最大」。
# ======================================================================

# 算子元数据：键为 checks_for_sarif 的分类键（或 C/PY/JS 启发式的 kind）。
# R62-R30：算子 registry（建议#10）——标签/严重度/类别 + 描述，驱动影响分析、
# 文档与测试覆盖；新增算子应在此登记元数据，避免遗漏。
_OPERATOR_META = {
    "uninitialized": {"label": "未初始化变量", "level": "error", "category": "正确性/安全",
                      "desc": "变量/字段在使用前未赋值，MATLAB 默认置 0 掩盖逻辑错误。"},
    "dead_code": {"label": "死代码", "level": "warning", "category": "可维护性",
                  "desc": "定义后从未被读取/调用的函数或变量，增加维护负担。"},
    "type_mismatch": {"label": "类型不一致", "level": "warning", "category": "正确性",
                      "desc": "同一符号在不同位置被当作不同类型使用。"},
    "shape_mismatch": {"label": "矩阵维度不匹配", "level": "warning", "category": "正确性",
                       "desc": "运算/拼接/索引处维度不兼容，易触发运行时错误。"},
    "dup_code": {"label": "重复代码", "level": "warning", "category": "可维护性",
                 "desc": "近似代码块重复出现，应抽取为函数。"},
    "tainted_sink": {"label": "污点流危险调用点", "level": "error", "category": "安全",
                     "desc": "敏感输入未经净化即到达危险调用点，易致注入/执行。"},
    "tainted_src": {"label": "污点源（敏感输入）", "level": "note", "category": "安全",
                    "desc": "被标记为不可信来源的输入（如文件/网络/参数）。"},
    "workspace": {"label": "工作区变量滥用", "level": "warning", "category": "正确性",
                  "desc": "依赖全局/工作区变量，状态不可控、易冲突。"},
    "perf_bottleneck": {"label": "性能瓶颈", "level": "warning", "category": "性能",
                        "desc": "可避免的低效模式（如循环内重复分配）。"},
    "code_quality": {"label": "代码质量", "level": "warning", "category": "可维护性",
                     "desc": "可读性/规范类问题（命名、结构等）。"},
    "outdated_syntax": {"label": "过时语法", "level": "note", "category": "可维护性",
                        "desc": "已废弃或将被移除的语法（如 legacy 风格）。"},
    "short_circuit": {"label": "短路求值误用", "level": "warning", "category": "正确性",
                      "desc": "误用短路逻辑导致分支判断错误。"},
    "loop_vectorize": {"label": "可向量化循环", "level": "note", "category": "性能",
                       "desc": "可用向量化替代的逐元素循环，提升性能。"},
    "todo": {"label": "待办/技术债注释", "level": "note", "category": "可维护性",
             "desc": "TODO/FIXME 等标记，提示未完成任务。"},
    "suppressed": {"label": "已抑制告警", "level": "note", "category": "治理",
                   "desc": "被显式抑制的告警，需定期复审防止疲劳。"},
}

# 严重度权重：错误对工程的危害远大于提示。
_LEVEL_WEIGHT = {"error": 10.0, "warning": 3.0, "note": 1.0}


def _operator_meta_fallback(kind):
    """为未在 _OPERATOR_META 登记的算子（主要是跨语言启发式 kind，如
    c_use_after_free / py_unused_import / js_*）推导可读标签与严重度。
    优先查 _CROSS_LANG_KIND_META 显式映射（R62-R24），否则回退关键词推导。"""
    if kind in _CROSS_LANG_KIND_META:
        return dict(_CROSS_LANG_KIND_META[kind])
    if kind.startswith("c_"):
        prefix, body = "C", kind[2:]
    elif kind.startswith("py_"):
        prefix, body = "Python", kind[3:]
    elif kind.startswith("js_"):
        prefix, body = "JS", kind[3:]
    else:
        prefix, body = "", kind
    level = "warning"
    if any(k in kind for k in ("unused", "dead", "todo", "deprecated", "style")):
        level = "note"
    if any(k in kind for k in ("use_after", "free", "injection", "exec", "eval", "overflow")):
        level = "error"
    label = (prefix + ": " if prefix else "") + body.replace("_", " ").strip()
    return {"label": label, "level": level, "category": "跨语言启发式"}


# R62：工具内置静态检查算子的已知目录规模（superpower 盘点共 44 个检测算子）。
# 用于「启用覆盖率」参考上限（实际覆盖率按本次启用且产出的算子计算）。
_OPERATOR_CATALOG_SIZE = 44

# R62-R17：大仓保护——单算子波及集合（文件/函数）扫描上限，避免超大规模工程
# 下集合无限膨胀；命中计数仍按全量统计，仅波及半径采样。
_OPERATOR_MAX_BLAST_SCAN = 20000

# R62-R21：波及系数权重集中为可调常量，便于按团队风险偏好调参（建议#1）。
OPERATOR_BLAST_FILE_W = 0.4
OPERATOR_BLAST_FUNC_W = 0.2

# R62-R24：跨语言启发式 kind 的显式元数据映射（替代纯关键词猜测，建议#5）。
# 未在此表登记的 kind 仍走 _operator_meta_fallback 的关键词推导兜底。
_CROSS_LANG_KIND_META = {
    "py_unused_import": {"label": "Python 未使用导入", "level": "warning", "category": "可维护性"},
    "py_eval_usage": {"label": "Python eval 危险调用", "level": "error", "category": "安全"},
    "py_sql_injection": {"label": "Python SQL 拼接", "level": "error", "category": "安全"},
    "c_use_after_free": {"label": "C 释放后使用", "level": "error", "category": "安全"},
    "c_buffer_overflow": {"label": "C 缓冲区溢出", "level": "error", "category": "安全"},
    "c_double_free": {"label": "C 重复释放", "level": "error", "category": "安全"},
    "js_dangerous_call": {"label": "JS 危险调用", "level": "error", "category": "安全"},
    "js_unused_var": {"label": "JS 未使用变量", "level": "note", "category": "可维护性"},
    "js_prototype_pollution": {"label": "JS 原型污染", "level": "error", "category": "安全"},
}

# R62-R38：**已声明但明确不实现**的 kind —— 显式登记，并写明不实现的原因。
# 为什么要这张表而不是直接从 _CROSS_LANG_KIND_META 删掉：
#   「做不到」是一种工程结论，需要留下痕迹；否则下一个人会重新加上表项、
#   又变成「目录宣称有、代码不产出」的幻影算子。
# 为什么允许不实现：诚实 > 数量。宁可在目录里承认缺一项，也不要做一个
#   完全不可靠、把用户引向错误结论的正则近似。
# 由 tools/check_operator_impl.py 守门：_CROSS_LANG_KIND_META 里每个 kind
#   都必须在元表之外被 `"kind": "<name>"` 真正产出；不实现者必须登记在此。
_UNIMPLEMENTED_KINDS = {
    "py_undefined_name": (
        "需要真实的作用域链 / 名字解析（含 import *、类型标注、全局注入、"
        "条件定义）。当前 Python 前端是行锚定轻量解析器，做不到；若用正则近似，"
        "几乎必然在正常代码上大量误报，反而掩盖真问题。故显式登记为未实现。"),
}


def _compute_operator_impact(checks_for_sarif, enabled_checks=None, threshold=0.0,
                             scan_cap=None):
    """R62：计算各检测算子对整个工程的综合影响，并降序排名。

    工程影响分 = 命中数 × 严重度权重 × 波及系数
      · 命中数  ：该算子在本工程实际产出的检出条数（频次越高影响越大）。
      · 严重度  ：error=10 / warning=3 / note=1（取自 _OPERATOR_META / 推导）。
      · 波及系数：1 + 0.4·ln(1+文件数) + 0.2·ln(1+函数数)。检出散落越多文件/函数，
        工程级风险越高（如跨文件污点传播、全局重复代码）。

    额外产出（迭代增强）：
      · fix_priority：在影响分基础上对 error 级再乘 2，作为「修复优先级」，
        避免高体量低危算子掩盖安全类算子（影响分≠修复优先级）。
      · impact_norm：归一化到 0-100（相对本轮最强算子），便于跨工程横向比较。
      · pct：该算子占本轮总影响分的百分比。
      · by_category：按类别聚合（正确性/安全、可维护性、性能、跨语言…）及小计。
      · severity_dist：触发算子的严重度分布（error/warning/note 计数）。
      · coverage：若给出 enabled_checks，统计「启用且实际产出」的覆盖率%。
      · example：每算子的首条命中位置（file:line），便于直接定位。

    对 C/PY/JS 的 {x_heuristics:[{kind,file,...}]} 包装，按 kind 展开后逐类聚合。
    threshold 用于过滤低影响噪点（仅影响 < threshold 的算子不计入排名）。
    """
    import math as _math
    _cap = scan_cap or _OPERATOR_MAX_BLAST_SCAN   # R62-R36：可配置采样上限
    by_kind = defaultdict(list)
    suppressed = 0
    suppressed_with_reason = 0   # R62-R29：带抑制理由/到期的治理项计数
    for key, findings in (checks_for_sarif or {}).items():
        if key == "suppressed":
            if isinstance(findings, list):
                for _s in findings:
                    suppressed += 1
                    if isinstance(_s, dict) and _s.get("reason"):
                        suppressed_with_reason += 1
            continue
        if not isinstance(findings, list):
            continue
        if key.endswith("_heuristics"):
            # C/PY/JS 启发式：按 kind 展开
            for _h in findings:
                by_kind[_h.get("kind", key)].append(_h)
        else:
            for _f in findings:
                by_kind[key].append(_f)
    rows = []
    sev_dist = {"error": 0, "warning": 0, "note": 0}
    for _kind, _flist in by_kind.items():
        _count = len(_flist)
        if _count == 0:
            continue
        _meta = _OPERATOR_META.get(_kind) or _operator_meta_fallback(_kind)
        _files, _funcs = set(), set()
        _example = None
        for _idx, _f in enumerate(_flist):
            _ff = _f.get("file")
            if _ff and _idx < _cap:   # R62-R17/R36 采样上限
                _files.add(_ff)
            _fn = _f.get("func") or _f.get("function")
            if _fn and _idx < _cap:
                _funcs.add(_fn)
            if _example is None:
                _ln = _f.get("line") or _f.get("lineno")
                _fn2 = _f.get("func") or _f.get("function")
                if _ff:
                    _example = (("%s:%s" % (_ff, _ln)) if _ln
                                else ("%s::%s" % (_ff, _fn2) if _fn2 else _ff))
                elif _fn2:
                    _example = _fn2
        _sev_w = _LEVEL_WEIGHT.get(_meta["level"], 3.0)
        _n_files = max(len(_files), 1)
        _n_funcs = max(len(_funcs), 0)
        # R62-R21：波及系数权重使用可调常量（OPERATOR_BLAST_FILE_W / _FUNC_W）。
        _blast = (1.0 + OPERATOR_BLAST_FILE_W * _math.log(1.0 + _n_files)
                  + OPERATOR_BLAST_FUNC_W * _math.log(1.0 + _n_funcs))
        _impact = _count * _sev_w * _blast
        if _impact < threshold:
            continue
        sev_dist[_meta["level"]] = sev_dist.get(_meta["level"], 0) + 1
        rows.append({
            "rule": _kind,
            "label": _meta["label"],
            "level": _meta["level"],
            "category": _meta["category"],
            "count": _count,
            "files": len(_files),
            "funcs": len(_funcs),
            "cross_file": len(_files) > 1,   # R62-R25：跨文件维度（安全尤其关键）
            "blast": round(_blast, 3),
            "impact": round(_impact, 2),
            # R62-R22：影响分构成拆解，便于审计（命中×严重度×波及）。
            "impact_breakdown": {"count": _count,
                                 "severity_w": round(_sev_w, 2),
                                 "blast": round(_blast, 3)},
            "fix_priority": round(_impact * (2.0 if _meta["level"] == "error" else 1.0), 2),
            "example": _example,
        })
    rows.sort(key=lambda r: r["impact"], reverse=True)
    _max = max((r["impact"] for r in rows), default=0.0) or 1.0
    _total_impact = sum(r["impact"] for r in rows)
    for _r in rows:
        _r["impact_norm"] = round(_r["impact"] / _max * 100, 1)
        _r["pct"] = round(_r["impact"] / _total_impact * 100, 1) if _total_impact else 0.0
    # 按类别聚合（R62-R1：category 分组 + 小计）
    _cat = defaultdict(lambda: {"count": 0, "impact": 0.0, "operators": []})
    for _r in rows:
        _c = _cat[_r["category"]]
        _c["count"] += _r["count"]
        _c["impact"] += _r["impact"]
        _c["operators"].append(_r["rule"])
    by_category = [{"category": _k, "count": _v["count"],
                    "impact": round(_v["impact"], 2), "operators": _v["operators"]}
                   for _k, _v in sorted(_cat.items(),
                                        key=lambda kv: kv[1]["impact"], reverse=True)]
    # 启用覆盖率（R62-R3）
    coverage = None
    silent = None
    if enabled_checks:
        _enabled = set(enabled_checks)
        _fired = set(r["rule"] for r in rows) & _enabled
        coverage = round(len(_fired) / len(_enabled) * 100, 1) if _enabled else None
        # R62-R23：静默算子——启用却 0 检出，是「检查盲区」的信号。
        silent = sorted(_enabled - _fired)
    # P221-A：目录全量算子（每一个都被统计）。实装目录(_OPERATOR_META) + 本次命中的跨语言动态算子。
    _fired_map = {r.get("kind") or r["rule"]: r for r in rows}
    _catalog = []
    for _kind in sorted(_OPERATOR_META.keys()):
        _m = _OPERATOR_META[_kind]
        _fr = _fired_map.get(_kind)
        _catalog.append({
            "rule": _kind,
            "label": _m.get("label", _kind),
            "level": _m.get("level", "warning"),
            "category": _m.get("category", "matlab"),
            "fired": _fr is not None,
            "count": _fr["count"] if _fr else 0,
            "impact": _fr["impact"] if _fr else 0.0,
        })
    # 跨语言动态算子（仅当本次启用 lang 检查且命中时；不在 _OPERATOR_META 静态目录内）
    for _kind in sorted(set(_fired_map) - set(_OPERATOR_META.keys())):
        _fr = _fired_map[_kind]
        _fb = _operator_meta_fallback(_kind)
        _catalog.append({
            "rule": _kind,
            "label": _fb.get("label", _kind),
            "level": _fb.get("level", "warning"),
            "category": _fb.get("category", "cross"),
            "fired": True,
            "count": _fr["count"],
            "impact": _fr["impact"],
        })
    _total_findings = sum(r["count"] for r in rows)
    return {
        "operators": rows,
        "total_findings": _total_findings,
        "total_impact": round(_total_impact, 2),
        "fired_count": len(rows),
        "suppressed_count": suppressed,
        "suppressed_with_reason": suppressed_with_reason,
        "silent_checks": silent,
        "top3": [r["label"] for r in rows[:3]],
        "high_blast": [r["rule"] for r in rows if r["files"] >= 5],
        "cross_file_ops": [r["rule"] for r in rows if r.get("cross_file")],
        "severity_dist": sev_dist,
        "by_category": by_category,
        "coverage": coverage,
        # P221-A：全量算子统计（命中/零命中）与目录覆盖。
        # catalog_total 取实际登记算子数（_OPERATOR_META 静态目录 + 本次命中动态算子），
        # 不再硬编码 _OPERATOR_CATALOG_SIZE，避免「未纳管」幻影；每个登记算子都被统计/可见。
        "catalog_operators": _catalog,
        "catalog_total": len(_catalog),
        "catalog_fired": sum(1 for _c in _catalog if _c["fired"]),
        # P224-U：真实一致性核验——所有「已命中」算子必须进入目录（静态+动态已追加），
        # 故 unmapped 应为 0；若 >0 说明存在被统计却未入册的命中（「计数失灵」信号）。
        "catalog_unmapped": len(set(_fired_map) - set(c["rule"] for c in _catalog)),
    }
    # P224-U：一致性自检（不致命，仅暴露隐患）——目录内 fired 计数之和须等于总检出条数，
    # 否则表明 findings 的 key 空间与目录 key 空间错位（统计自洽但计数失真）。
    _fired_sum = sum(c["count"] for c in _catalog if c["fired"])
    if _fired_sum != _total_findings:
        import warnings as _w
        _w.warn("算子目录命中计数(%d) 与总检出(%d) 不一致：存在未入册命中键"
                % (_fired_sum, _total_findings))


# R62：各类别算子的修复建议（R62-R14），按类别给出治理方向。
_OPERATOR_REMEDIATION = {
    "正确性/安全": "优先补全变量初始化与类型/维度校验，建立输入边界检查。",
    "安全": "审计危险调用点与敏感输入链路，最小化权限与序列化面。",
    "可维护性": "清理死代码、统一语法、降低重复率，提升可读性与可测性。",
    "性能": "消除瓶颈循环、优先向量化，减少重复计算与内存拷贝。",
    "跨语言启发式": "按语言规范统一检查项，纳入对应语言的 CI 门禁。",
    "治理": "定期复核已抑制项，避免告警疲劳掩盖真实风险。",
}


def _render_operator_impact_markdown(oi):
    """R62：把算子影响分析渲染为 Markdown 段落（供报告 / 独立文件）。"""
    lines = []
    A = lines.append
    ops = oi.get("operators", [])
    A("## 检测算子工程影响分析（R62）")
    A("")
    A("将工具内置的静态检查算子按「对整个工程的影响」聚合排名，帮助快速定位"
      "**影响面最大**的检测类别。影响分 = 命中数 × 严重度权重 × 波及系数"
      "（错误=10 / 警告=3 / 提示=1；波及系数随散落文件/函数数对数增长）。")
    A("")
    if oi.get("coverage") is not None:
        A("- 启用覆盖率：**%.1f%%**" % oi["coverage"])
    A("- 触发算子：**%d** 个 ｜ 总检出：**%d** 条 ｜ 已抑制：**%d** 条"
      % (oi["fired_count"], oi["total_findings"], oi.get("suppressed_count", 0)))
    _sd = oi.get("severity_dist", {})
    A("- 严重度分布：error **%d** ｜ warning **%d** ｜ note **%d**"
      % (_sd.get("error", 0), _sd.get("warning", 0), _sd.get("note", 0)))
    if oi.get("top3"):
        A("- 影响 Top-3：**%s**" % " ＞ ".join(oi["top3"]))
    if oi.get("high_blast"):
        A("- 高波及算子（横跨 ≥5 文件）：%s" % "、".join(oi["high_blast"]))
    # R62-R25：跨文件安全算子（一条污点穿越多文件）重点提示。
    if oi.get("cross_file_ops"):
        A("- 跨文件算子（检出散落多文件，安全风险更高）：%s"
          % "、".join(oi["cross_file_ops"]))
    if oi.get("suppressed_with_reason"):
        A("- 带理由/到期的抑制项：**%d** 条（建议定期复审，防止告警疲劳）"
          % oi["suppressed_with_reason"])
    # R62-R23：静默算子=启用却 0 检出，是「检查盲区」信号。
    if oi.get("silent_checks"):
        A("- 静默算子（启用但 0 检出，检查盲区）：%s"
          % "、".join(oi["silent_checks"]))
    A("")
    if not ops:
        A("> 本次扫描未触发任何静态检查算子（或被全部抑制）。")
        A("")
        return "\n".join(lines)
    A("### 按类别聚合")
    A("")
    A("| 类别 | 命中 | 影响分 | 算子 |")
    A("|------|-----:|-------:|------|")
    for _c in oi.get("by_category", []):
        A("| %s | %d | **%.2f** | %s |"
          % (_c["category"], _c["count"], _c["impact"], "、".join(_c["operators"])))
    A("")
    A("### 算子影响排名（按工程影响分降序）")
    A("")
    A("| 排名 | 检测算子 | 类别 | 严重度 | 命中 | 文件 | 函数 | 跨文件 | 构成(命中×严重度×波及) | 影响分 | 归一化 | 修复优先级 | 占比 | 首条示例 |")
    A("|----:|----------|------|--------|-----:|-----:|-----:|:----:|----------------------:|-------:|-------:|-----------:|-----:|----------|")
    for _i, _r in enumerate(ops, 1):
        _bd = _r.get("impact_breakdown", {}) or {}
        A("| %d | %s | %s | %s | %d | %d | %d | %s | %d×%.1f×%.2f | **%.2f** | %.1f | %.2f | %.1f%% | %s |"
          % (_i, _r["label"], _r["category"], _r["level"], _r["count"],
             _r["files"], _r["funcs"], "Y" if _r.get("cross_file") else "N",
             _bd.get("count", _r["count"]), _bd.get("severity_w", 0.0),
             _bd.get("blast", 0.0), _r["impact"], _r["impact_norm"],
             _r["fix_priority"], _r["pct"], _r.get("example") or "-"))
    A("")
    A("### 修复建议（按类别）")
    A("")
    for _c in oi.get("by_category", []):
        A("- **%s**：%s" % (_c["category"],
                            _OPERATOR_REMEDIATION.get(_c["category"],
                                                     "结合本工程实际评估治理优先级。")))
    A("")
    A("> 影响分衡量「检出规模与扩散面」，修复优先级对 error 级再加权（×2）；"
      "安全类算子即便影响分不最高也应优先治理。归一化分便于跨工程横向比较。")
    A("")
    return "\n".join(lines)


def _safe_print(*args, **kwargs):
    """R62：控制台安全打印——尽力以 UTF-8 输出，非 UTF-8 终端则按 errors='replace'
    兜底，避免 Windows 默认 GBK 终端因中文报错（R62-R16 健壮性）。"""
    try:
        try:
            sys.stdout.reconfigure(encoding="utf-8")
        except (AttributeError, ValueError, OSError):
            pass
        print(*args, **kwargs)
    except (UnicodeEncodeError, UnicodeDecodeError):
        _enc = (getattr(sys.stdout, "encoding", None) or "ascii")
        _safe = [str(a).encode(_enc, "replace").decode(_enc) for a in args]
        print(*_safe, **kwargs)


def _print_operator_impact(oi):
    """R62：控制台打印算子影响分析摘要（含占比%，兼容非 UTF-8 终端）。"""
    _safe_print("\n===== 检测算子工程影响分析（R62） =====")
    _cov = (" | 启用覆盖率 %.1f%%" % oi["coverage"]) if oi.get("coverage") is not None else ""
    _safe_print("触发算子 %d 个 | 总检出 %d 条 | 已抑制 %d 条%s | Top-3: %s"
                % (oi["fired_count"], oi["total_findings"],
                   oi.get("suppressed_count", 0), _cov,
                   " > ".join(oi["top3"]) if oi["top3"] else "-"))
    ops = oi.get("operators", [])
    if not ops:
        _safe_print("  (本次扫描未触发任何静态检查算子)")
        return
    _safe_print("%-4s %-22s %-6s %5s %6s %6s %3s %9s %7s %6s" %
                ("#", "算子", "严重度", "命中", "文件", "函数", "跨", "影响分", "归一化", "占比%"))
    for _i, _r in enumerate(ops, 1):
        _lab = _r["label"]
        if len(_lab) > 20:
            _lab = _lab[:19] + "…"
        _safe_print("%-4d %-22s %-6s %5d %6d %6d %3s %9.2f %7.1f %5.1f" %
                    (_i, _lab, _r["level"], _r["count"], _r["files"],
                     _r["funcs"], "Y" if _r.get("cross_file") else "N",
                     _r["impact"], _r["impact_norm"], _r["pct"]))


def _operator_impact_csv(oi):
    """R62：把算子影响分析渲染为 CSV（R62-R6，便于表格软件/CI 进一步处理）。"""
    import csv as _csv
    import io as _io
    _buf = _io.StringIO()
    _w = _csv.writer(_buf)
    _w.writerow(["rank", "rule", "label", "category", "level", "count",
                 "files", "funcs", "cross_file", "severity_w", "blast",
                 "impact", "impact_norm", "fix_priority", "pct", "example"])
    for _i, _r in enumerate(oi.get("operators", []), 1):
        _bd = _r.get("impact_breakdown", {}) or {}
        _w.writerow([_i, _r["rule"], _r["label"], _r["category"], _r["level"],
                     _r["count"], _r["files"], _r["funcs"],
                     "Y" if _r.get("cross_file") else "N",
                     _bd.get("severity_w", ""), _bd.get("blast", ""),
                     _r["impact"], _r["impact_norm"], _r["fix_priority"],
                     _r["pct"], _r.get("example") or ""])
    return _buf.getvalue()


def _operator_impact_html(oi):
    """R62-R27：把算子影响渲染为自带条形图的 HTML，便于非技术干系人查看。"""
    _ops = oi.get("operators", [])
    _max = max((r["impact"] for r in _ops), default=0.0) or 1.0
    _rows = []
    for _r in _ops:
        _w = min(100.0, _r["impact"] / _max * 100.0)
        _color = {"error": "#dc2626", "warning": "#d97706", "note": "#2563eb"}.get(
            _r["level"], "#2563eb")
        _rows.append(
            '<tr><td title="%s">%s</td><td>%.2f</td>'
            '<td><div class="bar" style="width:%.1f%%;background:%s"></div></td>'
            '<td>%s</td></tr>' % (_r["rule"], _r["label"], _r["impact"], _w, _color,
                                  _r["category"]))
    _bars = "\n".join(_rows)
    _meta = oi.get("_meta") or {}
    _gen = _meta.get("generated_at", "")
    return (
        "<!doctype html><html lang='zh'><head><meta charset='utf-8'>"
        "<title>检测算子工程影响分析</title>"
        "<style>body{font-family:system-ui,Arial;margin:24px;color:#1f2937}"
        "h1{font-size:20px}table{border-collapse:collapse;width:100%%;margin-top:8px}"
        "td{padding:4px 8px;border-bottom:1px solid #e5e7eb;font-size:13px}"
        ".bar{height:14px;border-radius:3px}</style></head><body>"
        "<a class=\"skip-link\" href=\"#main-content\">跳到主内容</a>"
        "<main id=\"main-content\">"
        "<h1>检测算子工程影响分析（R62）</h1>"
        "<p>触发算子 <b>%d</b> 个 ｜ 总检出 <b>%d</b> 条 ｜ 总影响分 <b>%.2f</b>%s</p>"
        "<table><tr><th>算子</th><th>影响分</th><th>占比</th><th>类别</th></tr>"
        "%s</table>"
        "</main></body></html>"
        % (oi.get("fired_count", 0), oi.get("total_findings", 0),
           oi.get("total_impact", 0.0),
           (" ｜ 生成于 %s" % _gen) if _gen else "", _bars))


def _operator_impact_gate_violations(prev, cur, gate_pct):
    """R62-R28：门禁——error 级算子影响分环比上涨超过 gate_pct% 视为违规，
    用于把「趋势」变成 CI 质量回归卡点（建议#3）。返回 [(label, delta_pct), ...]。"""
    _p = {r["rule"]: r for r in prev.get("operators", [])}
    _viol = []
    for _r in cur.get("operators", []):
        if _r["level"] != "error":
            continue
        _pi = _p.get(_r["rule"], {}).get("impact", 0.0)
        if _pi <= 0:
            continue
        _delta = (_r["impact"] - _pi) / _pi * 100.0
        if _delta > gate_pct:
            _viol.append((_r.get("label", _r.get("rule", "?")), round(_delta, 1)))
    return _viol


def _operator_impact_delta_md(prev, cur):
    """R62：对比两次扫描的算子影响（R62-R11/R12），输出增量 Markdown。"""
    _p = {r["rule"]: r for r in prev.get("operators", [])}
    _c = {r["rule"]: r for r in cur.get("operators", [])}
    _all = sorted(set(_p) | set(_c),
                  key=lambda k: abs((_c.get(k, {}).get("impact", 0)
                                     - _p.get(k, {}).get("impact", 0))),
                  reverse=True)
    _lines = ["### 算子影响增量（vs 基线）", "",
              "| 算子 | 基线影响分 | 当前影响分 | 变化 |",
              "|------|-----------:|-----------:|-----:|"]
    for _k in _all[:15]:
        _pi = _p.get(_k, {}).get("impact", 0.0)
        _ci = _c.get(_k, {}).get("impact", 0.0)
        _d = round(_ci - _pi, 2)
        _arrow = "↑" if _d > 0 else ("↓" if _d < 0 else "—")
        _lines.append("| %s | %.2f | %.2f | %s%.2f |"
                      % (_c.get(_k, {}).get("label", _k) or _k, _pi, _ci,
                         _arrow, _d))
    _lines.append("")
    return "\n".join(_lines)


def _merge_operator_impact(oi_list):
    """R62：合并多次/多语言扫描的算子影响（R62-R13/R35），用于跨语言统一视图。

    各 oi 的 operators 按 rule 合并：命中/文件/函数累加，影响分取各次之和，
    严重度取最高（error > warning > note），跨文件标记取并集，标签/类别取首次出现。
    合并后重算 impact_norm / pct / by_category，产出与单次扫描同构的结果。
    """
    _lvl_rank = {"note": 0, "warning": 1, "error": 2}
    _agg = {}
    for _oi in oi_list:
        for _r in _oi.get("operators", []):
            _a = _agg.get(_r["rule"])
            if _a is None:
                _a = dict(_r)
                _agg[_r["rule"]] = _a
            else:
                _a["count"] += _r["count"]
                _a["files"] += _r["files"]
                _a["funcs"] += _r["funcs"]
                _a["impact"] = round(_a["impact"] + _r["impact"], 2)
                _a["fix_priority"] = round(_a["fix_priority"] + _r["fix_priority"], 2)
                _a["cross_file"] = _a.get("cross_file", False) or _r.get("cross_file", False)
                if _lvl_rank.get(_r["level"], 0) > _lvl_rank.get(_a["level"], 0):
                    _a["level"] = _r["level"]
    _ops = list(_agg.values())
    _ops.sort(key=lambda r: r["impact"], reverse=True)
    _max = max((r["impact"] for r in _ops), default=0.0) or 1.0
    _total = sum(r["impact"] for r in _ops)
    for _r in _ops:
        _r["impact_norm"] = round(_r["impact"] / _max * 100, 1)
        _r["pct"] = round(_r["impact"] / _total * 100, 1) if _total else 0.0
    _cat = defaultdict(lambda: {"count": 0, "impact": 0.0, "operators": []})
    for _r in _ops:
        _c = _cat[_r["category"]]
        _c["count"] += _r["count"]
        _c["impact"] += _r["impact"]
        _c["operators"].append(_r["rule"])
    _by_cat = [{"category": _k, "count": _v["count"], "impact": round(_v["impact"], 2),
                "operators": _v["operators"]}
               for _k, _v in sorted(_cat.items(),
                                    key=lambda kv: kv[1]["impact"], reverse=True)]
    return {
        "operators": _ops,
        "fired_count": len(_agg),
        "total_findings": sum(r["count"] for r in _ops),
        "total_impact": round(_total, 2),
        "by_category": _by_cat,
        "top3": [_r["label"] for _r in _ops[:3]],
        "high_blast": [_r["rule"] for _r in _ops if _r["files"] >= 5],
        "cross_file_ops": [_r["rule"] for _r in _ops if _r.get("cross_file")],
    }


def _apply_operator_impact(args, checks_for_sarif):
    """R62：对 C/PY/JS 等非 MATLAB 流程，计算并落地算子影响分析。

    与 MATLAB 主流程一致：控制台打印 + 回读 JSON 注入 operator_impact +
    按 --operator-impact-out 输出独立文件（Markdown / .csv）+ 基线持久化与对比。
    """
    _enabled = None
    if getattr(args, "checks", None):
        try:
            _enabled = _parse_checks_arg(args.checks)
        except Exception:
            _enabled = None
    _threshold = float(getattr(args, "operator_impact_threshold", 0) or 0)
    _scan_cap = getattr(args, "operator_impact_scan_cap", None)
    _oi = _compute_operator_impact(checks_for_sarif, enabled_checks=_enabled,
                                   threshold=_threshold, scan_cap=_scan_cap)
    _print_operator_impact(_oi)
    # 独立文件：按扩展名选择 CSV / Markdown / HTML（R62-R6/R27）
    _out = getattr(args, "operator_impact_out", None)
    if _out:
        _ext = str(_out).lower()
        if _ext.endswith(".csv"):
            _body = _operator_impact_csv(_oi)
        elif _ext.endswith(".html"):
            _body = _operator_impact_html(_oi)
        else:
            _body = _render_operator_impact_markdown(_oi)
        if _write_output(_out, _body, "算子影响分析"):
            print("[OK] 算子影响分析已写入：%s" % _out)
    # 基线持久化 + 对比 + 门禁（R62-R11/R12/R28/R38）
    _base = getattr(args, "operator_impact_baseline", None)
    if _base:
        try:
            _d = os.path.dirname(_base)
            if _d and not os.path.exists(_d):
                os.makedirs(_d, exist_ok=True)
            _oi_save = dict(_oi)
            from datetime import datetime as _dt
            _oi_save["_meta"] = {"tool": "matlabc",
                                 "generated_at": _dt.now().isoformat()}
            with io.open(_base, "w", encoding="utf-8") as _fh:
                json.dump(_oi_save, _fh, ensure_ascii=False, indent=2)
            print("[OK] 算子影响基线已保存：%s" % _base)
        except (IOError, OSError) as _e:
            print("[WARN] 保存基线失败：%s" % _e)
    if _base and os.path.exists(_base) and (
            getattr(args, "operator_impact_compare", False)
            or getattr(args, "operator_impact_gate", None) is not None):
        try:
            with io.open(_base, "r", encoding="utf-8") as _fh:
                _prev = json.load(_fh)
            if "operators" not in _prev and isinstance(_prev.get("operator_impact"), dict):
                _prev = _prev["operator_impact"]
            if getattr(args, "operator_impact_compare", False):
                print(_operator_impact_delta_md(_prev, _oi))
            _gate = getattr(args, "operator_impact_gate", None)
            if _gate is not None:
                _viol = _operator_impact_gate_violations(_prev, _oi, float(_gate))
                if _viol:
                    for _l, _d in _viol:
                        print("[GATE] error 类影响分上涨 %.1f%%：%s" % (_d, _l))
                    if getattr(args, "operator_impact_gate_fail", False):
                        print("[GATE] 触发门禁失败（error 类影响显著上涨）")
                        sys.exit(2)
                else:
                    print("[GATE] 未触发门禁（error 类影响分上涨均在 %.1f%% 内）"
                          % float(_gate))
        except (IOError, OSError, ValueError) as _e:
            print("[WARN] 基线对比/门禁失败：%s" % _e)
    if getattr(args, "json", None):
        try:
            with io.open(args.json, "r", encoding="utf-8") as _fh:
                _payload = json.load(_fh)
            _payload["operator_impact"] = _oi
            with io.open(args.json, "w", encoding="utf-8") as _fh:
                json.dump(_payload, _fh, ensure_ascii=False, indent=2)
            print("[OK] 算子影响分析已并入 JSON：%s" % args.json)
        except (IOError, OSError, ValueError) as _e:
            print("[WARN] 回读 JSON 合并算子影响失败：%s" % _e)


def render_checks_page(checks):
    """C3：生成「静态检查」汇总页（checks.html，--browse 模式专用）。

    聚合未初始化（高）/ 类型不一致（中）/ 死代码（低）三类告警，按严重度分级、
    可点击跳转源码行，把 JSON 里的检查结果变成 review 可直接使用的清单。"""
    lines = []
    A = lines.append
    A("<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
      "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">")
    A("<script>(function(){try{var t=localStorage.getItem('gs-theme');"
      "if(!t){t=(window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light';}"
      "if(t==='dark'){document.documentElement.setAttribute('data-theme','dark');}}catch(e){}})();</script>")
    A("<title>静态检查（未初始化 / 类型不一致 / 死代码）</title>")
    A('<link rel="stylesheet" href="src/styles.css">')
    A("</head><body>")
    A('<a class="skip-link" href="#main-content">跳到主内容</a>')
    A("<header><span class=\"brand\">静态检查</span>"
      "<a href=\"index.html\">&larr; 返回索引</a></header>")
    A("<main id=\"main-content\">")
    A("<h1>静态检查汇总</h1>")
    uninit = checks["uninitialized"]
    mismatch = checks["type_mismatch"]
    dead = checks["dead_code"]
    total = len(uninit) + len(mismatch) + len(dead)
    hi_uninit = sum(1 for r in uninit if r.get("confidence") == "high")
    suppressed = checks.get("suppressed", {"names": 0, "all": 0, "lines": 0, "blocks": 0})
    supp_total = suppressed["names"] + suppressed["all"] + suppressed["lines"] + suppressed["blocks"]
    A("<div class=\"muted\">聚合未初始化变量（高）、类型不一致（中）、死代码（低）三类静态检查告警，"
      "共 <b>%d</b> 条（其中未初始化高置信 <b>%d</b> 条）。点击跳转到对应源码行。</div>" % (total, hi_uninit))
    if supp_total > 0:
        A("<div class=\"muted\">另有 <b>%d</b> 条告警被抑制注释忽略"
          "（名称级 %d · 文件级 %d · 行级 %d · 区间级 %d，见 <code>%% analyzer:ignore</code> / <code>%% analyzer:disable</code>）。</div>"
          % (supp_total, suppressed["names"], suppressed["all"], suppressed["lines"], suppressed["blocks"]))
        # 抑制原因汇总（可审计明细，定期复审防止抑制疲劳）
        details = suppressed.get("details", [])
        if details:
            shown = details[:200]
            A("<details class=\"supp-details\"><summary>查看抑制明细（%d 条，点击展开）</summary>"
              "<ul class=\"supp-list\">" % len(details))
            for d in shown:
                A("<li>%s</li>" % html_mod.escape(d))
            if len(details) > len(shown):
                A("<li class=\"muted\">…另有 %d 条未显示（可在源码注释中核对）。</li>"
                  % (len(details) - len(shown)))
            A("</ul></details>")
    if total == 0:
        A("<div class=\"muted\">未发现静态检查告警——代码健康。</div>")
        A("</main></body></html>")
        return "\n".join(lines)

    # 高：未初始化变量
    A("<h2 style=\"border-left:4px solid #cf222e;padding-left:10px;\">未初始化变量 "
      "<span class=\"muted\">（高 · %d 条）</span></h2>" % len(uninit))
    if uninit:
        A("<table><tr><th>变量</th><th>函数</th><th>文件</th><th>行</th></tr>")
        for r in uninit:
            href = "%s#L%d" % (_src_href_from_rel(r["file"]), r["line"])
            A("<tr><td><code>%s</code></td><td>%s</td>"
              "<td><a href=\"%s\">%s</a></td><td class=\"num\">%d</td></tr>"
              % (html_mod.escape(r["name"]), html_mod.escape(r["func"]),
                 href, html_mod.escape(r["file"]), r["line"]))
        A("</table>")

    # 中：类型不一致
    A("<h2 style=\"border-left:4px solid #bc4c00;padding-left:10px;\">类型不一致 "
      "<span class=\"muted\">（中 · %d 条）</span></h2>" % len(mismatch))
    if mismatch:
        A("<table><tr><th>变量</th><th>函数</th><th>类型变化</th><th>文件</th><th>行</th></tr>")
        for r in mismatch:
            href = "%s#L%d" % (_src_href_from_rel(r["file"]), r["line"])
            A("<tr><td><code>%s</code></td><td>%s</td>"
              "<td><code>%s &rarr; %s</code></td>"
              "<td><a href=\"%s\">%s</a></td><td class=\"num\">%d</td></tr>"
              % (html_mod.escape(r["name"]), html_mod.escape(r["func"]),
                 html_mod.escape(r["from_type"]), html_mod.escape(r["to_type"]),
                 href, html_mod.escape(r["file"]), r["line"]))
        A("</table>")

    # 低：死代码
    A("<h2 style=\"border-left:4px solid #6e7781;padding-left:10px;\">死代码 "
      "<span class=\"muted\">（低 · %d 条）</span></h2>" % len(dead))
    if dead:
        A("<table><tr><th>函数</th><th>原因</th><th>文件</th><th>行</th></tr>")
        for r in dead:
            href = "%s#L%d" % (_src_href_from_rel(r["file"]), r["line"])
            A("<tr><td>%s</td><td>%s</td>"
              "<td><a href=\"%s\">%s</a></td><td class=\"num\">%d</td></tr>"
              % (html_mod.escape(r["func"]), html_mod.escape(r["reason"]),
                 href, html_mod.escape(r["file"]), r["line"]))
        A("</table>")
    A("</main></body></html>")
    return "\n".join(lines)


def _collect_file_metrics(files):
    """C3：收集文件级复杂度指标（总复杂度/函数数/类数/行数），按复杂度降序。

    返回 [{file, complexity, n_funcs, n_classes, lines}]。"""
    out = []
    for mf in files:
        n_funcs = sum(1 for f in mf.functions if f.kind != "script")
        total_cx = sum(f.complexity for f in mf.functions if f.kind != "script")
        out.append({"file": mf.rel, "complexity": total_cx,
                    "n_funcs": n_funcs, "n_classes": len(mf.classes),
                    "lines": mf.lines})
    out.sort(key=lambda x: -x["complexity"])
    return out


# =============================================================================
# P271 R6-1：MathWorks 官方代码审查清单引擎
# -----------------------------------------------------------------------------
# 依据 matlab-agentic-toolkit 的 matlab-review-code / matlab-modernize-code
# 两个官方技能所定义的审查标准（命名 / 函数质量 / 代码模式 / 高危项），
# 把「静态浏览站点」升级为「代码审查工作台」：不只让人看代码，而是直接
# 指出**要改什么、属于哪一级严重度、以及怎么改**。
#
# 严重度沿用官方约定的三级：error（必须改）> warning（应该改）> suggestion（可改）。
# =============================================================================

# 强烈不建议/已移除的 API → 现代替代方案（官方现代化速查表）
MODERNIZE_MAP = {
    "csvread": ("readmatrix", "文件 I/O"),
    "dlmread": ("readmatrix", "文件 I/O"),
    "csvwrite": ("writematrix", "文件 I/O"),
    "dlmwrite": ("writematrix", "文件 I/O"),
    "xlsread": ("readtable / readmatrix", "文件 I/O"),
    "xlswrite": ("writetable / writematrix", "文件 I/O"),
    "datenum": ("datetime", "日期时间（官方已标记 not recommended）"),
    "datestr": ("string(dt) / char(dt)，或设置 dt.Format", "日期时间（官方已标记 not recommended）"),
    "now": ("datetime", "日期时间（官方已标记 not recommended）"),
    "strmatch": ("startsWith / matches", "字符串"),
    "uicontrol": ("uibutton / uidropdown 等 uifigure 组件", "UI"),
    "guide": ("appdesigner", "UI（已移除）"),
    "str2num": ("str2double，或 str2num(text, Evaluation=\"restricted\")", "安全"),
    "containers.Map": ("dictionary", "数据结构（checkcode 不会报）"),
    "bsxfun": ("隐式扩展（直接写运算符即可）", "性能/可读性"),
    "clear all": ("clearvars", "工作区（会清除函数、强制重编译）"),
    # 官方列为**高危**：动态执行会绕过编译、可能覆盖工作区变量、有注入风险
    "eval": ("动态字段名 s.(name) / 函数句柄 / feval", "高危（安全与可维护性）"),
    "evalc": ("动态字段名 s.(name) / 函数句柄 / feval", "高危（安全与可维护性）"),
    "evalin": ("显式传参，或用函数句柄", "高危（跨工作区）"),
    "assignin": ("显式返回值，或用句柄对象", "高危（跨工作区）"),
}
# 官方明确列为「高危」的动态执行类
HIGH_RISK_DYNAMIC = ("eval", "evalc", "evalin", "assignin")

# 审查清单阈值（与官方标准一致）
REVIEW_LIMITS = {
    "max_positional_inputs": 6,
    "max_outputs": 4,
    "max_func_lines": 50,
    "max_nesting": 3,
    "high_fan_in": 8,
    "high_complexity": 15,
}

RE_CAMEL = re.compile(r"^[a-z][a-zA-Z0-9]*$")
RE_PASCAL = re.compile(r"^[A-Z][a-zA-Z0-9]*$")
RE_UPPER_SNAKE = re.compile(r"^[A-Z][A-Z0-9_]*$")
RE_BACKSLASH_PATH = re.compile(r"['\"][A-Za-z]:\\\\|['\"][^'\"]*\\\\[^'\"]*['\"]")


def _review_naming(mf):
    """命名约定检查：函数 lowerCamelCase、类 PascalCase、文件名与函数名一致。"""
    out = []
    base = os.path.basename(mf.rel)
    stem = base[:-2] if base.lower().endswith(".m") else base
    for f in mf.functions:
        if f.kind == "script":
            continue
        nm = f.name or ""
        if not RE_CAMEL.match(nm):
            out.append({
                "severity": "suggestion", "cat": "命名", "file": mf.rel,
                "line": f.line, "symbol": nm,
                "msg": "函数名 `%s` 不符合 lowerCamelCase 约定（应是动词短语，如 computeArea）" % nm,
                "how": "改为 lowerCamelCase 命名",
            })
        # 文件名应与主函数名一致（脚本文件无主函数，跳过）
    if mf.functions and stem and not stem.startswith("t"):
        primary = None
        for f in mf.functions:
            if f.kind != "script":
                primary = f
                break
        if primary is not None and primary.name and primary.name != stem:
            out.append({
                "severity": "warning", "cat": "命名", "file": mf.rel,
                "line": primary.line, "symbol": stem,
                "msg": "文件名 `%s.m` 与主函数名 `%s` 不一致" % (stem, primary.name),
                "how": "统一文件名与主函数名（官方约定：file = function）",
            })
    for c in getattr(mf, "classes", []) or []:
        cname = getattr(c, "name", "") or ""
        if cname and not RE_PASCAL.match(cname):
            out.append({
                "severity": "suggestion", "cat": "命名", "file": mf.rel,
                "line": getattr(c, "line", 0), "symbol": cname,
                "msg": "类名 `%s` 不符合 PascalCase 约定" % cname,
                "how": "改为 PascalCase 命名",
            })
    return out


def _review_function_quality(mf, calls_of=None, callers_of=None):
    """函数质量检查：参数/返回值个数、长度、嵌套深度、复杂度、arguments 块、H1 帮助行。"""
    out = []
    src = getattr(mf, "source_lines", []) or []
    for f in mf.functions:
        if f.kind == "script":
            continue
        name = f.name or ""
        n_in = len(getattr(f, "inputs", []) or [])
        n_out = len(getattr(f, "outputs", []) or [])
        if n_in > REVIEW_LIMITS["max_positional_inputs"]:
            out.append({
                "severity": "warning", "cat": "函数质量", "file": mf.rel,
                "line": f.line, "symbol": name,
                "msg": "`%s` 有 %d 个位置参数，超过建议上限 %d"
                      % (name, n_in, REVIEW_LIMITS["max_positional_inputs"]),
                "how": "用 arguments 块 + name-value（options.X）收敛参数",
            })
        if n_out > REVIEW_LIMITS["max_outputs"]:
            out.append({
                "severity": "warning", "cat": "函数质量", "file": mf.rel,
                "line": f.line, "symbol": name,
                "msg": "`%s` 有 %d 个返回值，超过建议上限 %d"
                      % (name, n_out, REVIEW_LIMITS["max_outputs"]),
                "how": "合并为结构体或 table 输出",
            })
        # 函数长度（用 body_end - line + 1；body_end 未算出时按 0 处理，即跳过该检查）
        end_line = getattr(f, "body_end", None)
        ln = (end_line - f.line + 1) if end_line else 0
        if ln and ln > REVIEW_LIMITS["max_func_lines"]:
            out.append({
                "severity": "suggestion", "cat": "函数质量", "file": mf.rel,
                "line": f.line, "symbol": name,
                "msg": "`%s` 长度 %d 行，超过建议的 %d 行" % (name, ln, REVIEW_LIMITS["max_func_lines"]),
                "how": "拆分为更小的局部函数",
            })
        if getattr(f, "complexity", 0) >= REVIEW_LIMITS["high_complexity"]:
            out.append({
                "severity": "warning", "cat": "函数质量", "file": mf.rel,
                "line": f.line, "symbol": name,
                "msg": "`%s` 圈复杂度 %d（≥%d 视为高复杂度）"
                      % (name, f.complexity, REVIEW_LIMITS["high_complexity"]),
                "how": "提取分支逻辑为独立函数，或用查表/状态机替代深层条件",
            })
        # 嵌套深度
        depth, max_depth = 0, 0
        for i in range(f.line, min((end_line or (f.line + 200)), len(src)) + 1):
            if i < 1 or i > len(src):
                continue
            s = src[i - 1]
            opens = len(re.findall(r"\b(if|for|while|switch|try)\b", s))
            closes = len(re.findall(r"\bend\b", s))
            depth += opens - closes
            if depth > max_depth:
                max_depth = depth
        if max_depth > REVIEW_LIMITS["max_nesting"]:
            out.append({
                "severity": "warning", "cat": "函数质量", "file": mf.rel,
                "line": f.line, "symbol": name,
                "msg": "`%s` 嵌套深度达 %d 层，超过建议的 %d 层"
                      % (name, max_depth, REVIEW_LIMITS["max_nesting"]),
                "how": "提前 return / 提取内层逻辑（checkcode 不检测嵌套深度，需人工看）",
            })
        # arguments 块
        body = "\n".join(src[f.line - 1:(end_line or min(f.line + 60, len(src)))])
        if "arguments" not in body and n_in >= 2:
            out.append({
                "severity": "suggestion", "cat": "函数质量", "file": mf.rel,
                "line": f.line, "symbol": name,
                "msg": "`%s` 有多个参数但没有 arguments 块做输入校验" % name,
                "how": "用 arguments 块声明类型与默认值（替代 nargin/varargin）",
            })
        # H1 帮助行（函数签名后第一行注释）
        if f.line < len(src):
            nxt = src[f.line].strip() if f.line < len(src) else ""
            if not nxt.startswith("%"):
                out.append({
                    "severity": "suggestion", "cat": "函数质量", "file": mf.rel,
                    "line": f.line, "symbol": name,
                    "msg": "`%s` 缺少 H1 帮助行（签名后第一行注释）" % name,
                    "how": "补一行 %%FUNCTIONNAME 简述（checkcode 不要求，但官方建议有）",
                })
    return out


def _review_patterns(mf):
    """代码模式检查：废弃/不推荐 API、高危动态执行、硬编码反斜杠路径、循环内数组增长。"""
    out = []
    src = getattr(mf, "source_lines", []) or []
    for i, raw in enumerate(src, 1):
        line = raw.rstrip("\r\n")
        stripped = line.split("%")[0] if not line.strip().startswith("%") else ""
        for old, (new, cat) in MODERNIZE_MAP.items():
            if re.search(r"(?<![A-Za-z0-9_.])" + re.escape(old) + r"\s*\(", stripped):
                sev = "error" if old in ("guide",) else \
                      ("warning" if old in HIGH_RISK_DYNAMIC or
                       old in ("str2num", "clear all") else "suggestion")
                out.append({
                    "severity": sev, "cat": "现代化", "file": mf.rel,
                    "line": i, "symbol": old,
                    "msg": "`%s` 属于%s：建议改用 `%s`" % (old, cat, new),
                    "how": "%s → %s" % (old, new),
                })
        if RE_BACKSLASH_PATH.search(stripped):
            out.append({
                "severity": "warning", "cat": "可移植性", "file": mf.rel,
                "line": i, "symbol": "path",
                "msg": "硬编码的反斜杠路径（Windows 专用写法）",
                "how": "用 fullfile / filesep，或正斜杠（跨平台）",
            })
    return out


# 常见内置函数名（用于「遮蔽内置函数」检查）。MATLAB 内置被同名变量覆盖后，
# 该行之后调用该函数会失败，checkcode 未必报——官方清单明确要求人工看。
_SHADOW_BUILTINS = frozenset("""
sum mean max min abs size length numel zeros ones rand randn find sort round
floor ceil fix mod rem sqrt exp log log10 sin cos tan i j pi inf nan eps
table struct cell plot figure error warning input disp fprintf sprintf
""".split())
RE_MAGIC_NUM = re.compile(
    r"\b(if|while)\b[^\n%]*?(?<![\w.])(\d+(?:\.\d+)?)(?![\w.])"
    r"|\b(\w+)\s*(?:>|>=|<|<=|==|~=)\s*(?<![\w.])(\d+(?:\.\d+)?)(?![\w.])")


def _review_human_only(mf):
    """P271 R6-4：「静态分析查不出」的项目——官方清单明确要求人工复核的部分。

    matlab-review-code 指出 checkcode 不会报：魔数（未命名常量）、
    遮蔽内置函数的变量、深层嵌套、缺失 H1 帮助、硬编码反斜杠路径。
    我们的引擎能自动检测其中大部分，这里归拢为独立类别，
    在页面上明确提示「这些必须人工确认」，避免误以为自动检查已覆盖全部。
    """
    out = []
    src = getattr(mf, "source_lines", []) or []
    for i, raw in enumerate(src, 1):
        line = raw.rstrip("\r\n")
        stripped = line.split("%")[0] if not line.strip().startswith("%") else ""
        if not stripped.strip():
            continue
        # ① 魔数：条件判断里出现的裸数字（0/1/-1 等惯用值除外）
        for m in RE_MAGIC_NUM.finditer(stripped):
            num = m.group(2) or m.group(4) or ""
            if not num:
                continue
            try:
                v = float(num)
            except ValueError:
                continue
            if v in (0.0, 1.0, -1.0, 2.0, 0.5):
                continue
            out.append({
                "severity": "suggestion", "cat": "需人工复核", "file": mf.rel,
                "line": i, "symbol": num,
                "msg": "魔数 `%s` 出现在条件判断中，含义不明" % num,
                "how": "提取为具名常量（如 MAX_ITERATIONS）或加注释说明；"
                       "checkcode 不检测魔数",
            })
            break       # 每行最多报一次，避免刷屏
        # ② 遮蔽内置函数：把内置函数名当作变量赋值
        m2 = re.match(r"\s*([A-Za-z]\w*)\s*=\s*[^=]", stripped)
        if m2 and m2.group(1) in _SHADOW_BUILTINS:
            out.append({
                "severity": "warning", "cat": "需人工复核", "file": mf.rel,
                "line": i, "symbol": m2.group(1),
                "msg": "变量 `%s` 与 MATLAB 内置函数同名，会遮蔽该内置函数"
                       % m2.group(1),
                "how": "改用一个不含内置名的变量名（checkcode 可能不报）",
            })
    return out


def _review_file(mf, calls_of=None, callers_of=None):
    """对单个文件跑完整审查清单，返回按严重度可排序的发现列表。"""
    out = []
    out.extend(_review_naming(mf))
    out.extend(_review_function_quality(mf, calls_of, callers_of))
    out.extend(_review_patterns(mf))
    out.extend(_review_human_only(mf))
    # 稳定排序：严重度高者优先，其次按行号
    order = {"error": 0, "warning": 1, "suggestion": 2}
    out.sort(key=lambda x: (order.get(x["severity"], 3), x.get("line", 0)))
    return out


def _review_project(files, calls_of=None, callers_of=None):
    """对整个工程跑审查清单，返回 (findings, per_file, summary)。"""
    findings, per_file = [], {}
    for mf in files:
        fs = _review_file(mf, calls_of, callers_of)
        per_file[mf.rel] = fs
        findings.extend(fs)
    summary = {"error": 0, "warning": 0, "suggestion": 0}
    for f in findings:
        summary[f["severity"]] = summary.get(f["severity"], 0) + 1
    return findings, per_file, summary


def _compliance_score(summary):
    """合规得分（0-100）：按官方严重度加权扣分（error 最重）。

    权重沿用官方「errors > warnings > suggestions」的优先级：
    每个 error 扣 8 分、warning 扣 3 分、suggestion 扣 1 分，下限 0。
    """
    pen = summary.get("error", 0) * 8 + summary.get("warning", 0) * 3 \
        + summary.get("suggestion", 0) * 1
    return max(0, 100 - pen)


def render_compliance_page(files, findings, per_file, summary, fan_in=None, fan_trans=None):
    """P271 R6-2：生成「代码审查工作台」总览页 compliance.html。

    把静态浏览站点升级为审查工作台的第一入口：给出工程合规得分、
    按官方严重度（error > warning > suggestion）分组的发现，
    以及按文件下钻的清单——让人一眼知道「先改哪里」。
    """
    score = _compliance_score(summary)
    if score >= 90:
        grade, gcls = "良好", "ok"
    elif score >= 70:
        grade, gcls = "待改进", "warn"
    else:
        grade, gcls = "需重点整改", "bad"

    lines = []
    A = lines.append
    A("<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">")
    A("<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">")
    A("<title>代码审查工作台</title>")
    A('<link rel="stylesheet" href="src/styles.css">')
    A("</head><body>")
    A('<a class="skip-link" href="#main">跳到主内容</a>')
    A('<header><span class="brand">代码审查工作台</span>'
      '<a href="index.html">← 返回索引</a></header>')
    A('<main id="main">')
    A("<h1>代码审查工作台</h1>")
    A("<div class=\"muted\">依据 MathWorks 官方审查标准"
      "（matlab-agentic-toolkit 的 matlab-review-code / matlab-modernize-code）："
      "命名约定、函数质量、代码模式、高危项。严重度沿用官方三级："
      "<b>error（必须改）</b> &gt; <b>warning（应该改）</b> &gt; <b>suggestion（可改）</b>。</div>")

    # 得分卡
    A("<div class=\"cmp-score cmp-%s\">" % gcls)
    A("<div class=\"cmp-score-num\">%d</div>" % score)
    A("<div class=\"cmp-score-meta\"><div class=\"cmp-grade\">%s</div>" % grade)
    A("<div class=\"muted\">合规得分（满分 100）</div></div>")
    A("</div>")

    # 严重度统计
    A("<div class=\"cmp-cards\">")
    for sev, label in (("error", "必须改"), ("warning", "应该改"),
                       ("suggestion", "可改")):
        A("<div class=\"cmp-card cmp-%s\"><div class=\"cmp-card-n\">%d</div>"
          "<div class=\"cmp-card-l\">%s</div></div>"
          % (sev, summary.get(sev, 0), label))
    A("</div>")

    # P-rev S6：智能引导——「下一步该改什么」。基于官方严重度与（能拿到的）影响面，
    # 给出可点击优先顺序；每条展开「为什么」即为官方标准依据，让审查结论可溯源。
    SEV_W = {"error": 100, "warning": 40, "suggestion": 10}
    # 官方标准依据（matlab-agentic-toolkit 审查清单的可读摘录）
    RULE_REF = {
        "命名约定": "官方命名要求：函数名应为小写、用下划线分隔（snake_case），变量名应描述用途、避免泛化命名。",
        "函数质量": "官方要求函数「单一职责、可测试、参数少、无副作用」；长函数应拆分，避免嵌套过深。",
        "代码模式": "官方推荐向量化、预分配、用函数句柄/table/tiledlayout 等现代写法，避免低效/过时模式。",
        "高危": "官方将「清除变量/关闭图窗/硬编码路径/clear all」列为高危，要求限定作用域、显式管理资源。",
        "需人工复核": "官方明确 checkcode 查不出，必须人工确认（如 subplot 是否该替换、containers.Map 是否该改 dictionary）。",
    }
    def _prio(f):
        return SEV_W.get(f["severity"], 0)
    # P-rev R8/R14：按「行号 → 影响面」构建映射。R14 升级为传递闭包——若改 X，
    # 其全部下游（传递被依赖者）都会被影响，用传递规模作为主导权重。
    if fan_in is None:
        fan_in = {}
    if fan_trans is None:
        fan_trans = {}
    _line_fan = {}
    _line_trans = {}
    for _mf in files:
        for _f in _mf.functions:
            _k = "%s::%s" % (_mf.rel, _f.name)
            _line_fan[(_mf.rel, _f.line)] = fan_in.get(_k, 0)
            _line_trans[(_mf.rel, _f.line)] = fan_trans.get(_k, 0)
    def _impact(f):
        return _line_trans.get((f["file"], f.get("line", 0)),
                               _line_fan.get((f["file"], f.get("line", 0)), 0))
    def _prio2(f):
        _base = SEV_W.get(f["severity"], 0)
        _imp = _impact(f)
        return _base + _imp * 8   # 每多一处传递受影响，权重 +8，突出「改动波及广」项
    if findings:
        ordered = sorted(findings, key=lambda f: (-_prio2(f), f["cat"]))
        top = ordered[: min(8, len(ordered))]
        A("<h2>下一步建议（按影响优先）</h2>")
        A("<div class=\"cmp-note\">按「官方严重度 + 传递影响面（改了会波及多少下游函数）」"
          "综合排序，先处理「必须改且改动波及广」的项。点击任意项直达源码。</div>")
        A("<ol class=\"guide-ol\">")
        for i, f in enumerate(top, 1):
            href = f["file"].replace("\\", "/")
            if not href.endswith(".html"):
                href = "src/%s.html" % href
            ref = RULE_REF.get(f["cat"], RULE_REF.get("代码模式"))
            A("<li class=\"guide-li\">"
              "<a class=\"guide-go\" href=\"%s#L%d\">%s · %s:%d</a>"
              "<span class=\"guide-sev guide-%s\">%s</span>"
              "<span class=\"guide-imp\" title=\"改了此函数会波及的下游函数数\">波及 %d 处</span>"
              "<details class=\"guide-why\"><summary>为什么？</summary>"
              "<div class=\"guide-ref\">%s</div>"
              "</details>"
              "</li>"
              % (html_mod.escape(href), f.get("line", 0),
                 html_mod.escape(f["cat"]), html_mod.escape(f["file"]), f.get("line", 0),
                 f["severity"], f["severity"], _impact(f), html_mod.escape(ref)))
        A("</ol>")

    # 发现清单（按严重度分组）
    A("<h2>发现清单</h2>")
    if not findings:
        A("<div class=\"cmp-empty\">未发现违反官方审查标准的问题。</div>")
    else:
        for sev, label in (("error", "必须改（error）"),
                           ("warning", "应该改（warning）"),
                           ("suggestion", "可改（suggestion）")):
            group = [f for f in findings if f["severity"] == sev]
            if not group:
                continue
            A("<h3 class=\"cmp-h cmp-%s\">%s · %d</h3>" % (sev, label, len(group)))
            A("<table class=\"cmp-tbl\"><thead><tr>"
              "<th>类别</th><th>文件</th><th>行</th><th>问题</th><th>怎么改</th>"
              "</tr></thead><tbody>")
            for f in group:
                href = f["file"].replace("\\", "/")
                if not href.endswith(".html"):
                    # 源码页保留 .m：src/foo.m.html
                    href = "src/%s.html" % href
                A("<tr><td>%s</td>"
                  "<td><a href=\"%s#L%d\">%s</a></td>"
                  "<td>%d</td><td>%s</td><td class=\"cmp-how\">%s</td></tr>"
                  % (html_mod.escape(f["cat"]),
                     html_mod.escape(href), f.get("line", 0),
                     html_mod.escape(f["file"]), f.get("line", 0),
                     html_mod.escape(f["msg"]), html_mod.escape(f.get("how", ""))))
            A("</tbody></table>")

    # P271 R6-4：「静态分析查不出」的项目 —— 官方明确要求人工复核
    human = [f for f in findings if f["cat"] == "需人工复核"]
    A("<h2>需要人工复核</h2>")
    A("<div class=\"cmp-note\">以下项目 <b>MATLAB 的 checkcode / Code Analyzer"
      " 不会报</b>，官方审查清单明确要求人工确认。本工具已尽力自动检出，"
      "但仍建议逐条核对——不要因为「自动检查没报」就认为没问题。</div>")
    if not human:
        A("<div class=\"cmp-empty\">未自动检出需要人工复核的项目。</div>")
    else:
        A("<table class=\"cmp-tbl\"><thead><tr>"
          "<th>文件</th><th>行</th><th>项目</th><th>说明</th>"
          "</tr></thead><tbody>")
        for f in human:
            A("<tr><td><a href=\"src/%s.html#L%d\">%s</a></td><td>%d</td>"
              "<td>%s</td><td>%s</td></tr>"
              % (html_mod.escape(f["file"]), f.get("line", 0),
                 html_mod.escape(f["file"]), f.get("line", 0),
                 html_mod.escape(f.get("symbol", "")),
                 html_mod.escape(f["msg"])))
        A("</tbody></table>")
    A("<div class=\"cmp-note\">官方列出的「checkcode 查不出」还包括："
      "<code>subplot</code> 用法（官方说明它<b>并未废弃</b>，只是新代码推荐 "
      "tiledlayout/nexttile，不要盲目替换）、<code>containers.Map</code>"
      "（建议改 dictionary，但 checkcode 完全不报）。</div>")

    # 按文件下钻
    A("<h2>按文件分布</h2>")
    A("<table class=\"cmp-tbl\"><thead><tr>"
      "<th>文件</th><th>必须改</th><th>应该改</th><th>可改</th><th>合计</th>"
      "</tr></thead><tbody>")
    rows = []
    for mf in files:
        fs = per_file.get(mf.rel, [])
        if not fs:
            continue
        c = {"error": 0, "warning": 0, "suggestion": 0}
        for f in fs:
            c[f["severity"]] = c.get(f["severity"], 0) + 1
        rows.append((mf.rel, c, len(fs)))
    rows.sort(key=lambda r: (-r[1]["error"], -r[1]["warning"], -r[2]))
    for rel, c, tot in rows:
        A("<tr><td><a href=\"src/%s.html\">%s</a></td><td>%d</td><td>%d</td>"
          "<td>%d</td><td><b>%d</b></td></tr>"
          % (html_mod.escape(rel), html_mod.escape(rel),
             c["error"], c["warning"], c["suggestion"], tot))
    A("</tbody></table>")
    # P-rev S2/S4/R22：审查页也接入跨页联动 + 个人工作台 + 符号层
    A('<script defer src="src/_symbols.js"></script>')
    A('<script defer src="src/_ctxlink.js"></script>')
    A('<script defer src="src/_workbench.js"></script>')
    A('<script>document.addEventListener("DOMContentLoaded",function(){'
      'if(window.WB){WB.ensure();WB.recent();'
      'var h=document.querySelector("header");'
      'if(h){var b=document.createElement("button");b.className="ug-btn";'
      'b.textContent="⭐ 收藏本页";b.onclick=function(){WB.favor(location.pathname);'
      'WB.render();alert("已加入收藏（见右下角🧰工作台）");};h.appendChild(b);}}});</script>')
    A("</main></body></html>")
    return "\n".join(lines)


def _collect_dir_metrics(files):
    """C3：收集目录级复杂度/耦合度指标（按目录聚合文件复杂度）。

    返回 [{dir, complexity, n_files, n_funcs}]，按复杂度降序。"""
    agg = defaultdict(lambda: {"complexity": 0, "n_files": 0, "n_funcs": 0})
    for mf in files:
        d = mf.rel.rsplit("/", 1)[0] if "/" in mf.rel else "."
        n_funcs = sum(1 for f in mf.functions if f.kind != "script")
        agg[d]["complexity"] += sum(f.complexity for f in mf.functions if f.kind != "script")
        agg[d]["n_files"] += 1
        agg[d]["n_funcs"] += n_funcs
    out = [{"dir": d, "complexity": v["complexity"],
            "n_files": v["n_files"], "n_funcs": v["n_funcs"]}
           for d, v in agg.items()]
    out.sort(key=lambda x: -x["complexity"])
    return out


def render_complexity_heatmap(files):
    """C3：生成「复杂度热力总览」页面（complexity.html，--browse 模式专用）。

    文件复杂度热力图（按总复杂度降序 + 颜色编码）+ 目录复杂度汇总，
    让用户在首页一眼看到复杂度/耦合热点。"""
    file_metrics = _collect_file_metrics(files)
    dir_metrics = _collect_dir_metrics(files)
    lines = []
    A = lines.append
    A("<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
      "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">")
    A("<title>复杂度热力总览</title>")
    A('<link rel="stylesheet" href="src/styles.css">')
    A("</head><body>")
