    for fm in file_metrics:
        # 复杂度归一化为颜色深浅（0~255）
        intensity = int(255 * fm["complexity"] / max_cx) if max_cx else 0
        bg = "#%02x%02x%02x" % (255, 255 - intensity // 2, 255 - intensity // 2)
