def _collect_members(files):
    """B1：收集全部类的成员（属性/事件/枚举/方法），用于全局成员索引。

    返回 [{name, file, line, superclasses, properties, events, enumerations, methods}]，
    按类名稳定排序。"""
    classes = []
    for mf in files:
        for cls in mf.classes:
            classes.append({
                "name": cls.name,
                "file": mf.rel,
                "line": cls.line,
                "superclasses": list(cls.superclasses),
                "properties": [(n, l) for (n, l) in cls.properties],
                "events": [(n, l) for (n, l) in cls.events],
                "enumerations": [(n, l) for (n, l) in cls.enumerations],
                "methods": [(m.name, m.line) for m in cls.methods],
            })
    classes.sort(key=lambda c: c["name"])
    return classes


def render_members_page(files):
    """B1：生成「全局成员索引（Member Index）」页面（--browse 模式专用），
    doxygen 风格复合索引——跨文件聚合全部类的属性/事件/枚举/方法，可跳转源码行。"""
    members = _collect_members(files)
    lines = []
    A = lines.append
    A("<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
      "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">")
    A("<title>成员索引（Member Index）</title>")
    A('<link rel="stylesheet" href="src/styles.css">')
    A("</head><body>")
    A('<a class="skip-link" href="#main-content">跳到主内容</a>')
    A("<header><span class=\"brand\">成员索引</span>"
      "<a href=\"index.html\">&larr; 返回索引</a></header>")
    A("<main id=\"main-content\">")
    A("<h1>成员索引（Member Index）</h1>")
    if not members:
        A("<div class=\"muted\">项目内未发现 classdef 类定义。</div>")
        A("</main></body></html>")
        return "\n".join(lines)
    n_prop = sum(len(c["properties"]) for c in members)
    n_ev = sum(len(c["events"]) for c in members)
    n_enum = sum(len(c["enumerations"]) for c in members)
    n_meth = sum(len(c["methods"]) for c in members)
    A("<div class=\"muted\">跨文件聚合全部类的成员：<b>%d</b> 个类 · 属性 %d · 事件 %d · "
      "枚举 %d · 方法 %d。点击成员名跳转到源码定义行。</div>"
      % (len(members), n_prop, n_ev, n_enum, n_meth))
    for c in members:
        href = _src_href_from_rel(c["file"])
        A("<h2><a href=\"%s#L%d\"><code>%s</code></a> <span class=\"muted\">%s</span></h2>"
          % (href, c["line"], html_mod.escape(c["name"]), html_mod.escape(c["file"])))
        if c["superclasses"]:
            A("<div class=\"muted\">继承：%s</div>"
              % html_mod.escape(" & ".join(c["superclasses"])))
        # 成员表格：类型 | 成员名 | 行号
        rows = []
        for kind_label, items in (("属性", c["properties"]),
                                  ("事件", c["events"]),
                                  ("枚举", c["enumerations"]),
                                  ("方法", c["methods"])):
            for name, ln in items:
                rows.append((kind_label, name, ln))
        if rows:
            A("<table><tr><th>类型</th><th>成员</th><th>行</th></tr>")
            for kind_label, name, ln in rows:
                A("<tr><td><span class=\"chip\">%s</span></td>"
                  "<td><a href=\"%s#L%d\"><code>%s</code></a></td>"
                  "<td class=\"num\">%d</td></tr>"
                  % (html_mod.escape(kind_label), href, ln,
                     html_mod.escape(name), ln))
            A("</table>")
    A("</main></body></html>")
    return "\n".join(lines)


