def render_dir_coupling_matrix(files, calls_of):
    """P82：生成「目录耦合度矩阵」页面（dir_matrix.html，--browse 模式专用）。

    doxygen 只有目录的树形文件列表，没有「目录 × 目录」的耦合强度视图。
    本页把全部跨目录调用边聚合成二维矩阵：行 = 源目录（扇出）、列 = 目标
    目录（扇入），单元格颜色深浅表示耦合强度，点击单元格可下钻到具体调用
    明细；双向耦合（A→B 且 B→A）的目录对以红色边框高亮并单独列出。
    """
    data = _compute_dir_coupling(files, calls_of)
    dirs = data["dirs"]
    cells = data["cells"]
    cycles = data["cycles"]
    max_count = data["max"] or 1
    lines = []
    A = lines.append
    A("<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
      "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">")
    A("<title>目录耦合度矩阵</title>")
    A('<link rel="stylesheet" href="src/styles.css">')
    A("""<link rel="stylesheet" href="dm.css">""")
    A("</head><body>")
    A('<a class="skip-link" href="#main-content">跳到主内容</a>')
    A("<header><span class=\"brand\">目录耦合度矩阵</span>"
      "<a href=\"index.html\">&larr; 返回索引</a></header>")
    A("<main id=\"main-content\">")
    A("<h1>目录耦合度矩阵</h1>")
    if not dirs:
        A("<div class=\"muted\">项目内未发现目录间调用关系。</div>")
        A("</main></body></html>")
        return "\n".join(lines)
    # 扇出（每行源目录的跨目录调用数）/ 扇入（每列目标目录被调用数）
    fan_out = {}
    fan_in = {}
    for (src, dst), info in cells.items():
        fan_out[src] = fan_out.get(src, 0) + info["count"]
        fan_in[dst] = fan_in.get(dst, 0) + info["count"]
    cyc_set = set()
    for a, b in cycles:
        cyc_set.add(a)
        cyc_set.add(b)
    A("<div class=\"muted\">共 <b>%d</b> 个目录、<b>%d</b> 条跨目录调用边。"
      "行 = 源目录（扇出），列 = 目标目录（扇入），颜色越深耦合越强。"
      "点击单元格查看具体调用明细；红色边框表示存在双向耦合（循环依赖风险）。</div>"
      % (len(dirs), data["total"]))
    # 循环依赖警告
    if cycles:
        A("<div class=\"dm-cycles\"><b>⚠ 双向耦合目录（%d 对）</b>："
          % len(cycles))
        A("，".join("<code>%s</code> ⇄ <code>%s</code>" % (html_mod.escape(a), html_mod.escape(b))
                    for a, b in cycles))
        A("</div>")
    A("<div class=\"dm-toolbar\">"
      "<input id=\"dm-filter\" placeholder=\"过滤目录名…\" />"
      "<label><input type=\"checkbox\" id=\"dm-only-coup\" /> 仅看有耦合的目录</label>"
      "<button id=\"dm-reset\">复位</button>"
      "<span class=\"dm-count\" id=\"dm-visible\"></span>"
      "</div>")
    A("<div class=\"dm-legend\"><span class=\"sw\" style=\"background:rgba(9,105,218,0.10)\"></span>弱 "
      "<span class=\"sw\" style=\"background:rgba(9,105,218,0.45)\"></span>中 "
      "<span class=\"sw\" style=\"background:rgba(9,105,218,0.92)\"></span>强</div>")
    A("<div class=\"dm-wrap\"><table id=\"dm-table\">")
    # 表头：第一列目录名 + 扇出列 + 每个目标目录
    A("<thead><tr><th>源 \\ 目标</th><th>扇出</th>")
    for d in dirs:
        cls = " class=\"dm-col dm-cycle-col\"" if d in cyc_set else " class=\"dm-col\""
        A("<th%s title=\"%s\">%s</th>" % (cls, html_mod.escape(d), html_mod.escape(d)))
    A("</tr></thead>")
    # 表体：每行一个源目录
    js_cells = []
    A("<tbody>")
    for src in dirs:
        row_cycle = src in cyc_set
        tr_cls = " class=\"dm-cycle\"" if row_cycle else ""
        A("<tr%s data-dir=\"%s\" data-coup=\"%s\">"
          % (tr_cls, html_mod.escape(src), "1" if fan_out.get(src) else "0"))
        A("<td class=\"dm-dir\">%s</td>" % html_mod.escape(src))
        A("<td class=\"dm-stat\">%d</td>" % fan_out.get(src, 0))
        for dst in dirs:
            info = cells.get((src, dst))
            if info is None:
                A("<td class=\"dm-stat\">·</td>")
                continue
            alpha = 0.10 + 0.82 * (float(info["count"]) / max_count)
            key = src + "\x00" + dst
            js_cells.append(
                "[\"%s\",\"%s\",%d,[%s]]" % (
                    _json_js_esc(src), _json_js_esc(dst), info["count"],
                    ",".join("[\"%s\",\"%s\"]" % (_json_js_esc(c["caller"]),
                                                 _json_js_esc(c["callee"]))
                             for c in info["calls"])))
            cell_cls = "dm-cycle-col" if dst in cyc_set else ""
            A("<td class=\"dm-cell %s\" data-src=\"%s\" data-dst=\"%s\" "
              "title=\"%s → %s：%d 条调用\">%d</td>"
              % (cell_cls, html_mod.escape(src), html_mod.escape(dst),
                 html_mod.escape(src), html_mod.escape(dst), info["count"],
                 info["count"]))
        A("</tr>")
    A("</tbody></table></div>")
    # 扇入合计行
    A("<div class=\"muted\">扇入合计：")
    A("，".join("%s = %d" % (html_mod.escape(d), fan_in.get(d, 0)) for d in dirs
                if fan_in.get(d, 0)))
    A("</div>")
    A("<div id=\"dm-detail\"><span class=\"muted\">点击矩阵中的数字查看调用明细…</span></div>")
    A("</main>")
    A("<script>window.__DMData__={cells:{")
    if js_cells:
        A(",".join("\"%s\\u0000%s\":{%s}" % (
            _json_js_esc(src), _json_js_esc(dst),
            "calls:[%s]" % ",".join(
                "[\"%s\",\"%s\"]" % (_json_js_esc(c["caller"]), _json_js_esc(c["callee"]))
                for c in cells.get((src, dst), {}).get("calls", [])))
            for src, dst in cells))
    A("},cycles:[%s]};</script>" % ",".join(
        "[\"%s\",\"%s\"]" % (_json_js_esc(a), _json_js_esc(b)) for a, b in cycles))
    A("<script>%s</script>" % DIRMATRIX_JS)
    # P223：复用 HTML 尾模板
    A("</body>" + _html_foot())
    return "\n".join(lines)


import re  # R41-R60：内置函数维度传播引擎依赖


# ===================== R41-R60：内置函数「实际维度」传播引擎 =====================
# 目标：把"按函数名查固定维度文案"升级为"根据源码词法分析 + 数据流推导每个调用处
# 的实际维度"。沿赋值（B=A; C=B+1 → C 与 A 同形）、运算、索引、内置形状规则逐行推导，
# 在每个 .tk-builtin 调用处注入 data-dim，前端据此展示"实参/返回的实际维度"。

def _shp(*dims):
    """构造形状元组：int → 已知常量维，None → 未知维。空元组表示标量。"""
    return tuple(('c', d) if isinstance(d, int) else ('u',) for d in dims)


def _shp_str(shp):
    if shp is None:
        return '?'
    if not shp:
        return '标量'
    # 形状可能来自 _es_eval 的任意标记：正常为 [('c',n)/('u',)], 但特殊结构体
    # 标记（如 ('struct',)）或意外标量/字符串会破坏逐维下标访问，这里统一防御，
    # 避免 IndexError 使整个报告生成崩溃（P224-Y）。
    if isinstance(shp, str):
        return shp
    try:
        _dims = list(shp)
    except TypeError:
        return str(shp)
    out = []
    for d in _dims:
        if isinstance(d, str):
            out.append(d)
            continue
        try:
            _tag = d[0]
        except (TypeError, IndexError):
            out.append(str(d))
            continue
        if _tag == 'c':
            try:
                out.append(str(d[1]))
            except (TypeError, IndexError):
                out.append('?')
        elif _tag == 'u':
            out.append('?')
        elif _tag == 'struct':
            out.append('结构体')
        else:
            try:
                out.append('size(%s,%d)' % (d[1], d[2]))
            except (TypeError, IndexError):
                out.append('?')
    return '×'.join(out)


def _shp_transpose(shp):
    if shp is None:
        return None
    if len(shp) >= 2:
        return tuple(reversed(shp))
    return shp


def _shp_elem(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if not a:
        return b
    if not b:
        return a
    if len(a) != len(b):
        return a if len(a) >= len(b) else b
    res = []
    for x, y in zip(a, b):
        if x[0] == 'c' and x[1] == 1:
            res.append(y)
        elif y[0] == 'c' and y[1] == 1:
            res.append(x)
        else:
            res.append(x if x[0] == 'c' else y)
    return tuple(res)


def _dim_eq(x, y):
    if x[0] == 'u' or y[0] == 'u':
        return True
    return x[0] == 'c' and y[0] == 'c' and x[1] == y[1]


def _shp_matmul(a, b, op):
    if a is None:
        return b
    if b is None:
        return a
    if not a:
        return b
    if not b:
        return a
    if op == '*':
        if len(a) >= 2 and len(b) >= 2 and _dim_eq(a[1], b[0]):
            return (a[0], b[1])
        return _shp_elem(a, b)
    if op == '/':
        return _shp_elem(a, b)
    if op == '\\':
        return _shp_elem(b, a)
    return _shp_elem(a, b)


def _const_dim(shp):
    if shp is None:
        return None
    if len(shp) == 1 and shp[0][0] == 'c':
        return shp[0][1]
    return None


def _mul_dim(d, k):
    return ('c', d[1] * k) if d[0] == 'c' else ('u',)


def _add_dim(x, y):
    if x[0] == 'c' and y[0] == 'c':
        return ('c', x[1] + y[1])
    return ('u',)


def _lit_dim(runs):
    """把尺寸参数表达式解析为维度原子：字面量数字 → ('c',n)，否则未知。
    P204：支持十六进制 0x1F / 二进制 0b1010 字面量；忽略空白 token。"""
    runs = [r for r in runs if r[1] != 'ws']
    if len(runs) == 1 and runs[0][1] == 'number':
        txt = runs[0][0].lower()
        try:
            if txt.startswith('0x'):
                return ('c', int(txt, 16))
            if txt.startswith('0b'):
                return ('c', int(txt, 2))
            return ('c', int(float(txt)))
        except Exception:
            return ('u',)
    return ('u',)


def _idx_vector_len(runs):
    """解析形如 [1 2 3] / [1,2,3] 的向量下标，返回元素个数；
    含区间(:) 或变量则无法静态求长，返回 None。"""
    if not runs or runs[0][0] != '[':
        return None
    cnt = 0
    depth = 0
    for t in runs:
        if t[0] == '[':
            if depth == 0:
                depth = 1
                continue
            depth += 1
            continue
        if t[0] == ']':
            depth -= 1
            continue
        if depth != 1:
            continue
        if t[0] == ':':
            return None  # 含区间，长度无法静态确定
        if t[1] == 'number':
            cnt += 1
            continue
        if t[1] in ('ident', 'builtin'):
            return None
    return cnt if cnt > 0 else None


def _colon_count_at(T, start):
    """扫描形如 a:b 或 a:s:b 的整数/小数字面量，返回元素个数；非字面量则返回 None。"""
    j = start
    nums = []
    seen_colon = False
    while j < len(T):
        t = T[j]
        if t[1] == 'number':
            nums.append(float(t[0]))
        elif t[0] == ':' and nums:
            seen_colon = True
        else:
            break
        j += 1
    if not seen_colon or len(nums) < 2:
        return None
    try:
        if len(nums) == 2:
            a, b = nums
            return int(round(b - a)) + 1 if b >= a else 0
        a, s, b = nums[0], nums[1], nums[-1]
        if s == 0:
            return 0
        import math as _m
        return int(_m.floor((b - a) / s)) + 1
    except Exception:
        return None


def _idx_kind(runs):
    """下标表达式类型：冒号(:) / 区间(a:b) / 向量([1 2 3]) / 标量(塌缩)。"""
    if len(runs) == 1 and runs[0][0] == ':':
        return ('colon',)
    cols = [i for i, t in enumerate(runs) if t[0] == ':']
    if len(cols) == 1:
        lo = _lit_dim(runs[:cols[0]])
        hi = _lit_dim(runs[cols[0] + 1:])
        lo_n = lo[1] if lo[0] == 'c' else None
        hi_n = hi[1] if hi[0] == 'c' else None
        return ('range', lo_n, hi_n)
    if runs and runs[0][0] == '[':
        L = _idx_vector_len(runs)
        if L is not None:
            return ('vector', L)
    return ('scalar',)


def _shp_index(base, args):
    if base is None:
        return None
    single = (len(args) == 1)
    if single:
        k0 = _idx_kind(args[0])
        # A(:) 单冒号线性化 → 按列拉直的列向量
        if k0[0] == 'colon':
            if len(base) <= 1:
                return base
            if all(d[0] == 'c' for d in base):
                N = 1
                for d in base:
                    N *= d[1]
                return (('c', N), ('c', 1))
            return (('u',), ('c', 1))
        # A([1 2 3]) 单向量下标（线性索引）→ 列向量 L×1
        if k0[0] == 'vector':
            L = k0[1]
            return (('c', L), ('c', 1)) if L else (('u',), ('c', 1))
    res = []
    axis = 1
    for idxruns in args:
        k = _idx_kind(idxruns)
        if k[0] == 'colon':
            res.append(base[axis - 1] if axis - 1 < len(base) else ('u',))
        elif k[0] == 'range':
            res.append(('c', max(0, k[2] - k[1] + 1)) if (k[1] is not None and k[2] is not None) else ('u',))
        elif k[0] == 'vector':
            L = k[1]
            res.append(('c', L) if L is not None else ('u',))
        # scalar 下标（含 end）→ 该维塌缩，不加入结果
        axis += 1
    if single and not res:
        return _shp()  # 单下标线性索引 → 标量
    if not res:
        return _shp()
    return tuple(res)


def _concat_shp(a, b, vertical=False):
    if a is None:
        return b
    if b is None:
        return a
    if not a:
        return b
    if not b:
        return a
    if len(a) != len(b):
        return _shp_elem(a, b)
    if vertical:
        return (_add_dim(a[0], b[0]),) + a[1:]
    return a[:-1] + (_add_dim(a[-1], b[-1]),)


# P220：扩展内置形状库——数值/线性代数/信号处理类（依据 MATLAB 文档的形状语义）。
def _len_of(shp):
    """取形状最后一个可确定的常量维长度（向量/矩阵均适用）。"""
    if not shp:
        return None
    for d in reversed(shp):
        if d[0] == 'c':
            return d[1]
    return None


def _EXTRA_BUILTIN_SHAPE_fn_poly(arg_shapes, arg_runs, env):
    n = _len_of(arg_shapes[0]) if arg_shapes else None
    return _shp(1, n + 1) if n is not None else _shp(('u',), ('u',))


def _EXTRA_BUILTIN_SHAPE_fn_roots(arg_shapes, arg_runs, env):
    n = _len_of(arg_shapes[0]) if arg_shapes else None
    return _shp(1, n) if n is not None else _shp(('u',), ('u',))


def _EXTRA_BUILTIN_SHAPE_fn_conv(arg_shapes, arg_runs, env):
    if len(arg_shapes) >= 2:
        x = _len_of(arg_shapes[0]); y = _len_of(arg_shapes[1])
        if x is not None and y is not None:
            return _shp(1, x + y - 1)
    return _shp(('u',), ('u',))


def _EXTRA_BUILTIN_SHAPE_fn_same(arg_shapes, arg_runs, env):
    return arg_shapes[0] if arg_shapes else _shp(('u',), ('u',))


_EXTRA_BUILTIN_SHAPE = {
    'poly': _EXTRA_BUILTIN_SHAPE_fn_poly,
    'roots': _EXTRA_BUILTIN_SHAPE_fn_roots,
    'conv': _EXTRA_BUILTIN_SHAPE_fn_conv,
    'conv2': _EXTRA_BUILTIN_SHAPE_fn_same,
    'cummax': _EXTRA_BUILTIN_SHAPE_fn_same,
    'cummin': _EXTRA_BUILTIN_SHAPE_fn_same,
    'cumsum': _EXTRA_BUILTIN_SHAPE_fn_same,
    'cumprod': _EXTRA_BUILTIN_SHAPE_fn_same,
    'movmean': _EXTRA_BUILTIN_SHAPE_fn_same,
    'movmedian': _EXTRA_BUILTIN_SHAPE_fn_same,
    'normalize': _EXTRA_BUILTIN_SHAPE_fn_same,
    'rescale': _EXTRA_BUILTIN_SHAPE_fn_same,
    'gradient': _EXTRA_BUILTIN_SHAPE_fn_same,
    'trapz': _EXTRA_BUILTIN_SHAPE_fn_same,
    'cumtrapz': _EXTRA_BUILTIN_SHAPE_fn_same,
    'flip': _EXTRA_BUILTIN_SHAPE_fn_same,
    'flipud': _EXTRA_BUILTIN_SHAPE_fn_same,
    'fliplr': _EXTRA_BUILTIN_SHAPE_fn_same,
    'circshift': _EXTRA_BUILTIN_SHAPE_fn_same,
    'shiftdim': _EXTRA_BUILTIN_SHAPE_fn_same,
    'rgb2gray': lambda arg_shapes, arg_runs, env: (arg_shapes[0][:2] if arg_shapes and len(arg_shapes[0]) >= 2 else (('u',), ('u',))),
    'pagectranspose': lambda arg_shapes, arg_runs, env: (tuple(reversed(arg_shapes[0][-2:])) + arg_shapes[0][:-2]) if arg_shapes else (('u',), ('u',)),
    'vecnorm': lambda arg_shapes, arg_runs, env: arg_shapes[0][:1] if arg_shapes and arg_shapes[0] else (('u',), ('u',)),
    'bounds': lambda arg_shapes, arg_runs, env: _shp(2) + (arg_shapes[0][1:] if arg_shapes and len(arg_shapes[0]) > 1 else ()),
    'hankel': lambda arg_shapes, arg_runs, env: (_shp(_len_of(arg_shapes[0]), _len_of(arg_shapes[0])) if arg_shapes and _len_of(arg_shapes[0]) else (('u',), ('u',))) if len(arg_shapes) >= 1 else (('u',), ('u',)),
    'toeplitz': lambda arg_shapes, arg_runs, env: (_shp(_len_of(arg_shapes[0]), _len_of(arg_shapes[0])) if arg_shapes and _len_of(arg_shapes[0]) else (('u',), ('u',))),
    'hilb': lambda arg_shapes, arg_runs, env: (_shp(_len_of(arg_shapes[0]), _len_of(arg_shapes[0])) if arg_shapes and _len_of(arg_shapes[0]) else (('u',), ('u',))),
    'compan': lambda arg_shapes, arg_runs, env: (_shp(_len_of(arg_shapes[0]) - 1, _len_of(arg_shapes[0]) - 1) if arg_shapes and _len_of(arg_shapes[0]) else (('u',), ('u',))),
}


def _builtin_shape(name, arg_shapes, arg_runs, env):
    """依据内置函数的形状规则，由实参形状推导返回形状（失败则透传首参）。

    arg_shapes: 各实参经表达式求值得到的形状元组列表（用于逐元素/矩阵运算）。
    arg_runs:   各实参的原始 token 子列表（用于读取 zeros(3,4) 中的字面量尺寸）。
    """
    a = arg_shapes[0] if arg_shapes else None
    name = name.lower()
    # P220：扩展内置函数形状库（数值/线性代数类）
    if name in _EXTRA_BUILTIN_SHAPE:
        return _EXTRA_BUILTIN_SHAPE[name](arg_shapes, arg_runs, env)
    if name in ('zeros', 'ones', 'nan', 'inf', 'true', 'false', 'rand', 'randn', 'randi'):
        return tuple(_lit_dim(r) for r in arg_runs)
    if name == 'eye':
        if len(arg_runs) == 1:
            d = _lit_dim(arg_runs[0])
            return (d, d)
        if len(arg_runs) >= 2:
            return (_lit_dim(arg_runs[0]), _lit_dim(arg_runs[1]))
        return None
    # diag 规则见下方扩展块（支持向量→方阵、矩阵→对角列向量）
    if name == 'size':
        if len(arg_shapes) == 1:
            if a is None:
                return (('c', 1), ('u',))
            return (('c', 1), ('c', len(a)) if a else ('u',))
        return _shp()  # size(A,dim) → 标量
    if name in ('length', 'numel', 'ndims', 'nnz', 'rank', 'det', 'trace', 'norm'):
        return _shp()
    if name in ('sum', 'mean', 'median', 'std', 'var', 'prod', 'all', 'any'):
        if a is None:
            return None
        if len(a) == 0:
            return _shp()
        if len(arg_runs) >= 2:
            d_atom = _lit_dim(arg_runs[1])
            didx = d_atom[1] if d_atom[0] == 'c' else None
            if didx is not None and 1 <= didx <= len(a):
                lst = list(a)
                lst[didx - 1] = ('c', 1)
                return tuple(lst)
            if arg_runs[1] and arg_runs[1][0][0] == 'string' and arg_runs[1][0][1].strip("'\"") == 'all':
                return _shp()
        return (('c', 1),) + a[1:]
    if name in ('cumsum', 'cumprod', 'gradient', 'fft', 'ifft', 'fft2', 'ifft2', 'fftn',
                'abs', 'sqrt', 'exp', 'log', 'log10', 'sin', 'cos', 'tan', 'conj', 'real', 'imag',
                'angle', 'sign', 'mod', 'rem', 'fix', 'floor', 'ceil', 'round'):
        return a
    if name in ('transpose', 'ctranspose'):
        return _shp_transpose(a)
    if name in ('flip', 'flipud', 'fliplr', 'rot90', 'circshift', 'shiftdim'):
        return a
    if name in ('inv', 'pinv', 'lu'):
        return a
    if name == 'reshape':
        return tuple(_lit_dim(r) for r in arg_runs[1:]) if len(arg_runs) > 1 else a
    if name == 'repmat':
        if len(arg_runs) >= 3 and a is not None and len(a) >= 2:
            m_dim = _lit_dim(arg_runs[1])
            n_dim = _lit_dim(arg_runs[2])
            if m_dim[0] == 'c' and n_dim[0] == 'c':
                return (_mul_dim(a[0], m_dim[1]), _mul_dim(a[1], n_dim[1]))
        return a
    if name == 'cat':
        if a is not None and len(arg_runs) >= 2:
            d_atom = _lit_dim(arg_runs[1])
            dim = d_atom[1] if d_atom[0] == 'c' else 1
            res = a
            for s in arg_shapes[1:]:
                res = _concat_shp(res, s, vertical=(dim == 1))
            return res
        return a
    if name == 'horzcat':
        if a is not None and len(arg_shapes) >= 2:
            res = a
            for s in arg_shapes[1:]:
                res = _concat_shp(res, s, vertical=False)
            return res
        return a
    if name == 'vertcat':
        if a is not None and len(arg_shapes) >= 2:
            res = a
            for s in arg_shapes[1:]:
                res = _concat_shp(res, s, vertical=True)
            return res
        return a
    if name == 'kron':
        b = arg_shapes[1] if len(arg_shapes) >= 2 else None
        if a is not None and b is not None and len(a) == len(b):
            return tuple(_mul_dim(x, y[1]) for x, y in zip(a, b))
        return a
    if name == 'diff':
        if a is None:
            return None
        if len(a) == 0:
            return _shp()
        k = 1
        dim = 1
        if len(arg_runs) >= 2:
            d_atom = _lit_dim(arg_runs[1])
            k = d_atom[1] if d_atom[0] == 'c' else 1
        if len(arg_runs) >= 3:
            d_atom = _lit_dim(arg_runs[2])
            dim = d_atom[1] if d_atom[0] == 'c' else 1
        lst = list(a)
        if 1 <= dim <= len(lst):
            d = lst[dim - 1]
            if d[0] == 'c':
                lst[dim - 1] = ('c', max(0, d[1] - k))
        return tuple(lst)
    if name in ('sort', 'sortrows'):
        return a
    if name in ('linspace', 'logspace'):
        if len(arg_runs) >= 3:
            n_atom = _lit_dim(arg_runs[2])
            if n_atom[0] == 'c':
                return (('c', 1), ('c', n_atom[1]))
        return (('c', 1), ('u',))
    if name == 'squeeze':
        if a is None:
            return None
        return tuple(d for d in a if not (d[0] == 'c' and d[1] == 1)) or _shp()
    if name in ('permute', 'ipermute'):
        return a
    if name == 'repelem':
        if a is not None and len(a) >= 2 and len(arg_runs) >= 2:
            res = list(a)
            for idx in range(min(len(res), len(arg_runs) - 1)):
                d_atom = _lit_dim(arg_runs[idx + 1])
                if d_atom[0] == 'c':
                    res[idx] = _mul_dim(res[idx], d_atom[1])
            return tuple(res)
        return a
    if name in ('unique', 'intersect', 'setdiff', 'union', 'setxor'):
        # 集合运算：返回列向量（长度未知）
        return ('u',)
    if name == 'meshgrid':
        return a
    if name == 'cross':
        return a
    if name in ('bsxfun', 'arrayfun', 'cellfun', 'structfun', 'cell2mat', 'num2cell', 'mat2cell'):
        return a
    if name in ('del2', 'gradient', 'filter', 'filter2'):
        return a
    if name == 'interp1':
        if len(arg_shapes) >= 3 and arg_shapes[2] is not None:
            return arg_shapes[2]
        return a
    if name == 'conv':
        if len(arg_shapes) >= 2:
            x = arg_shapes[0][0] if arg_shapes[0] else None
            y = arg_shapes[1][0] if len(arg_shapes) > 1 and arg_shapes[1] else None
            if x is not None and y is not None and x[0] == 'c' and y[0] == 'c':
                return (('c', x[1] + y[1] - 1),)
        return a
    if name == 'trapz':
        return _shp()
    if name == 'cumtrapz':
        return a
    if name in ('pdist', 'norm', 'trace', 'det', 'rank', 'rcond', 'cond', 'rms'):
        return _shp()
    if name == 'pdist2':
        return a
    if name in ('cov', 'corrcoef'):
        if len(a) >= 2 and a[1][0] == 'c':
            n = a[1][1]
            return (('c', n), ('c', n))
        return a
    if name in ('histcounts', 'histogram', 'hist'):
        return a  # 频数/计数向量
    if name == 'qr' and a is not None and len(a) >= 2:
        n = a[0][1] if a[0][0] == 'c' else None
        return (('c', n), ('c', n)) if n is not None else a
    if name == 'eig' and a is not None and len(a) >= 2:
        n = a[0][1] if a[0][0] == 'c' else None
        return (('c', n),) if n is not None else a
    if name == 'svd' and a is not None and len(a) >= 2:
        m = a[0][1] if a[0][0] == 'c' else None
        nn = a[1][1] if len(a) > 1 and a[1][0] == 'c' else m
        mn = min(m, nn) if (m is not None and nn is not None) else None
        return (('c', mn),) if mn is not None else a
    if name == 'diag':
        if a is None:
            return None
        if len(a) == 0:
            return _shp()
        if len(a) == 1:
            L = a[0][1] if a[0][0] == 'c' else None
            return (('c', L), ('c', L)) if L is not None else (('u',), ('u',))
        singletons = [i for i, d in enumerate(a) if d[0] == 'c' and d[1] == 1]
        nonsingle = [d for i, d in enumerate(a) if i not in singletons]
        if len(singletons) == 1 and len(nonsingle) == 1:
            L = nonsingle[0][1] if nonsingle[0][0] == 'c' else None
            return (('c', L), ('c', L)) if L is not None else (('u',), ('u',))
        if a[0][0] == 'c' and (len(a) < 2 or a[1][0] == 'c'):
            L = min(a[0][1], a[1][1] if len(a) > 1 else a[0][1])
            return (('c', L),)
        return (('u',),)
    if name == 'find':
        return (('u',),)  # 索引向量
    if name in ('max', 'min'):
        # max(A)/min(A)：矩阵按列取极值 → 行向量 1×N；向量 → 标量。
        # max(A,B)/min(A,B)：逐元素 → 形状同 A。
        if len(arg_shapes) >= 2:
            return a
        if a is None:
            return None
        if len(a) <= 1:
            return _shp()
        return (('c', 1),) + a[1:]
    if name in ('sprintf', 'fprintf', 'disp', 'plot', 'figure', 'hold', 'title',
                'xlabel', 'ylabel', 'legend', 'close', 'grid'):
        return None
    return a if a is not None else None


def _multi_out(name, n, args):
    """多返回值解构 [a,b]=f(x) 的各输出形状。"""
    name = name.lower()
    a = args[0] if args else None
    if n <= 0:
        return []
    if name == 'size' and n == 2 and a is not None:
        return [_shp(), _shp()]
    if name == 'eig' and a is not None and len(a) >= 2:
        n = a[0][1] if a[0][0] == 'c' else None
        sz = (('c', n), ('c', n)) if n is not None else (a[0], a[1])
        return [sz, sz]
    if name == 'qr' and a is not None and len(a) >= 2:
        return [(a[0], a[0]), (a[0], a[1])]
    if name == 'lu' and a is not None and len(a) >= 2:
        return [(a[0], a[0]), (a[1], a[1]), (a[0], a[0])]
    if name == 'svd' and a is not None and len(a) >= 2:
        mn = min(_const_dim((a[0],)) or 0, _const_dim((a[1],)) or 0)
        return [(a[0], a[0]), (('c', mn), ('c', mn)), (a[1], a[1])]
    if name in ('max', 'min') and n == 2 and a is not None:
        tail = a[1:] if len(a) > 1 else ()
        return [('c', 1) + tail, ('c', 1) + tail]
    if name == 'sort' and n >= 2 and a is not None:
        return [a] * n
    if name == 'sortrows' and n >= 2 and a is not None:
        return [a] * n
    if name == 'find' and n >= 2:
        return [('u',)] * n
    if name == 'meshgrid' and n >= 2:
        if a is not None and len(a) >= 2:
            return [a] * n  # 矩阵输入 → 各输出同形
        return [(('u',), ('u',))] * n  # 向量输入 → 2D 网格（尺寸未知）
    if name == 'gradient' and n == 2 and a is not None:
        return [a, a]
    return [None] * n


def _es_eval(T, env, member_dims=None):
    """递归下降求表达式形状。T 为 (文本, 类型) token 列表。

    member_dims：可选 {base.field(path): shp}（来自 _compute_member_dims），
    用于把结构体字段访问（如 S.f1）解析为其真实维度，而非保守标量（P223-B/C）。
    """
    if T and isinstance(T[0], tuple) and len(T[0]) == 3 and isinstance(T[0][0], int):
        raise TypeError("_es_eval 需要 (text, kind) 二元组 token，"
                        "而非 (start, end, kind)；请先用 [(line[s:e], k) for s, e, k in toks] 转换")
    try:
        n = len(T)
        pos = [0]

        def peek():
            return T[pos[0]] if pos[0] < n else (None, None)

        def adv():
            t = T[pos[0]]
            pos[0] += 1
            return t

        def p_compare():
            left = p_colon()
            while True:
                tk = peek()
                if tk[0] in ('==', '~=', '<=', '>=', '<', '>', '&&', '||'):
                    adv()
                    p_colon()  # 消耗右操作数，结果形状≈左操作数（逐元素逻辑）
                else:
                    break
            return left

        def p_colon():
            start_pos = pos[0]
            left = p_add()
            while peek() is not None and peek()[0] == ':':
                adv()
                p_add()  # 消耗步长/终点（推进 pos）
                n = _colon_count_at(T, start_pos)
                left = (('c', 1), ('c', n)) if n is not None else (('c', 1), ('u',))
            return left

        def p_add():
            left = p_mul()
            while peek()[0] in ('+', '-', '|', '&'):
                adv()
                right = p_mul()
                left = _shp_elem(left, right)
            return left

        def p_mul():
            left = p_unary()
            while True:
                tk = peek()
                if tk[0] in ('*', '/', '\\', '.*', './', '.\\', '.^', '^'):
                    op = tk[0]
                    adv()
                    right = p_unary()
                    left = _shp_matmul(left, right, op) if op in ('*', '/', '\\') else _shp_elem(left, right)
                else:
                    break
            return left

        def p_unary():
            tk = peek()
            if tk[0] in ('+', '-', '~'):
                adv()
                return p_unary()
            return p_post()

        def p_post():
            node = p_prim()
            while peek()[0] == "'":
                adv()
                node = _shp_transpose(node)
            return node

        def p_prim():
            tk = peek()
            if tk is None:
                return None
            if tk[0] == '(':
                adv()
                inner = p_compare()
                if peek()[0] == ')':
                    adv()
                return inner
            if tk[0] == '[':
                # 拼接：[A,B] 水平（沿末维相加），[A;B] 垂直（沿首维相加）。
                depth = 0
                i = pos[0]
                while i < n:
                    if T[i][0] == '[':
                        depth += 1
                    elif T[i][0] == ']':
                        depth -= 1
                        if depth == 0:
                            break
                    i += 1
                inner = T[pos[0] + 1:i]
                pos[0] = min(i + 1, n)
                # 2D 块拼接：顶层 ; 分行，行内顶层 , 分块；空分隔视为标量占位。
                rows = []
                cur_row = []
                cur_cell = []
                d = 0
                for t in inner:
                    if t[0] == '[':
                        d += 1
                        cur_cell.append(t)
                    elif t[0] == ']':
                        d -= 1
                        cur_cell.append(t)
                    elif d == 0 and t[0] == ';':
                        if cur_cell:
                            cur_row.append(cur_cell)
                        rows.append(cur_row)
                        cur_row = []
                        cur_cell = []
                    elif d == 0 and t[0] == ',':
                        if cur_cell:
                            cur_row.append(cur_cell)
                        cur_cell = []
                    else:
                        cur_cell.append(t)
                if cur_cell:
                    cur_row.append(cur_cell)
                if cur_row:
                    rows.append(cur_row)
                if not rows:
                    return _shp()
                row_shapes = []
                for row in rows:
                    if not row:
                        continue
                    s = _es_eval(row[0], env)
                    for c in row[1:]:
                        s = _concat_shp(s, _es_eval(c, env), vertical=False)
                    row_shapes.append(s)
                if not row_shapes:
                    return _shp()
                res = row_shapes[0]
                for s in row_shapes[1:]:
                    res = _concat_shp(res, s, vertical=True)
                return res
            if tk[1] == 'number':
                adv()
                return _shp()
            if tk[1] == 'string':
                adv()
                return _shp()
            if tk[1] in ('ident', 'builtin'):
                name = tk[0]
                adv()
                if peek()[0] == '(':
                    adv()
                    args = []
                    cur = []
                    depth = 0
                    while pos[0] < n:
                        tt = T[pos[0]]
                        if tt[0] == '(':
                            depth += 1
                            cur.append(tt)
                        elif tt[0] == '[':
                            depth += 1
                            cur.append(tt)
                        elif tt[0] == ')':
                            if depth == 0:
                                if cur:
                                    args.append(cur)
                                pos[0] += 1
                                break
                            depth -= 1
                            cur.append(tt)
                        elif tt[0] == ']':
                            if depth > 0:
                                depth -= 1
                            cur.append(tt)
                        elif tt[0] == ',' and depth == 0:
                            if cur:
                                args.append(cur)
                            cur = []
                        elif tt[0] == ';' and depth == 0:
                            if cur:
                                args.append(cur)
                            cur = []
                        else:
                            cur.append(tt)
                        pos[0] += 1
                    if name in env:  # 视为下标索引
                        return _shp_index(env[name], args)
                    arg_shapes = [_es_eval(a, env) for a in args]
                    return _builtin_shape(name, arg_shapes, args, env)
                if peek()[0] == '.':
                    _path = name
                    while peek()[0] == '.':
                        adv()
                        if peek()[1] in ('ident', 'builtin'):
                            _path = _path + '.' + peek()[0]
                            adv()
                    if member_dims:
                        _mshp = member_dims.get(_path)
                        if _mshp is not None:
                            return _mshp
                    return _shp()  # 字段访问：保守视作标量
                return env.get(name)
            adv()
            return None

        return p_compare()
    except Exception:
        return None


def _collect_args_T(T, i):
    """从 T[i]（函数名）之后收集顶层逗号分隔的参数 token 子列表。"""
    args = []
    cur = []
    depth = 0
    j = i + 1
    if j >= len(T) or T[j][0] != '(':
        return args, j
    j += 1
    while j < len(T):
        t = T[j]
        if t[0] == '(':
            depth += 1
            cur.append(t)
        elif t[0] == '[':
            depth += 1
            cur.append(t)
        elif t[0] == ')':
            if depth == 0:
                if cur:
                    args.append(cur)
                j += 1
                break
            depth -= 1
            cur.append(t)
        elif t[0] == ']':
            if depth > 0:
                depth -= 1
            cur.append(t)
        elif t[0] == ',' and depth == 0:
            if cur:
                args.append(cur)
            cur = []
        elif t[0] == ';' and depth == 0:
            if cur:
                args.append(cur)
            cur = []
        else:
            cur.append(t)
        j += 1
    return args, j


def _record_builtins(T, ln, occ, env, dim_map, member_dims=None):
    i = 0
    while i < len(T):
        if T[i][1] == 'builtin':
            name = T[i][0]
            k = occ.get(name, 0)
            occ[name] = k + 1
            args, _ = _collect_args_T(T, i)
            arg_shapes = [_es_eval(a, env, member_dims) for a in args]
            res = _builtin_shape(name, arg_shapes, args, env)
            dim_map[(ln, name, k)] = {
                'p': [_shp_str(s) for s in arg_shapes],
                'r': _shp_str(res),
                'p_raw': list(arg_shapes),
                'r_raw': res,
                'note': '实际维度由词法分析+数据流推导',
            }
        i += 1


def _strip_inline_comment(raw):
    out = []
    in_str = False
    prev = ''
    i = 0
    L = len(raw)
    while i < L:
        c = raw[i]
        if c == "'":
            in_str = not in_str
            out.append(c)
        elif c == '%' and not in_str and prev != '%' and raw[i:i + 2] not in ('%{', '%%'):
            break
        else:
            out.append(c)
        prev = c
        i += 1
    return ''.join(out)


def _split_statements(code):
    _runs, _ = _tokenize_matlab(code, False)
    runs = [(s, e, kind) for (s, e, kind) in _runs if kind != 'comment']
    parts = []
    cur = []
    depth = 0
    for (s, e, kind) in runs:
        t = code[s:e]
        if t in ('(', '['):
            depth += 1
            cur.append((s, e, kind))
        elif t in (')', ']'):
            depth -= 1
            cur.append((s, e, kind))
        elif t in (';', ',') and depth == 0:
            parts.append(cur)
            cur = []
        else:
            cur.append((s, e, kind))
    if cur:
        parts.append(cur)
    out = []
    for r in parts:
        if not r:
            continue
        out.append(code[r[0][0]:r[-1][1]])
    return out


def _find_assign(T):
    depth = 0
    for i, (t, k) in enumerate(T):
        if t in ('(', '['):
            depth += 1
        elif t in (')', ']'):
            depth -= 1
        elif t == '=' and depth == 0:
            if i > 0 and T[i - 1][0] in ('=', '<', '>', '~'):
                continue
            if i + 1 < len(T) and T[i + 1][0] == '>':
                continue
            return i
    return -1


def _apply_lhs(lhs_T, rhs_shape, rhs_T, env):
    if not lhs_T:
        return
    if len(lhs_T) == 1 and lhs_T[0][1] == 'ident':
        env[lhs_T[0][0]] = rhs_shape
        return
    if lhs_T[0][0] == '[':
        names = []
        depth = 0
        for (t, k) in lhs_T:
            if t == '[':
                depth += 1
            elif t == ']':
                depth -= 1
            elif t in (',', ';') and depth == 1:
                pass
            elif k == 'ident' and depth == 1:
                names.append(t)
        names = [x for x in names if x]
        if rhs_T and rhs_T[0][1] in ('ident', 'builtin') and len(rhs_T) > 1 and rhs_T[1][0] == '(':
            fname = rhs_T[0][0]
            args, _ = _collect_args_T(rhs_T, 0)
            arg_shapes = [_es_eval(a, env) for a in args]
            outs = _multi_out(fname, len(names), arg_shapes)
            for nm, o in zip(names, outs):
                env[nm] = o
        else:
            for nm in names:
                env[nm] = None


def _signature_params(stmt):
    # 兼容三种声明：`function [a,b] = f(x)`、`function y = f(x)`、`function f(x)`
    m = re.match(
        r'function\s+(?:\[[^\]]*\]\s*=\s*|[\w.]+\s*=\s*)?(\w+)\s*\(([^)]*)\)', stmt)
    if not m:
        return []
    return [p.strip() for p in m.group(2).split(',') if p.strip()]


def _signature_outputs(stmt):
    """从函数声明提取输出变量名列表；无输出（过程式）返回 []。

    P224-Y 用于维度视图展示「函数产出维度」：取声明左侧输出变量，再查函数末尾
    变量环境，得到每个返回值的真实维度。
    """
    s = (stmt or '').strip()
    m = re.match(r'function\s+(.*?)=', s, re.S)
    if not m:
        return []
    lhs = m.group(1).strip().strip('[]')
    if not lhs:
        return []
    return [p.strip() for p in lhs.split(',') if p.strip()]


def _extract_var_refs(tokens):
    """从 token 序列提取被读变量名（ident），排除结构体字段 .f、函数调用名 f(、
    关键字与赋值左侧的目标。用于 P225-A 变量字段流动的 use 侧。"""
    out = []
    n = len(tokens)
    for i in range(n):
        t, k = tokens[i]
        if k != 'ident':
            continue
        if t.lower() in _HILITE_KEYWORDS:
            continue
        # 前一 token 是 '.' → 结构体字段名，不视为独立变量
        j = i - 1
        while j >= 0 and tokens[j][0] == '':
            j -= 1
        if j >= 0 and tokens[j][0] == '.':
            continue
        # 后一 token 是 '(' → 函数/内置调用名，非数据变量
        m = i + 1
        while m < n and tokens[m][0] == '':
            m += 1
        if m < n and tokens[m][0] == '(':
            continue
        out.append(t)
    return out


def _record_flow_defuse(var_defs, writes_map, usages_map, T, lhs_T, rhs_T, env, ln):
    """记录一条赋值语句的 def（写）与 use（读）关系（P225-A）。

    - 写侧：lhs 中的目标变量（含 `[a,b]=` 多目标）。
    - 读侧：rhs 中出现的独立变量（排除字段名与调用名）。
    - from：若 rhs 是单变量直赋（`B = A`）记来源变量，否则记运算涉及的读变量集合。
    """
    names = []
    if lhs_T and len(lhs_T) == 1 and lhs_T[0][1] == 'ident':
        names = [lhs_T[0][0]]
    elif lhs_T and lhs_T[0][0] == '[':
        depth = 0
        for (t, k) in lhs_T:
            if t == '[':
                depth += 1
            elif t == ']':
                depth -= 1
            elif k == 'ident' and depth == 1:
                names.append(t)
        names = [x for x in names if x]
    if not names:
        return
    reads = _extract_var_refs(rhs_T)
    reads = [r for r in reads if r in env]
    writes_map.setdefault(ln, [])
    usages_map.setdefault(ln, [])
    for nm in names:
        writes_map[ln].append(nm)
        var_defs.setdefault(nm, []).append(
            {"line": ln, "from": list(reads), "kind": "assign"})
    for r in reads:
        usages_map[ln].append(r)


def _infer_function_dims(src_lines, f, member_dims=None, flow_out=None):
    """对单个函数做维度推导。返回 (dim_map, line_env, env)。

    dim_map: {(line, name, k): {"p": [...], "r": shp|None, "note": str}}
    line_env: {line_no: env} 行前变量维度环境（供结构体成员维度推导，P223-B）
    env: 函数末尾变量维度环境（供维度视图展示函数产出维度，P224-Y）
    member_dims: 可选结构体成员维度，使 `W = S.f1` 等能解析真实维度（P223-C）
    flow_out: 可选 dict；非空时回填 var_defs/writes/uses（变量字段流动，P225-A）
    """
    dim_map = {}
    env = {}
    line_env = {}
    # P225-A：变量/字段流动 def-use 追踪（flow_out 非空时启用，零开销关闭）
    def_line = {}          # 变量 -> 最近一次定义行
    var_defs = {}          # 变量 -> [{line, from(来源变量列表), kind}]
    writes_map = {}        # 行号 -> [被写变量]
    usages_map = {}        # 行号 -> [被读变量]
    start = getattr(f, 'line', None) or getattr(f, 'body_start', None) or 1
    end = getattr(f, 'body_end', None) or len(src_lines)
    end = min(end, len(src_lines))
    cap = 0
    for ln in range(start, end + 1):
        raw = src_lines[ln - 1] if ln - 1 < len(src_lines) else ''
        code = _strip_inline_comment(raw)
        if not code.strip():
            continue
        st = code.strip()
        if st.startswith('function') or st.startswith('classdef'):
            for pn in _signature_params(st):
                env[pn] = None
                if flow_out is not None and pn not in def_line:
                    def_line[pn] = ln
                    var_defs.setdefault(pn, []).append(
                        {"line": ln, "from": None, "kind": "param"})
            line_env[ln] = dict(env)
            continue
        occ = {}
        for stmt in _split_statements(code):
            stmt = stmt.strip()
            if not stmt:
                continue
            _runs, _ = _tokenize_matlab(stmt, False)
            runs = [(s, e, kind) for (s, e, kind) in _runs if kind not in ('comment', 'ws')]
            T = [(stmt[s:e], kind) for (s, e, kind) in runs]
            if not T:
                continue
            eq = _find_assign(T)
            if eq >= 0:
                lhs_T = T[:eq]
                rhs_T = T[eq + 1:]
                rhs_shape = _es_eval(rhs_T, env, member_dims)
                if flow_out is not None:
                    _record_flow_defuse(var_defs, writes_map, usages_map,
                                        T, lhs_T, rhs_T, env, ln)
                _apply_lhs(lhs_T, rhs_shape, rhs_T, env)
            _record_builtins(T, ln, occ, env, dim_map, member_dims)
            cap += 1
            if cap > 8000:
                break
        line_env[ln] = dict(env)
    if flow_out is not None:
        flow_out["var_defs"] = var_defs
        flow_out["writes"] = writes_map
        flow_out["uses"] = usages_map
    return dim_map, line_env, env


_INFER_FILE_DIMS_CACHE = {}
_INFER_LINE_DIMS_CACHE = {}
_INFER_FUNC_ENV_CACHE = {}  # (id(mf), id(f), path) -> 函数末尾变量维度环境（维度视图输出维度展示，P224-Y）
_INFER_VARFLOW_CACHE = {}   # id(mf) -> {func_name: {"defs":..., "writes":..., "uses":...}}（P225-A）


def _infer_file_dims(mf, member_dims=None):
    """文件级真实维度推导（带缓存；member_dims=None 时按 id(mf) 命中，否则每次重算）。

    返回 merged dim_map（真实 per-call 维度）。member_dims=None 时同时填充
    _INFER_LINE_DIMS_CACHE（行前变量环境），供结构体成员维度推导。
    """
    _k = (id(mf), getattr(mf, '_path', None))  # P225 加固：路径参与键，避免 id 回收串扰
    if member_dims is None and _k in _INFER_FILE_DIMS_CACHE:
        return _INFER_FILE_DIMS_CACHE[_k]
    union = {}
    led = {}
    for f in (getattr(mf, 'functions', []) or []):
        try:
            dm, fld, env = _infer_function_dims(
                mf.source_lines, f, member_dims=member_dims)
        except Exception:
            dm, fld, env = {}, {}, {}
        union.update(dm)
        _INFER_FUNC_ENV_CACHE[(id(mf), id(f), getattr(mf, '_path', None))] = env
        led.update(fld)
    if member_dims is None:
        _INFER_FILE_DIMS_CACHE[_k] = union
        _INFER_LINE_DIMS_CACHE[_k] = led
    return union


def _infer_file_line_env(mf):
    """返回本文件 {line_no: 行前变量维度环境}（供结构体成员维度推导，P223-B）。"""
    _infer_file_dims(mf)  # 确保 _INFER_LINE_DIMS_CACHE 已填充
    return _INFER_LINE_DIMS_CACHE.get((id(mf), getattr(mf, '_path', None)), {})


def _infer_file_varflow(mf, member_dims=None):
    """文件级变量字段流动（def-use）推导，带缓存（P225-A）。

    返回 {func_name: {"defs": {var: [{line, from, kind}]},
                       "writes": {line: [var]}, "uses": {line: [var]},
                       "line0": 函数起始行}}。
    与 `_infer_function_dims` 共用一次遍历（flow_out 旁路），维度和流动一次算清。
    """
    _k = id(mf)
    if member_dims is None and _k in _INFER_VARFLOW_CACHE:
        return _INFER_VARFLOW_CACHE[_k]
    # 先跑维度推导，确保 _INFER_FUNC_ENV_CACHE 已填充（变量维度列依赖它）
    _infer_file_dims(mf, member_dims=member_dims)
    res = {}
    for f in (getattr(mf, 'functions', []) or []):
        flow = {}
        try:
            _infer_function_dims(mf.source_lines, f, member_dims=member_dims,
                                 flow_out=flow)
        except Exception:
            flow = {}
        res[getattr(f, 'name', '?')] = {
            "defs": flow.get("var_defs", {}),
            "writes": flow.get("writes", {}),
            "uses": flow.get("uses", {}),
            "line0": getattr(f, 'line', 0),
        }
    if member_dims is None:
        _INFER_VARFLOW_CACHE[_k] = res
    return res


# ============================================================================
# P204–P223：词法 / 语法 / 数据流 / 静态检查 / 结构 共 20 轮增量改进
# 全部零/低侵入、可单测；遵循「先探针实测、断言再固化」的 TDD 纪律（superpowers）。
# 词法层修改（P204 十六进制/二进制、P207 多字符运算符合并）已直接在 _tokenize_matlab 落地。
# ============================================================================

# ---- P205：MATLAB 命令形式检测 -------------------------------------------
# 命令形式：builtin/ident 后紧跟一个裸词（ident/可带 / \ 的路径）被解释为字符串参数，
# 例如 `help eig`、`disp 'hello'`、`cd my/folder`。返回需转为 string 的 token 下标区间 [(s,e)]。
def _detect_command_form(tokens):
    if tokens and isinstance(tokens[0], tuple) and len(tokens[0]) == 3 and isinstance(tokens[0][0], int):
        raise TypeError("_detect_command_form 需要 (text, kind) 二元组 token，"
                        "而非 (start, end, kind)；请先转换")
    out = []
    n = len(tokens)
    i = 0
    while i < n:
        tk = tokens[i]
        if tk[1] in ("builtin", "ident") and tk[0].lower() not in _HILITE_KEYWORDS:
            chain = []
            j = i + 1
            while j < n:
                tj = tokens[j]
                if tj[1] == "ws":
                    j += 1
                    continue
                if tj[1] in ("ident", "builtin") or (tj[1] == "op" and tj[0] in ("/", "\\")):
                    chain.append(j)
                    j += 1
                    continue
                break
            if chain:
                out.append((chain[0], chain[-1]))
                i = chain[-1] + 1
                continue
        i += 1
    return out


# ---- P206：字符串续行容错 -------------------------------------------------
# 检测行末单引号字符串因 `...` 续行而未结束（MATLAB 允许字符串跨行续接）。
def _tok_string_open_at_eol(line):
    s = line.rstrip()
    if "..." not in s:
        # 无续行符：按普通未配对引号判断
        pass
    in_str = False
    k = 0
    while k < len(s):
        c = s[k]
        if c == "'":
            if in_str and k + 1 < len(s) and s[k + 1] == "'":
                k += 2
                continue
            in_str = not in_str
        k += 1
    return in_str and s.endswith("...")


# ---- P208：嵌套块注释容错 ------------------------------------------------
# 容忍 `%{ ... %}` 的嵌套（外层注释内出现内层 `%{ %}` 视为普通文本，仍属注释）。
def _strip_nested_block_comments(src):
    """剔除 %{ ... %} 块注释（MATLAB 规则：定界符须独占一行）。
    对嵌套的 %{（非独占行）容错：当作普通注释文本忽略，仅按外层的 %} 闭合。"""
    lines = src.splitlines() if isinstance(src, str) else list(src)
    out = []
    depth = 0
    for ln in lines:
        st = ln.strip()
        if depth == 0:
            if st == "%{" or (st.startswith("%{") and st.rstrip("%{ \t") == ""):
                depth = 1
                out.append("")
            else:
                out.append(ln)
        else:
            if st == "%}":
                depth = 0
                out.append("")
            else:
                out.append("")  # 块注释内部
    return "\n".join(out)


# ---- P209：冒号步长形状 ---------------------------------------------------
def _colon_count_scalar(a, b, s=None):
    """a(:s:)b 的元素个数（常量维度原子）。未知返回 ('u',)。"""
    if a is None or b is None:
        return ('u',)
    if s is None or s == 0:
        return ('c', max(0, int(b) - int(a) + 1))
    n = (int(b) - int(a)) // int(s) + 1
    return ('c', max(0, n))


# ---- P210：元胞字面量形状 {a,b;c,d} --------------------------------------
def _shp_cell_literal(grid):
    """grid: 二维列表（行×列）的元素形状；返回元胞数组形状 (nrows, ncols)。"""
    if not grid:
        return _shp(0, 0)
    nrows = len(grid)
    ncols = max((len(r) for r in grid), default=0)
    return _shp(nrows, ncols)


# ---- P211：struct 构造器形状 ---------------------------------------------
def _shp_struct_ctor(pairs):
    """struct('a',x,'b',y) → 标量结构体。返回专用形状标记 ('struct',)。"""
    return ('struct',)


# ---- P212：广播兼容校验 ---------------------------------------------------
def _broadcast_compat(a, b):
    """逐维检查 a,b 是否可广播（dim 相等或其一为 1 或未知）。"""
    if a is None or b is None:
        return True
    la, lb = list(a), list(b)
    if len(la) < len(lb):
        la = [('c', 1)] * (len(lb) - len(la)) + la
    if len(lb) < len(la):
        lb = [('c', 1)] * (len(la) - len(lb)) + lb
    for x, y in zip(la, lb):
        if x == ('u',) or y == ('u',):
            continue
        if x[0] == 'c' and y[0] == 'c' and x[1] != y[1] and x[1] != 1 and y[1] != 1:
            return False
    return True


def _broadcast_expands(a, b):
    """判断是否会发生隐式扩展（某一维其一为 1、另一为不同的常量/未知大小）。"""
    if a is None or b is None:
        return False
    la, lb = list(a), list(b)
    if len(la) < len(lb):
        la = [('c', 1)] * (len(lb) - len(la)) + la
    if len(lb) < len(la):
        lb = [('c', 1)] * (len(la) - len(lb)) + lb
    for x, y in zip(la, lb):
        xc, yc = x[0] == 'c', y[0] == 'c'
        if xc and yc:
            if x[1] != y[1] and (x[1] == 1 or y[1] == 1):
                return True
        elif xc != yc:
            # 一常一未知：未知侧可能需扩展，保守报 True
            if (xc and x[1] == 1) or (yc and y[1] == 1):
                return True
    return False


def _broadcast_shape(a, b):
    """返回 a,b 广播后的结果形状（按最大维度对齐，缺失维补 (c,1)）。"""
    la, lb = list(a), list(b)
    n = max(len(la), len(lb))
    la = [('c', 1)] * (n - len(la)) + la
    lb = [('c', 1)] * (n - len(lb)) + lb
    out = []
    for x, y in zip(la, lb):
        if x == ('u',):
            out.append(y)
        elif y == ('u',):
            out.append(x)
        else:
            out.append(x if x[1] >= y[1] else y)
    return tuple(out)


# ---- P213：循环索引尺寸推断 ----------------------------------------------
def _infer_loop_index(range_text):
    """for k = 1:N / 1:step:N / 1:10 → k 的形状。含变量则末维未知。"""
    parts = [p.strip() for p in range_text.split(":")]
    try:
        nums = [int(p) for p in parts]
    except Exception:
        return _shp(1) + (('u',),)
    if len(nums) == 1:
        return _shp()  # 单值循环（for k = 5）→ k 为标量
    if len(nums) == 2:
        a, b = nums
        return _shp(1, max(0, b - a + 1))
    if len(nums) >= 3:
        a, s, b = nums[0], nums[1], nums[2]
        if s == 0:
            return _shp(1, 0)
        return _shp(1, max(0, (b - a) // s + 1))
    return _shp(1) + (('u',),)


# ---- P214：分支形状合并 ---------------------------------------------------
def _merge_branch_shapes(a, b):
    """if/else 两个分支对同一变量的形状合并（未知取对方，常量取较大）。"""
    if a is None:
        return b
    if b is None:
        return a
    la, lb = list(a), list(b)
    n = max(len(la), len(lb))
    la = [('c', 1)] * (n - len(la)) + la
    lb = [('c', 1)] * (n - len(lb)) + lb
    out = []
    for x, y in zip(la, lb):
        if x == y:
            out.append(x)
        elif x == ('u',):
            out.append(y)
        elif y == ('u',):
            out.append(x)
        elif x[0] == 'c' and y[0] == 'c':
            out.append(('c', max(x[1], y[1])))
        else:
            out.append(x)
    return tuple(out)


# ---- P215：size/numel 常量折叠 -------------------------------------------
def _fold_size_numel(shp, dim=None):
    """size(A)→(1,ndims)；size(A,d)→标量常量；numel(A)→元素总数常量。"""
    if shp is None:
        return None
    if dim is None:
        return _shp(1, len(shp) if shp else 0)
    d = dim if dim >= 1 else 1
    if d - 1 < len(shp) and shp[d - 1][0] == 'c':
        return _shp(shp[d - 1][1])
    return _shp(('u',))


def _fold_numel(shp):
    if not shp:
        return _shp(1)
    prod = 1
    for d in shp:
        if d[0] != 'c':
            return _shp(('u',))
        prod *= d[1]
    return _shp(prod)


# ---- P216：reshape 一致性校验 --------------------------------------------
def _reshape_consistent(in_shp, out_dims):
    """检查 reshape 前后元素总数一致（任一维未知则返回 None=无法判定）。"""
    if in_shp is None or out_dims is None:
        return None
    in_count = 1
    for d in in_shp:
        if d[0] != 'c':
            return None
        in_count *= d[1]
    out_count = 1
    for d in out_dims:
        if d[0] != 'c':
            return None
        out_count *= d[1]
    return in_count == out_count


# ---- P217：索引 end 检测 --------------------------------------------------
def _index_uses_end(idx_tokens):
    """判断索引表达式 token 序列是否含 'end' 关键字（需替换为基维长度）。"""
    if idx_tokens and isinstance(idx_tokens[0], tuple) and len(idx_tokens[0]) == 3 and isinstance(idx_tokens[0][0], int):
        raise TypeError("_index_uses_end 需要 (text, kind) 二元组 token，"
                        "而非 (start, end, kind)；请先转换")
    for tk in idx_tokens:
        if tk[1] == "keyword" and tk[0].lower() == "end":
            return True
        if tk[1] == "ident" and tk[0].lower() == "end":
            return True
    return False


# ---- P218：跨函数维度两趟传播 --------------------------------------------
def _propagate_dims_across_calls(model):
    """model: {fname: {'out': shape|None, 'calls': {callee: argcount}}}。
    两趟：先占位，再按调用图拓扑回填被调输出形状到调用方输出，直到不动点。"""
    out = {fn: info.get("out") for fn, info in model.items()}
    order = list(model.keys())
    for _ in range(len(order) + 1):
        changed = False
        for fn, info in model.items():
            if out[fn] is not None:
                continue
            for callee in info.get("calls", {}):
                cs = out.get(callee)
                if cs is not None:
                    out[fn] = cs
                    changed = True
                    break
        if not changed:
            break
    return out


# ---- P219：return 后不可达检测 -------------------------------------------
def _detect_unreachable_after_return(lines):
    """检测函数体内 return 之后、同块内的不可达语句。返回 [(行号, 文本)]。"""
    findings = []
    block_depth = 0
    in_function = False
    return_depth = None
    for idx, raw in enumerate(lines, 1):
        s = raw.strip()
        if not s or s.startswith("%"):
            continue
        low = s.lower()
        if low.startswith("function"):
            in_function = True
            block_depth = 0
            return_depth = None
            continue
        if not in_function:
            continue
        is_end = low == "end" or low.startswith("end ")
        is_block_open = low.startswith(("if", "for", "while", "switch", "try", "function"))
        if is_end:
            if return_depth is not None and block_depth == return_depth:
                return_depth = None
            block_depth -= 1
            if block_depth < 0:
                in_function = False
                block_depth = 0
                return_depth = None
            continue
        if is_block_open:
            block_depth += 1
        if low.startswith("return"):
            return_depth = block_depth
            continue
        if (return_depth is not None and block_depth >= return_depth
                and not (is_block_open or is_end)):
            findings.append((idx, s))
    return findings


# ---- P221：分词 LRU 缓存（性能） -----------------------------------------
_TOKENIZE_CACHE = {}
def _tokenize_cached(text, in_block=False):
    # P221：修复签名 bug —— 旧实现把 keep_comments 当成 _tokenize_matlab 的第二参数
    # （in_block，跨行块注释状态）传入，会破坏多行块注释（%{ / %}）剥离。
    # 现正确透传 in_block。调用方（单行场景）传 in_block=False 即得等价结果。
    key = (text, in_block)
    if key in _TOKENIZE_CACHE:
        return _TOKENIZE_CACHE[key]
    if len(_TOKENIZE_CACHE) > 2000:
        _TOKENIZE_CACHE.clear()
    res = _tokenize_matlab(text, in_block)
    _TOKENIZE_CACHE[key] = res
    return res


# ---- P222：classdef 成员提取 ---------------------------------------------
def _parse_classdef_members(src):
    """解析 classdef 的 properties / methods 块，返回 {'properties':[...],'methods':[...]}。
    正确处理 methods 块内嵌套 function/end（函数体的 end 不提前关闭 methods 块）。"""
    lines = src.splitlines() if isinstance(src, str) else list(src)
    res = {"properties": [], "methods": []}
    mode = None
    func_depth = 0
    for ln in lines:
        s = ln.strip()
        if not s or s.startswith("%"):
            continue
        low = s.lower()
        if low.startswith("classdef"):
            continue
        if low.startswith("properties"):
            mode = "properties"
            continue
        if low.startswith("methods"):
            mode = "methods"
            func_depth = 0
            continue
        if low == "end":
            if mode == "methods":
                if func_depth > 0:
                    func_depth -= 1  # 闭合某个方法函数体，methods 块仍打开
                else:
                    mode = None      # 闭合 methods 块本身
            elif mode == "properties":
                mode = None
            continue
        if mode == "properties":
            name = re.split(r"[\s(=]", s, 1)[0].strip()
            if name:
                res["properties"].append(name)
        elif mode == "methods":
            if low.startswith("function"):
                func_depth += 1
                m = re.search(r"function\s+(.*)", s, re.IGNORECASE)
                if m:
                    res["methods"].append(m.group(1).strip())
    return res


# ---- P223：HTML head/foot 模板去重 ---------------------------------------
def _html_head(title, theme="light"):
    # 注：刻意不关闭 </head>，以便调用方在 <head> 内追加 <style>/<script> 后再统一收口，
    # 与 render_source_page 的拼接契约一致（见 P223）。
    return ("<!DOCTYPE html><html lang=\"zh-CN\"><head>"
            "<meta charset=\"utf-8\">"
            "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
            "<title>%s</title>" % html_mod.escape(title))


def _html_foot():
    return "</html>"


def render_source_page(mf, index, files, fn_to_file, callers_of, calls_of, root, rel, model=None,
                       max_nodes=None, cg_json=None, gid_of=None, offline=False):
    """渲染单个源码文件页：顶部函数索引 + 可跳转源码 + 按需下钻调用图。

    cg_json / gid_of：可选，由调用方（render_browse_site）预先构建的全局调用图，
    直接复用以避免每个源文件都重建一次 O(files^2 * vars) 的调用图（否则在
    多文件项目下退化为 O(files^3)，表现为渲染阶段「卡死」）。未传入时本地构建，
    保持单文件独立调用的兼容性。"""
    # P113：渲染层契约前置 —— 幂等补齐缺失属性，独立调用亦安全
    _coerce_mfile(mf)
    lines = []
    A = lines.append
    # P223：复用 HTML 头模板（不再内联重复 doctype/head/meta/title）
    A(_html_head(mf.rel))
    A('<link rel="stylesheet" href="%s">' % _rel_to_src_asset(mf.rel, "styles.css"))
    # P-rev R27：调用图模块（63KB）此前**内联在每个源码页**，12 个页面各自重复携带
    # 同一份代码，首屏 JS 达 147KB。改为外链到 src/_localcg.js 后由浏览器缓存一次，
    # 单页首屏 JS 降到约 84KB（外链的加载时机与同位置内联脚本一致，行为不变）。
    _lcg_asset = _rel_to_src_asset(mf.rel, "_localcg.js")
    A('<script src="%s" defer></script>' % _lcg_asset)
    # A4/P269：MathJax **按需 + 离线可控** —— 仅当本文件含 LaTeX 片段、且未开启
    # --offline 时才引入 CDN，避免内网环境发起必然失败的外网请求（首屏变慢 + 控制台报错）。
    if (not offline) and _has_latex("\n".join(mf.source_lines or [])):
        A("<script>%s</script>" % MATHJAX_INIT_JS)
    A("</head><body>")
    # P271 R5：无障碍基线——跳转到主内容的 skip link
    A('<a class="skip-link" href="#main-content">跳到主内容</a>')
    A(f"<header><span class=\"brand\">MATLAB 源码浏览</span>"
      f"<a href=\"{_up_to_index(mf.rel)}\">← 返回索引</a>"
      f"<a href=\"{_to_dir_page(mf.rel)}\">目录 {html_mod.escape(os.path.dirname(mf.rel) or '(root)')}</a>"
      f"<span class=\"muted\" style=\"color:#8b949e;font-size:13px\">"
      f"{html_mod.escape(mf.rel)} · {mf.kind} · {mf.lines} 行 · {mf.encoding}</span></header>")
    A("<main id=\"main-content\">")
    A(_crumbs_html([
        ("项目", _up_to_index(mf.rel)),
        (os.path.dirname(mf.rel) or "(root)", _to_dir_page(mf.rel)),
        (mf.rel, None),
    ]))
    A(f"<h1>{html_mod.escape(mf.rel)}</h1>")

    # C3：文件概览卡片（文件头 author/date/description + 复杂度 + 函数/类数）
    _fh = mf.header or {}
    _fo_desc = _fh.get("description") or ""
    _fo_author = _fh.get("author") or ""
    _fo_date = _fh.get("date") or ""
    _fo_version = _fh.get("version") or ""
    _fo_cx = sum(f.complexity for f in mf.functions if f.kind != "script")
    _fo_nfuncs = sum(1 for f in mf.functions if f.kind != "script")
    _fo_ncls = len(mf.classes)
    if _fo_desc or _fo_author or _fo_date or _fo_version or _fo_cx:
        A('<div class="file-overview">')
        if _fo_desc:
            A('<div class="fo-desc">%s</div>' % html_mod.escape(_fo_desc))
        A('<div class="fo-meta">'
          '<span>函数 %d</span><span>类 %d</span><span>复杂度 %d</span><span>%d 行</span>'
          % (_fo_nfuncs, _fo_ncls, _fo_cx, mf.lines or 0))
        if _fo_author:
            A('<span>👤 %s</span>' % html_mod.escape(_fo_author))
        if _fo_date:
            A('<span>📅 %s</span>' % html_mod.escape(_fo_date))
        if _fo_version:
            A('<span>🔖 %s</span>' % html_mod.escape(_fo_version))
        A('</div>')
        A('</div>')

    # P20：调用路径查找面板（最短可达路径 BFS）。位于文件标题下方，与函数卡片并列。
    A(_cg_path_panel_html())

    # P22：影响面 / 依赖面（传递闭包）交互面板。
    A(_cg_impact_panel_html())

    # C2：项目内同名映射（含脚本），用于「疑似漏检」调用名一键跳转到同名定义。
    project_map = defaultdict(list)
    for _mf in files:
        for _f in _mf.functions:
            project_map[_f.name.lower()].append((_f, _mf))

    # 本文件使用的 MATLAB 内置库函数说明（P18）：汇总本文件实际调用的内置函数，
    # 列出名称、次数与一句说明，便于快速回顾其语义（折叠以免喧宾夺主）。
    file_builtins = []
    seen = set()
    for f in mf.functions:
        for bname, c in (f.builtin_calls or {}).items():
            if bname not in seen:
                seen.add(bname)
                file_builtins.append((bname, c))
    file_builtins.sort(key=lambda kv: (-kv[1], kv[0].lower()))
    if file_builtins:
        A("<details class=\"builtin-list\">"
          "<summary>本文件使用的 MATLAB 库函数（%d，展开查看说明）</summary>"
          "<div class=\"builtin-list-body\">" % len(file_builtins))
        for bname, c in file_builtins:
            A("<div class=\"builtin-item\"><code>%s</code> "
              "<span class=\"muted\">×%d</span> — %s</div>"
              % (html_mod.escape(bname), c, html_mod.escape(matlab_builtin_desc(bname))))
        A("</div></details>")

    # 全局调用图邻接表（一次构建，跨页缓存）：嵌入共享 _cgdata.js，供前端
    # initLocalCG 按需下钻渲染。SITE_REL 表示该页目录到站点根的相对前缀，用于拼接节点 href。
    # 复用调用方传入的全局调用图（render_browse_site 已构建一次），否则本地构建。
    if cg_json is None or gid_of is None:
        cg_json, gid_of = _build_global_cg(files, fn_to_file, calls_of, callers_of, model,
                                           max_nodes=max_nodes)
    cg_asset = _rel_to_src_asset(mf.rel, "_cgdata.js")
    site_rel = _cg_site_rel(mf.rel)
    A("<script src=\"%s\" defer></script>" % html_mod.escape(cg_asset))
    A("<script>window.__CG_SITE_REL__=\"%s\";</script>" % site_rel)
    # P270：命令面板索引（函数/文件/目录/全局变量），须在搜索脚本之前加载
    _index_asset = _rel_to_src_asset(mf.rel, "_index.js")
    A("<script src=\"%s\" defer></script>" % html_mod.escape(_index_asset))
    # P107：全站搜索浮层（Ctrl+K / '/'）——复用 __CG__.meta + __GS_INDEX__
    _search_asset = _rel_to_src_asset(mf.rel, "_search-lazy.js")
    A("<script src=\"%s\" defer></script>" % html_mod.escape(_search_asset))

    # 文件内函数速览（含双向跳转链接）
    # 变量 / 参数流向分析（用于源码级读写高亮）
    func_of_line, line_var_map, var_summary = _analyze_varflow(mf)
    # P36：结构体字段定义位（首次写入）——供源码页标记 data-kind="d" 实现字段跳转
    field_def_map = _collect_field_defs(mf)
    # R41-R60：维度传播——按实际代码推导每个内置调用处的真实维度，供前端展示。
    dim_map = _infer_file_dims(mf) if (getattr(mf, "source_lines", None) and len(mf.source_lines or []) <= 8000) else {}
    if mf.functions:
        A("<h2>函数速览</h2>")
        cguid = [0]
        for f in mf.functions:
            cls = f"kind {f.kind}"
            # 调用 / 被调用计数徽章
            n_out = len(calls_of.get(id(f), []))
            n_in = len(callers_of.get(id(f), []))
            cx = f.complexity
            sig_html = _highlight_source_line(f.signature(), [], False)[0]
            # P104：函数名可点击直达详情页（gid 来自全局调用图，缺失时退化为纯文本）
            _gid = gid_of.get(id(f))
            if _gid is not None:
                # 修复：相对路径按页面深度计算（此前硬编码导致 browse/src/ 下的死链）
                sig_html = ('<a class="fd-fn" href="%s">'
                            % _to_func_detail(mf.rel, _gid)) + sig_html + "</a>"
            A(f"<div class=\"func-card\" id=\"{_anchor_id(f)}\">")
            A(f"<h4><span class=\"{cls}\">{f.kind}</span> "
              f"<code>{sig_html}</code> "
              f"<span class=\"muted\">第 {f.line} 行</span>"
              f"<a href=\"#L{f.line}\" class=\"badge\">↳ 源码</a>"
              f"<span class=\"badge\" title=\"本函数直接调用的项目内函数数\">调用 {n_out}</span>"
              f"<span class=\"badge\" title=\"直接调用本函数的调用方数\">被调用 {n_in}</span>"
              f"<span class=\"badge\" title=\"圈复杂度 ≈ 分支点(if/for/while/switch…)+1\">复杂度 {cx}</span></h4>")
            # 参数流向（可点击高亮源码读写位置）
            flow_html = _render_param_flow_pills(f, var_summary)
            if flow_html:
                A(flow_html)
            # P73：该函数在文件夹层面的调用情况（跨目录调用了哪些文件夹、被哪些文件夹调用）
            _dir_label = os.path.dirname(mf.rel) or "(root)"
            _called_dirs = set()
            for _cf, _cmf in calls_of.get(id(f), []):
                if _cmf is not None:
                    _td = os.path.dirname(_cmf.rel) or "(root)"
                    if _td != _dir_label:
                        _called_dirs.add(_td)
            _caller_dirs = set()
            for _cf2 in callers_of.get(id(f), []):
                if _cf2 is not None and getattr(_cf2, "mfile", None) is not None:
                    _sd = os.path.dirname(_cf2.mfile.rel) or "(root)"
                    if _sd != _dir_label:
                        _caller_dirs.add(_sd)
            if _called_dirs or _caller_dirs:
                _parts = []
                if _called_dirs:
                    _parts.append("调用 → " + "、".join(
                        '<a href="%s">%s</a>' % (_to_dir_page_from(mf.rel, _d), html_mod.escape(_d))
                        for _d in sorted(_called_dirs)))
                if _caller_dirs:
                    _parts.append("被调用 ← " + "、".join(
                        '<a href="%s">%s</a>' % (_to_dir_page_from(mf.rel, _d), html_mod.escape(_d))
                        for _d in sorted(_caller_dirs)))
                A('<div class="fn-folder-calls"><span class="muted">文件夹调用：</span>%s</div>'
                  % " ｜ ".join(_parts))
            # P73：参数说明（缺失显式 null）
            _docs = f.param_docs()
            _in_docs = _docs["inputs"]
            _out_docs = _docs["outputs"]
            if f.inputs or f.outputs:
                _doc_parts = []
                if f.inputs:
                    _doc_parts.append("输入：" + " ".join(
                        '<span class="param-doc">%s=%s</span>' % (
                            html_mod.escape(_p),
                            html_mod.escape(_in_docs.get(_p)) if _in_docs.get(_p)
                            else '<span class="null">null</span>')
                        for _p in f.inputs))
                if f.outputs:
                    _doc_parts.append("输出：" + " ".join(
                        '<span class="param-doc">%s=%s</span>' % (
                            html_mod.escape(_p),
                            html_mod.escape(_out_docs.get(_p)) if _out_docs.get(_p)
                            else '<span class="null">null</span>')
                        for _p in f.outputs))
                A('<div class="fn-param-docs">%s</div>' % " ｜ ".join(_doc_parts))
            # 结构化头部注释（DESCRIPTION / Input / Output / Calling / ...）
            hdr_html = _render_func_header_html(f)
            if hdr_html:
                A(hdr_html)
            else:
                # 缺头注释时给出友好摘要，保证每个函数页都有可读说明
                A('<div class="fn-friendly-desc muted">%s</div>'
                  % html_mod.escape(friendly_func_summary(f, calls_of, callers_of)))
            # 调用列表（静态分析结果）——按源码调用顺序编号 + 函数简要说明（注释）
            callee_items = calls_of.get(id(f), [])
            if callee_items:
                A("<div class=\"muted\"><b>调用（按源码调用顺序，共 %d 个）：</b></div>"
                  % len(callee_items))
                A("<ol class=\"call-order-list\">")
                for _i, (cf, dmf) in enumerate(callee_items, 1):
                    _desc = _fn_desc(cf) or friendly_func_summary(cf, calls_of, callers_of)
                    _dspan = ("<span class=\"muted\"> — %s</span>"
                              % html_mod.escape(_desc)) if _desc else ""
                    A("<li><span class=\"call-ord\">%d</span>"
                      "<a href=\"%s#L%d\">%s</a>"
                      "<span class=\"muted\"> · %s</span>%s</li>"
                      % (_i, _rel_href(mf.rel, dmf), cf.line,
                         html_mod.escape(cf.name),
                         html_mod.escape(dmf.rel if dmf else ""), _dspan))
                A("</ol>")
            # P74/P79：未解析调用三级归类（项目内同名=疑似漏检 / 内置=附说明 / 外部）
            if f.external_calls:
                _ext_parts = []
                for _name in sorted(f.external_calls):
                    _desc = matlab_builtin_desc(_name)
                    if _name.lower() in project_map:
                        # C2：疑似漏检调用名一键跳转到同名定义（含脚本；把「看得到」升级为「改得动」）
                        _tgt, _tmf = project_map[_name.lower()][0]
                        _href = "%s#L%d" % (_rel_href(mf.rel, _tmf), _tgt.line)
                        _ext_parts.append('<a class="ext-leak" href="%s" '
                                          'title="项目内存在同名函数/脚本，疑似漏检——点击跳转到同名定义">%s</a>'
                                          % (_href, html_mod.escape(_name)))
                    elif _desc:
                        _ext_parts.append('<code title="%s">%s</code>' % (
                            html_mod.escape(_desc, quote=True), html_mod.escape(_name)))
                    else:
                        _ext_parts.append("<code>%s</code>" % html_mod.escape(_name))
                A("<div class=\"fn-external\"><span class=\"muted\">未解析调用（项目内不存在/外部函数）：</span>"
                  + "、".join(_ext_parts)
                  + "</div>")
            # 被调用列表（按调用方定义位置）——标注入口函数（追本溯源的「源头」）
            caller_items = callers_of.get(id(f), [])
            if caller_items:
                A("<div class=\"muted\"><b>被调用（按调用方定义位置，共 %d 个）：</b></div>"
                  % len(caller_items))
                A("<ul class=\"call-order-list\">")
                for cf in caller_items:
                    _tmf = fn_to_file.get(id(cf))
                    _desc = _fn_desc(cf) or friendly_func_summary(cf, calls_of, callers_of)
                    _entry = ("（入口函数，无调用方）" if not callers_of.get(id(cf)) else "")
                    _dspan = (" — %s" % html_mod.escape(_desc)) if _desc else ""
                    A("<li><a href=\"%s#L%d\">%s</a>"
                      "<span class=\"muted\"> · %s%s</span>%s</li>"
                      % (_rel_href(mf.rel, _tmf), cf.line, html_mod.escape(cf.name),
                         html_mod.escape(_tmf.rel if _tmf else ""), _entry, _dspan))
                A("</ul>")
            # P22：影响面 / 依赖面（传递闭包）——追本溯源：谁（传递）调用本函数、
            # 本函数（传递）依赖谁，均按最短距离分层列出，点击可跳转对应函数源码。
            A(_render_impact_dependency_html(f, callers_of, calls_of, fn_to_file, mf))
            # 局部调用关系图：调用图 + 被调用图（前端「按需下钻」渲染）。
            # 仅生成占位容器，真实 SVG 由 initLocalCG 依据 window.__CG__ 渲染：
            # 默认浅层（根 + 直接子一层），点击节点上的 +/- 徽标增量展开 / 折叠
            # 其被调 / 被调用子树，彻底消除 MAX_CALLGRAPH_DEPTH 深度截断。
            callee_svg = _render_callgraph_host(f, "callee", gid_of)
            caller_svg = _render_callgraph_host(f, "caller", gid_of)
            if callee_svg or caller_svg:
                A("<details class=\"callgraph\"><summary>调用关系图（SVG Call / Caller Graph）</summary>")
                A("<div class=\"muted cg-note cg-search-wrap\">"
                  "<input type=\"text\" class=\"cg-search\" "
                  "placeholder=\"🔍 搜索函数名 → 自动展开路径并脉冲定位（如 helper）\" "
                  "aria-label=\"搜索并聚焦调用图函数\">"
                  "<span class=\"cg-search-hint\">匹配子串将自动展开其全部祖先调用路径并脉冲高亮；清空恢复。</span>"
                  "<button type=\"button\" class=\"cg-share-btn\" "
                  "data-cg-act=\"cgExpandAllScoped\" title=\"一键展开当前卡片全部调用链（callee 图全下游 / caller 图溯源到入口）\">"
                  "&#127757; 溯源（展开全部）</button>"
                  "<button type=\"button\" class=\"cg-share-btn\" "
                  "data-cg-act=\"cgCollapseAllScoped\" title=\"复位当前卡片为默认浅层（根 + 直接子一层）\">收缩</button>"
                  "<button type=\"button\" class=\"cg-share-btn\" "
                  "data-cg-act=\"cgCopyShareLink\">"
                  "&#128279; 复制可分享链接</button></div>" + _CG_DELEGATE_JS + ")")
                A("<div class=\"muted cg-note\">提示：默认仅展示<b>根函数 + 直接子一层</b>（浅层）。点击节点上的"
                  "<b> + / − 徽标</b>可<b>增量展开 / 折叠</b>其被调（callee）或被调用（caller）子树，彻底突破旧版的深度截断；"
                  "<b>点击节点本体</b>高亮其全部上下游调用链并淡化其余；<b>按住 Shift 点击</b>在新标签打开源码；"
                  "圆形颜色代表函数类型，连线表示调用方向（左→右）；<b>红色虚线循环徽标（↺）</b>表示该函数处于循环调用（闭环）中，点击可高亮整个循环。"
                  "所有展开 / 聚焦 / 循环高亮状态都会自动写入 URL <b>#</b>，刷新或分享链接后可一键还原，浏览器前进 / 后退也能切换视图。</div>")
                A("<div class=\"cg-legend2\">"
                  "<span><i style=\"background:#1a7f37\"></i>main</span>"
                  "<span><i style=\"background:#9a6700\"></i>local</span>"
                  "<span><i style=\"background:#8250df\"></i>method</span>"
                  "<span><i style=\"background:#cf222e\"></i>constructor</span>"
                  "<span><i style=\"background:#57606a\"></i>script</span>"
                  "<span><i style=\"background:#0969da\"></i>其他</span></div>")
                if callee_svg:
                    A("<div class=\"cg-title\">调用图 (Call Graph)：本函数调用的函数</div>")
                    A("<div class=\"cg-local\">%s</div>" % callee_svg)
                if caller_svg:
                    A("<div class=\"cg-title\">被调用图 (Caller Graph)：调用本函数的函数</div>")
                    A("<div class=\"cg-local\">%s</div>" % caller_svg)
                A("</details>")
            A("</div>")

    # 源码视图（语法高亮 + 调用点跳转 + 参数流向高亮）
    A("<h2>源码</h2>")
    # P105：左侧 sticky 函数大纲（滚动联动高亮由 _search.js 的 scrollspy 驱动）
    A('<div class="src-wrap">')
    A('<aside class="src-outline" aria-label="函数大纲"><h4>函数大纲</h4>')
    for _of in mf.functions:
        # P-rev R7：函数大纲项携带 data-sym，供跨页精确联动（rel::name）
        A('<a href="#L%d" data-line="%d" data-sym="%s::%s" title="%s">%s</a>'
          % (_of.line, _of.line, html_mod.escape(mf.rel), html_mod.escape(_of.name),
             html_mod.escape(_of.name), html_mod.escape(_of.name)))
    A("</aside>")
    A('<div class="src-code">')
    # 语法颜色图例
    A("<div class=\"legend\">"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#6a737d\"></span>注释</span>"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#b35a1f\"></span>字符串</span>"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#d73a49\"></span>关键字</span>"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#005cc5\"></span>内置函数</span>"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#0086b3\"></span>数字</span>"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#0969da\"></span>调用(可跳转)</span>"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#1f6feb;text-decoration:underline\"></span>结构体基名</span>"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#8250df\"></span>结构体字段</span>"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#cfd8e3\"></span>参数声明</span>"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#dbeafe\"></span>参数读取</span>"
      "<span class=\"chip\"><span class=\"sw\" style=\"background:#ffedd5\"></span>参数写入</span>"
      "</div>")
    A("<div class=\"muted vf-hint\">提示：点击上方「参数流向」药丸，或源码中的参数名，"
      "可高亮该参数在本函数体内的全部声明 / 读取 / 写入位置；<b>点击源码中任意局部变量名"
      "</b>，可高亮「同一函数内」该变量的全部出现位置；<b>点击结构体字段名"
      "(如 <code>obj.field</code> 中的 field)</b> 可单独高亮该字段的全部访问；"
      "<b>点击结构体基名(如 <code>obj.field</code> 中的 obj)</b> 可联动高亮其所有字段访问；"
      "勾选下方开关后，点击变量名将高亮<b>整个文件</b>内的同名变量（追踪跨函数传递）。"
      "再次点击同一变量、或点击空白处取消。</div>")
    A("<label class=\"xf-toggle\"><input type=\"checkbox\" id=\"ident-cross-file\"> "
      "跨函数同名变量高亮（勾选后，点击变量名高亮<b>整个文件</b>内的同名变量 / 字段）</label>")
    A("<label class=\"xf-toggle\"><input type=\"checkbox\" id=\"fold-comments\"> "
      "折叠纯注释行（让核心逻辑更紧凑）</label>")
    # P-rev R65：块注释统一展开/折叠按钮（与 R58 的逐块持久化互补）
    A("<button type=\"button\" class=\"ug-btn\" id=\"blk-fold-all\" "
      "aria-label=\"折叠所有块注释\">折叠块注释</button>")
    A("<div id=\"vf-info\" class=\"vf-info\"></div>")
    A("<div class=\"src\"><table>")
    def_lines = {f.line for f in mf.functions}
    # P271 R5-4：函数定义行的内联诊断徽章。
    # 灵感来自 MATLAB Agentic Toolkit 的 check_matlab_code —— 把分析结论
    # 放回**代码所在的位置**，而不是让用户去另一页对照表格看。
    # 仅展示有信息量的项；高复杂度/高扇入用告警样式突出，点击直达函数详情。
    line_diag = {}
    for f in mf.functions:
        n_out = len(calls_of.get(id(f), []))
        n_in = len(callers_of.get(id(f), []))
        cx = f.complexity
        warn = (cx >= 15) or (n_in >= 8)
        cls = "src-diag src-diag-warn" if warn else "src-diag"
        tip = ("圈复杂度 %d（≥15 视为高复杂度）｜调用 %d 个项目内函数｜"
               "被 %d 处调用（≥8 视为高扇入）｜点击打开函数详情" % (cx, n_out, n_in))
        gid = gid_of.get(id(f))
        if gid is not None:
            href = _to_func_detail(mf.rel, gid)
            inner = ('<a class="%s" data-sym="%s::%s" href="%s" title="%s">'
                     % (cls, html_mod.escape(mf.rel), html_mod.escape(f.name),
                        html_mod.escape(href), html_mod.escape(tip)))
            tail = "</a>"
        else:
            inner = ('<span class="%s" data-sym="%s::%s" title="%s">'
                     % (cls, html_mod.escape(mf.rel), html_mod.escape(f.name),
                        html_mod.escape(tip)))
            tail = "</span>"
        marks = []
        if cx >= 15:
            marks.append('<b class="sd-w">复杂度 %d</b>' % cx)
        else:
            marks.append('复杂度 %d' % cx)
        marks.append('调用 %d' % n_out)
        if n_in >= 8:
            marks.append('<b class="sd-w">被调用 %d</b>' % n_in)
        else:
            marks.append('被调用 %d' % n_in)
        line_diag[f.line] = inner + " &#9432; " + " · ".join(marks) + tail

    # P271 R6-3：逐行「现代化标记」——在用到废弃/不推荐 API 的行上直接标出，
    # 悬停显示官方推荐的现代替代方案（数据来自 matlab-modernize-code 速查表）。
    # 性能：先在**文件级**预筛出本文件真正用到的 API，再逐行只对它们做匹配，
    # 避免「每行 × 全表」造成的无谓开销（大文件上会明显变慢）。
    file_text = "\n".join(mf.source_lines or [])
    used_api = [(o, v) for o, v in MODERNIZE_MAP.items()
                if re.search(r"(?<![A-Za-z0-9_.])" + re.escape(o) + r"\s*\(",
                             file_text)]
    line_modern = {}
    if used_api:
        for _i, _raw in enumerate(mf.source_lines or [], 1):
            _s = _raw.split("%")[0] if not _raw.strip().startswith("%") else ""
            if not _s.strip():
                continue
            _hits = []
            for _old, (_new, _cat) in used_api:
                if re.search(r"(?<![A-Za-z0-9_.])" + re.escape(_old) + r"\s*\(", _s):
                    _hits.append((_old, _new, _cat))
            if _hits:
                line_modern[_i] = _hits
    # 按行渲染，将调用点链接、参数读写标注与语法高亮合并
    sites = defaultdict(list)   # line -> [(start, end, href, ambiguous, desc)]
    for f in mf.functions:
        for lineno, st, en, tgt_fn in f.call_sites:
            if lineno <= len(mf.source_lines) and tgt_fn is not None:
                tf = tgt_fn
                tm = fn_to_file.get(id(tf))
                if tm is not None:
                    name = mf.source_lines[lineno - 1][st:en]
                    amb = f.ambiguous_calls.get(name, 0) > 1
                    # 目标函数的简要说明（来自结构化头部注释），悬停调用点时展示（P18）
                    tdesc = getattr(tf, "header", {}) or {}
                    tdesc = tdesc.get("description", "") if isinstance(tdesc, dict) else ""
                    sites[lineno].append(
                        (st, en, f"{_rel_href(mf.rel, tm)}#L{tf.line}", amb, tdesc))
    # A2：多返回值解构——行号 -> [(lhs, cname, tgt_fn)]，源码行追加「返回值流向」标注
    destructure_map = defaultdict(list)
    for f in mf.functions:
        for lineno, lhs, cname, tgt_fn in f.destructured_calls:
            if lineno <= len(mf.source_lines):
                destructure_map[lineno].append((lhs, cname, tgt_fn))
    in_block = False  # 跨行块注释 %{ ... %} 状态
    # P-rev R37：识别文件头注释区域（首个 function/classdef 之前且所有行均为注释）。
    # 这部分内容已在页面顶部的「文件信息卡」中完整展示，源码体里再渲染一遍就是
    # 重复——让用户读两遍相同内容，且打乱了阅读节奏。这里改为：在源码体里用单行
    # 「📄 文件头注释（已在顶部信息卡中展示，可展开）」占位替代该区域所有行，
    # 既保留行号准确（不删行）、又消除重复阅读负担。
    hdr = mf.header or {}
    _hdr_keys = ("description", "notice", "references", "author", "date")
    _has_header = any(hdr.get(k) for k in _hdr_keys)
    if _has_header:
        _first_code = len(mf.source_lines) + 1
        for _i, _raw in enumerate(mf.source_lines, start=1):
            _st = _raw.strip()
            if (_st.startswith("function") or _st.startswith("classdef")) \
                    and not _st.startswith("%"):
                _first_code = _i
                break
        _hdr_end = max(0, _first_code - 1)
    else:
        _hdr_end = 0
    # P-rev R55：预扫描 %{ ... %} 块注释范围，折叠为单行可展开占位（与 R37 文件头
    # 折叠同构）。_block_start/_block_end 记录「块起始行 -> 块结束行」。
    _block_start, _block_end = {}, {}
    _in_blk = False
    _blk_start_line = 0
    for _i, _raw in enumerate(mf.source_lines, start=1):
        _st = _raw.strip()
        if not _in_blk and _st.startswith("%{"):
            _in_blk = True
            _blk_start_line = _i
        elif _in_blk and _st.startswith("%}"):
            _in_blk = False
            _block_start[_blk_start_line] = _i
            _block_end[_i] = _blk_start_line
    for i, raw in enumerate(mf.source_lines, start=1):
        line = raw.rstrip("\r\n")
        ln_cls = " fdef" if i in def_lines else ""
        # 整行注释（含 %{ %} 块注释行）加可视化背景，使「注释」在源码中清晰可见
        if line.strip().startswith("%"):
            ln_cls += " comment-line"
        # P-rev R50：块注释 %{ ... %} 用独立的左侧边框色区分，让大段说明文字
        # 一眼看出是「成块的注释」而非逐行零散注释
        if line.strip().startswith("%{") or line.strip().startswith("%}"):
            ln_cls += " block-comment-edge"
        # P-rev R41：空白行作为「呼吸位」独立标记，给视觉留白
        if not line.strip():
            ln_cls += " blank-line"
        # P-rev R37：折叠文件头注释区域为单行可展开占位
        if _hdr_end and i <= _hdr_end:
            if i == 1:
                A(f"<tr class=\"code-row src-hdr-fold\" id=\"L{i}\">"
                  f"<td class=\"ln\" data-ln=\"{i}\" title=\"点击复制本行链接\"># {i}</td>"
                  f"<td class=\"code\"><details class=\"src-hdr-details\">"
                  f"<summary>📄 文件头注释（已在顶部信息卡中展示，共 {_hdr_end} 行）</summary>"
                  f"<span class=\"src-hdr-hint\">展开可查看原始注释文本</span></details></td></tr>")
                continue
            else:
                # 后续头部行折叠为隐藏 span，避免在源码体里重复展示
                A(f"<tr class=\"code-row src-hdr-fold\" id=\"L{i}\" hidden>"
                  f"<td class=\"ln\" data-ln=\"{i}\"># {i}</td>"
                  f"<td class=\"code\">{html_mod.escape(line)}</td></tr>")
                continue
        # P-rev R55/R58：块注释 %{ ... %} 折叠为单行可展开占位。R58 加 data-blk 键，
        # 供前端按「文件+起始行」记住折叠/展开偏好（localStorage 持久化）。
        if i in _block_start:
            _end = _block_start[i]
            _nlines = _end - i + 1
            A(f"<tr class=\"code-row src-blk-fold\" id=\"L{i}\">"
              f"<td class=\"ln\" data-ln=\"{i}\" title=\"点击复制本行链接\"># {i}</td>"
              f"<td class=\"code\"><details class=\"src-blk-details\" data-blk=\"{i}\">"
              f"<summary>%{{ 块注释 · {_nlines} 行（点击展开）%}}</summary></details></td></tr>")
            # 块内行折叠为隐藏，仅起始行显示 summary
            for _bi in range(i + 1, _end + 1):
                A(f"<tr class=\"code-row src-blk-fold\" id=\"L{_bi}\" hidden>"
                  f"<td class=\"ln\" data-ln=\"{_bi}\"># {_bi}</td>"
                  f"<td class=\"code\">{html_mod.escape(mf.source_lines[_bi - 1].rstrip(chr(13) + chr(10)))}</td></tr>")
            continue
        if i in _block_end and i not in _block_start:
            continue
        line_sites = sites.get(i, [])
        owning = func_of_line.get(i)
        fn_anchor = _anchor_id(owning) if owning else ""
        lvars = line_var_map.get(i, {})
        code_html, in_block = _highlight_source_line(
            line, line_sites, in_block, lvars, fn_anchor, i, dim_map,
            field_def_map.get(i))
        # A2：追加多返回值解构标注（`[d, s] = demodulate(x)` → 返回值流向）
        extra = ""
        for lhs, cname, tgt_fn in destructure_map.get(i, []):
            outs = getattr(tgt_fn, "outputs", []) or []
            if outs:
                pairs = []
                for idx, lv in enumerate(lhs):
                    target = outs[idx] if idx < len(outs) else "?"
                    pairs.append("%s = %s" % (lv, target))
                tip = "%s 返回 [%s]，依次赋给：%s" % (cname, ", ".join(outs), "; ".join(pairs))
            else:
                tip = "[%s] = %s(x)：多返回值解构（%d 个返回值）" % (", ".join(lhs), cname, len(lhs))
            extra += (" <span class=\"destructure\" title=\"%s\">"
                      "&#8618; [%s] &larr; %s</span>"
                      % (html_mod.escape(tip), html_mod.escape(", ".join(lhs)),
                         html_mod.escape(cname)))
        # P271 R5-4：函数定义行附内联诊断（把分析结论放回代码所在位置）
        diag = line_diag.get(i, "")
        # P271 R6-3：废弃/不推荐 API 的行内标记（悬停显示现代替代方案）
        mods = line_modern.get(i)
        if mods:
            parts = []
            for old, new, cat in mods:
                sev = "high" if old in HIGH_RISK_DYNAMIC or old == "guide" else "mid"
                tip = "%s：%s → 建议改用 %s" % (cat, old, new)
                parts.append(
                    '<span class="src-mod src-mod-%s" title="%s">'
                    '&#9888; %s &rarr; %s</span>'
                    % (sev, html_mod.escape(tip), html_mod.escape(old),
                       html_mod.escape(new)))
            diag += '<span class="src-mods">' + "".join(parts) + "</span>"
        # P-rev R32：data-orig 应存「原始文本」而非高亮 HTML。
        # 此前把整个 code_html（含 data-field/span 等）塞进 data-orig 属性，
        # 导致每行的 data-field/ident 等属性**重复出现两次**（一次在真实内容、
        # 一次在 data-orig 属性值里），既污染 DOM 计数、又让编辑回填比较失真
        # （拿高亮 HTML 与用户编辑的纯文本对比，永远不等）。
        A(f"<tr class=\"code-row{ln_cls}\" id=\"L{i}\">"
          f"<td class=\"ln\" data-ln=\"{i}\" title=\"点击复制本行链接\"># {i}</td>"
          f"<td class=\"code\"><span class=\"code-edit\" data-ln=\"{i}\" "
          f"data-orig=\"{html_mod.escape(line)}\">{code_html}</span>{extra}{diag}</td></tr>")
    A("</table></div>")
    A("</div>")
    A("</div>")
    # P-rev R80：变量流 + 源码行深链收编为站点共享 _pageview.js（不再逐页内联）。
    # 保留原注入点位置与顺序（紧随页面正文、早于下方两段初始化脚本），加载仍同步，
    # 行为与内联完全一致，但 N 个源码页共享同一份文件（浏览器只拉一次）。
    _pv_asset = _rel_to_src_asset(mf.rel, "_pageview.js")
    # 当前文件 rel：供 STRUCT_JUMP_JS 计算跨文件相对路径（点击结构体字段名跳转）。
    A("<script>window.__CURRENT_REL__=%s;</script>" % json.dumps(getattr(mf, "rel", "")))
    A("<script src=\"%s\" defer></script>" % html_mod.escape(_pv_asset))
    # 初始化本页所有「按需下钻」调用图容器（数据来自共享的 src/_cgdata.js）
    # 注意：_localcg.js / _cgdata.js 均为 defer 外部脚本，会在「文档解析完成后、
    # DOMContentLoaded 之前」才执行；此处若用普通内联脚本立即调用 initLocalCG，
    # 会遇到 initLocalCG 与 window.__CG__ 尚未定义 → 调用图永远渲染为空。
    # 因此必须等到 DOMContentLoaded（defer 脚本保证在此之前已执行）再初始化。
    A("<script>(function(){function __initCG(){if(window.initLocalCG){window.initLocalCG();}}"
      "if(document.readyState!=='loading'){__initCG();}"
      "else{document.addEventListener('DOMContentLoaded',__initCG);}})();</script>")
    # 从全局搜索「函数」模式跳转（带 ?expand=1）时自动展开调用关系图
    A("<script>if(location.search.indexOf('expand')>=0){"
      "document.querySelectorAll('details.callgraph').forEach(function(d){d.open=true;});}</script>")
    A("</main></body></html>")
    return "\n".join(lines)


def _render_hotspot_section(A, files, callers_of, calls_of, fn_to_file):
    """渲染首页「热点分析」：核心枢纽 / 高风险 / 孤立函数。"""
    funcs = [(mf, f) for mf in files for f in mf.functions
             if f.kind not in ("script", "local", "method")]
    # 被调用最多（核心枢纽）
    top_called = sorted(
        funcs,
        key=lambda x: (len(callers_of.get(id(x[1]), [])), x[1].complexity),
        reverse=True)[:10]
    # 复杂度最高（高风险）
    by_cx = sorted(funcs, key=lambda x: x[1].complexity, reverse=True)[:10]
    # 孤立函数：无调用方且无出向调用
    isolated = [x for x in funcs
                if not callers_of.get(id(x[1])) and not calls_of.get(id(x[1]))]

    def _item(mf, f, extra):
        return (f'<li><a href="{_src_href(mf)}#L{f.line}">'
                f'<code>{html_mod.escape(f.name)}</code></a>'
                f'<span class="muted"> {html_mod.escape(mf.rel)}</span> · {extra}</li>')

    A("<h2>热点分析（Hotspot Analysis）</h2>")
    A("<div class=\"muted\">圈复杂度 ≈ 分支点(if/for/while/switch/try/case…)+1。"
      "用于快速定位「改动风险高（被依赖多）」与「缺陷风险高（逻辑复杂）」的函数；"
      "孤立函数指既无调用方也无出向调用，可能是死代码或独立工具。</div>")
    A("<div class=\"hotspot\">")
    A("<div class=\"hs-col\"><h3>🔗 被调用最多（核心枢纽 Top 10）</h3><ol>")
    for mf, f in top_called:
        A(_item(mf, f, "被调用 %d" % len(callers_of.get(id(f), []))))
    A("</ol></div>")
    A("<div class=\"hs-col\"><h3>⚠ 复杂度最高（高风险 Top 10）</h3><ol>")
    for mf, f in by_cx:
        A(_item(mf, f, "复杂度 %d" % f.complexity))
    A("</ol></div>")
    A("<div class=\"hs-col\"><h3>🔌 孤立函数（%d 个）</h3><ul>" % len(isolated))
    for mf, f in isolated[:30]:
        A(_item(mf, f, "无调用方 / 无出向"))
    if len(isolated) > 30:
        A('<li class="muted">… 仅显示前 30 个</li>')
    A("</ul></div>")
    A("</div>")


def _render_callgraph_section(A, files, calls_of, callers_of, fn_to_file, max_nodes=1200):
    """渲染首页「交互式全局调用图」：节点=函数、边=调用关系（离线 SVG 力导向）。"""
    # 仅纳入实际参与调用的函数（脚本 / 局部 / 方法以及孤立函数不进图，
    # 孤立函数已在热点分析中单列）。项目过大时按 (被调用*2 + 调用) 取前 max_nodes。
    cands = []
    for mf in files:
        for f in mf.functions:
            if f.kind == "script":
                continue
            indeg = len(callers_of.get(id(f), []))
            outdeg = len(calls_of.get(id(f), []))
            if indeg + outdeg == 0:
                continue
            cands.append((mf, f, indeg, outdeg))
    if len(cands) > max_nodes:
        cands.sort(key=lambda x: x[2] * 2 + x[3], reverse=True)
        cands = cands[:max_nodes]

    idx_of = {}
    nodes = []
    for i, (mf, f, indeg, outdeg) in enumerate(cands):
        idx_of[id(f)] = i
        href = "%s#L%d" % (_src_href(mf), f.line)
        nodes.append({
            "name": f.name, "file": mf.rel, "line": f.line, "kind": f.kind,
            "cx": f.complexity, "inDeg": indeg, "outDeg": outdeg, "href": href,
            "d": (f.header.get("description", "") if isinstance(getattr(f, "header", None), dict) else "")
                  or "",   # 函数简要说明（P18：悬停展示）
        })
    seen = set()
    edges = []
    for (mf, f, _i, _o) in cands:
        si = idx_of[id(f)]
        for item in calls_of.get(id(f), []):
            callee_fn = item[0]          # calls_of 存的是 (callee_fn, dmf) 元组
            ti = idx_of.get(id(callee_fn))
            if ti is None:
                continue
            key = (si, ti)
            if key in seen:
                continue
            seen.add(key)
            edges.append([si, ti])
    if not nodes:
        return
    max_in = max((nd["inDeg"] for nd in nodes), default=1)
    graph_data = {"nodes": nodes, "edges": edges, "maxIn": max_in}

    A("<h2>交互式全局调用图（Interactive Call Graph）</h2>")
    A("<div class=\"muted\">节点 = 函数（圆点大小随「被调用数」增大，颜色越红表示被依赖越多 / "
      "改动风险越高）；边 = 调用关系（A→B 表示 A 调用 B）。可滚轮缩放、拖拽空白处平移、"
      "拖动节点重新布局、悬停高亮邻居并查看详情、双击节点解除固定、点击节点跳转源码。"
      "孤立函数不在图中（见上方热点分析）。</div>")
    A("<div class=\"cg-ctrl\">")
    A("<label>最小被调用数 "
      "<input type=\"range\" id=\"cg-min\" min=\"0\" max=\"%d\" value=\"0\" data-cg-act=\"cgFilter\"> "
      "<span id=\"cg-minv\">0</span></label>" % max_in)
    A("<label><input type=\"checkbox\" id=\"cg-lbl\" data-cg-act=\"cgToggleLabels\"> 显示全部标签</label>")
    A("<button data-cg-act=\"cgRelayout\">重新布局</button>" + _CG_DELEGATE_JS)
    A("<span class=\"cg-zoombar\">"
      "<button type=\"button\" id=\"cg-zout\" title=\"缩小\">−</button>"
      "<span class=\"cg-zoom-pct\" id=\"cg-zoom-pct\">100%</span>"
      "<button type=\"button\" id=\"cg-zin\" title=\"放大\">+</button>"
      "<button type=\"button\" id=\"cg-zreset\" title=\"复位视图\">复位</button>"
      "</span>")
    A("<span class=\"muted\" id=\"cg-stat\"></span>")
    A("</div>")
    A("<div class=\"cg-wrap\">"
      "<svg id=\"cg-svg\"><g id=\"cg-g\"></g></svg>"
      "<div id=\"cg-tip\" class=\"cg-tip\"></div></div>")
    A("<div class=\"cg-legend\">被调用数（热度）："
      "<span class=\"bar\"></span> 低 → 高</div>")
    A("<script>var CG_DATA = %s;</script>" % json.dumps(graph_data, ensure_ascii=False))
    A("<script>%s</script>" % GRAPH_JS)


def _site_nav_html(active, ai):
    """浏览站点顶部全局导航（分组 + 移动端折叠），索引页与各子页统一复用。

    active：当前页 key（与导航项 key 对应），用于高亮当前位置。
    ai：是否启用 AI 分析页（决定是否显示「AI 分析」入口）。
    """
    _groups = [
        ("浏览", [
            ("index.html", "首页", "index"),
            ("class_hierarchy.html", "类层次", "class_hierarchy"),
            ("members.html", "成员索引", "members"),
            ("annotations.html", "注释标签", "annotations"),
        ]),
        ("分析", [
            ("checks.html", "静态检查", "checks"),
            ("compliance.html", "审查工作台", "compliance"),
            ("complexity.html", "复杂度热力", "complexity"),
            ("dir_matrix.html", "目录耦合", "dir_matrix"),
            ("taint.html", "污点分析", "taint"),
            ("todo.html", "待办清单", "todo"),
            ("c_report.html", "C报告", "c_report"),
            ("metrics.html", "风险度量", "metrics"),
            ("unresolved.html", "疑似漏检", "unresolved"),
        ]),
        ("视图", [
            ("matlab_lib.html", "库函数", "matlab_lib"),
            ("dims.html", "维度视图", "dims"),
            ("dims_check.html", "维度联动", "dims_check"),
            ("struct_members.html", "结构体成员", "struct_members"),
            ("operator_impact.html", "算子影响", "operator_impact"),
            ("calibration.html", "定标分析", "calibration"),
            ("overview.html", "分析总览", "overview"),
        ]),
        ("图", [
            ("callgraph.svg", "调用图", "callgraph"),
            ("combined_graph.svg", "分层图", "combined_graph"),
            ("unified.html", "统一图", "unified"),
            ("folder_impact.html", "影响面", "folder_impact"),
            ("var_taint.html", "污点溯源", "var_taint"),
        ]),
    ]
    _parts = []
    for _gname, _items in _groups:
        _links = []
        for _href, _label, _key in _items:
            _cls = "nav-link" + (" active" if _key == active else "")
            _links.append('<a class="%s" href="%s">%s</a>' % (_cls, _href, _label))
        if ai and _gname == "视图":
            _links.append('<a class="nav-link" href="ai_prompts.html">AI 分析</a>')
        _parts.append('<div class="nav-group"><span class="nav-group-label">%s</span>%s</div>'
                      % (_gname, "".join(_links)))
    _search = ('<a class="nav-link" id="nav-search" href="#" role="button" '
               'aria-label="打开搜索面板（Ctrl+K 或 /）" title="搜索（Ctrl+K / /）">搜索</a>')
    return ('<button class="nav-toggle" id="nav-toggle" aria-label="展开/收起导航" '
            'aria-expanded="false">导航菜单</button>'
            '<nav class="topnav" id="topnav">' + "".join(_parts) + _search + '</nav>')


def _site_header_html(active, ai):
    """浏览站点统一页眉（品牌 + 分组导航 + 移动端折叠开关）。"""
    return ('<header class="site-header"><span class="brand">MATLAB 源码浏览</span>'
            + _site_nav_html(active, ai) + '</header>')


def render_browse_index(files, index, callers_of, stats, root, rel, calls_of=None,
                        fn_to_file=None, reproducible=False, empty_dirs=None, ai=False):
    """渲染浏览站点索引页：目录树 + 全量函数索引 + 类汇总。

    reproducible=True 时省略生成时间戳（P51）。
    empty_dirs：空目录相对路径列表（P75，目录树纳入空目录）。
    """
    lines = []
    A = lines.append
    # P224-Z：站点首页展示渲染降级清单（若有），使单页异常可观测而非静默。
    if _RENDER_ERRORS:
        A('<div class="render-errors" style="background:#fff4f4;border:1px solid '
          '#f3c2c2;color:#9b1c1c;padding:8px 12px;margin:8px 0;border-radius:6px;">'
          '<b>⚠ 渲染异常降级</b>：本次有 %d 个页面因渲染错误被降级为占位页'
          '（其余页面正常）。错误清单：<ul style="margin:4px 0 0;">'
          % len(_RENDER_ERRORS))
        for _n, _e in _RENDER_ERRORS[:30]:
            A('<li><code>%s</code>: %s</li>' % (_html_esc(_n), _html_esc(_e)))
        A('</ul></div>')
    A("<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
      "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">")
    A("<title>MATLAB 源码浏览索引</title>")
    A('<link rel="stylesheet" href="src/styles.css">')
    A("</head><body>")
    A('<a class="skip-link" href="#main-content">跳到主内容</a>')
    A(_site_header_html("index", ai))
    A('<script>'
      '(function(){var t=document.getElementById("nav-toggle");'
      'var n=document.getElementById("topnav");'
      'if(t&&n){t.addEventListener("click",function(){'
      'var o=n.classList.toggle("open");'
      't.setAttribute("aria-expanded",o?"true":"false");});}})();'
      '</script>')
    A("<main id=\"main-content\">")
    A(f"<h1>MATLAB 代码结构 — 交互式浏览</h1>")
    A(f"<div class=\"muted\">目录：{html_mod.escape(str(root))} · 生成时间 {_timestamp(reproducible)}</div>")
    A("<div style=\"margin:16px 0\">")
    A(f"<span class=\"stat\"><b>{stats['files']}</b>文件</span>")
    A(f"<span class=\"stat\"><b>{stats['functions']}</b>函数</span>")
    A(f"<span class=\"stat\"><b>{stats['classes']}</b>类</span>")
    A(f"<span class=\"stat\"><b>{stats['internal_edges']}</b>调用边</span>")
    A(f"<span class=\"stat\"><b>{stats['total_lines']}</b>代码行</span>")
    A("</div>")

    # P-rev S1：任务向导——首页从「功能陈列」升级为「任务主线」，引导用户从
    # 「理解 → 审查 → 风险 → 依赖」一键进入预置视图（brainstorming：为用户的真实任务设计）
    A("<h2>我想做什么？</h2>")
    A("<div class=\"wizard\">")
    A('<a class="task" href="#tree">'
      '<div class="ico">🧭</div><h3>理解这个工程</h3>'
      '<p>从目录结构、函数索引、类层次入手，快速建立全局认知。</p>'
      '<span class="go">↓ 浏览目录结构</span></a>')
    A('<a class="task is-review" href="compliance.html">'
      '<div class="ico">✅</div><h3>审查代码质量</h3>'
      '<p>按 MathWorks 官方标准逐项给出「必须改 / 应该改 / 可改」及改法。</p>'
      '<span class="go">打开审查工作台 →</span></a>')
    A('<a class="task is-risk" href="metrics.html">'
      '<div class="ico">🔥</div><h3>追踪高风险点</h3>'
      '<p>复杂度 / 扇入 / 重复代码热力图，定位最该先动的代码。</p>'
      '<span class="go">打开风险度量 →</span></a>')
    A('<a class="task is-dep" href="unified.html">'
      '<div class="ico">🕸️</div><h3>理清依赖关系</h3>'
      '<p>统一画布（文件夹 / 文件 / 函数 / 变量 + 包含 / 数据流 / 调用）。</p>'
      '<span class="go">打开统一画布 →</span></a>')
    A("</div>")
    A("<p class=\"hint-row\">提示：随时按 <code>Ctrl+K</code> / <code>/</code> 搜索函数、文件、全文；"
      "按 <code>?</code> 查看全部快捷键。</p>")

    # 目录树（文件可点击，目录加目录页链接，空目录纳入展示）
    A("<h2>目录结构</h2>")
    A("<div class=\"tree\">")
    A(render_tree_browse([(f.rel, f.kind) for f in files],
                         empty_dirs=empty_dirs))
    A("</div>")

    # 文件夹级调用统计
    if calls_of is not None:
        folder_stats = _compute_folder_stats(files, callers_of, calls_of)
        if folder_stats:
            A("<h2>文件夹调用统计</h2>")
            A("<div class=\"folder-stats\"><table>")
            A("<tr><th>目录</th><th>文件数</th><th>函数数</th><th>类数</th>"
              "<th>内部调用边</th><th>跨目录出</th><th>跨目录入</th><th>入口函数</th></tr>")
            for fs in folder_stats:
                dir_name = html_mod.escape(fs["dir"])
                entries_html = ""
                if fs["entry_funcs"]:
                    entry_items = []
                    for emf, ef in fs["entry_funcs"][:8]:
                        entry_items.append(
                            f'<a href="{_src_href(emf)}#L{ef.line}">'
                            f'{html_mod.escape(ef.name)}</a>')
                    if len(fs["entry_funcs"]) > 8:
                        entry_items.append(f'<span class="muted">+{len(fs["entry_funcs"])-8}</span>')
                    entries_html = '<div class="fs-entry-list">' + ", ".join(entry_items) + "</div>"
                entry_cell = entries_html if entries_html else '<span class="muted">-</span>'
                A(f"<tr>"
                  f"<td><b>{dir_name}</b></td>"
                  f"<td>{fs['n_files']}</td><td>{fs['n_funcs']}</td><td>{fs['n_classes']}</td>"
                  f"<td>{fs['n_internal_edges']}</td>"
                  f"<td>{fs['n_cross_out']}</td><td>{fs['n_cross_in']}</td>"
                  f"<td>{entry_cell}</td></tr>")
            A("</table></div>")

    # 文件夹依赖关系（目录间调用边 + 扇出/扇入汇总，P60）
    if calls_of is not None:
        _render_folder_deps_section(A, files, calls_of)

    # 热点分析（被调用最多 / 复杂度最高 / 孤立函数）
    if calls_of is not None and fn_to_file is not None:
        _render_hotspot_section(A, files, callers_of, calls_of, fn_to_file)

    # 交互式全局调用图（离线 SVG 力导向）
    if calls_of is not None and fn_to_file is not None:
        _render_callgraph_section(A, files, calls_of, callers_of, fn_to_file)

    # 函数索引（C3：按目录分组，doxygen 文件列表风格，可折叠）
    A("<h2>函数索引</h2>")
    funcs_sorted = sorted(
        ((mf, f) for mf in files for f in mf.functions if f.kind != "script"),
        key=lambda x: (x[0].rel.lower(), x[1].line))
    by_dir = defaultdict(list)
    for mf, f in funcs_sorted:
        d = os.path.dirname(mf.rel) or "(root)"
        by_dir[d].append((mf, f))
    _tbl_i = 0   # P-rev R76：每组目录一张函数表，id 逐组递增保证全局唯一
    for d in sorted(by_dir.keys()):
        items = by_dir[d]
        _tbl_i += 1
        A('<details class="fn-group" open><summary><b>%s</b> <span class="muted">（%d 函数）</span>'
          '</summary>' % (html_mod.escape(d), len(items)))
        A('<table id="fn-table-%d">'
          '<tr><th>函数</th><th>类型</th><th>文件</th><th>行</th><th>签名</th>'
          '<th>调用</th><th>被调用</th><th>复杂度</th></tr>' % _tbl_i)
        for mf, f in items:
            n_callers = len(callers_of.get(id(f), []))
